                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar - 3 Seconds */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_3s_linear] w-full origin-left" style={{ animationDuration: '3s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Toggle Camera */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <Camera className="w-4 h-4 text-gray-400" />}

           {isFollowingBet ? (
               <div className="flex items-center space-x-2">
                   <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                       <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
                   </div>
                   <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
               </div>
           ) : (
               <span className="text-gray-300 font-bold uppercase text-sm">CÂMERA: LÍDER</span>
           )}
        </button>
      )}

    </div>
  );
}

{
  "name": "Marble Royale",
  "description": "Um jogo de corrida de bolinhas com eliminação, apostas e física realista.",
  "requestFramePermissions": [
    "accelerometer",
    "gyroscope",
    "magnetometer"
  ]
}

import React, { useEffect, useRef, useState } from 'react';
import { ArrowLeft, Smartphone, Trophy, AlertCircle } from 'lucide-react';

interface Team {
  id: number;
  name: string;
  color: string;
  logoUrl: string;
}

interface PongGameProps {
  playerTeam: Team;
  opponentTeam: Team;
  onExit: () => void;
}

const PongGame: React.FC<PongGameProps> = ({ playerTeam, opponentTeam, onExit }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Game State Refs (Mutable for high-performance loop)
  // Coordinates are in % (0-100) to be responsive
  const ball = useRef({ x: 50, y: 50, vx: 0, vy: 0, speed: 0.8, radius: 2 }); 
  const player = useRef({ x: 50, width: 25, score: 0 }); 
  const ai = useRef({ x: 50, width: 25, score: 0, speed: 0.9 }); 

  const [gameState, setGameState] = useState<'start' | 'playing' | 'finished'>('start');
  const [winner, setWinner] = useState<Team | null>(null);
  const [sensorStatus, setSensorStatus] = useState<string>('Inativo');
  const [sensorVal, setSensorVal] = useState<number>(0);

  const WIN_SCORE = 5;

  // --- Physics Engine ---
  const resetBall = (server: 'player' | 'ai') => {
    ball.current.x = 50;
    ball.current.y = 50;
    ball.current.speed = 0.8;
    // Randomize start angle slightly
    const angle = (Math.random() - 0.5) * 1.5; 
    const dir = server === 'player' ? -1 : 1; // Send towards opponent

    // Normalize velocity
    ball.current.vx = Math.sin(angle) * ball.current.speed;
    ball.current.vy = Math.cos(angle) * ball.current.speed * dir;
  };

  const updatePhysics = () => {
    if (gameState !== 'playing') return;

    const b = ball.current;
    const p = player.current;
    const a = ai.current;

    // 1. Move Ball
    b.x += b.vx;
    b.y += b.vy;

    // 2. Wall Collisions (Left/Right)
    if (b.x <= 0 || b.x >= 100) {
        b.vx *= -1;
        b.x = Math.max(0, Math.min(100, b.x));
    }

    // 3. Paddle Collisions
    // Player (Bottom)
    if (b.y >= 92 && b.y <= 95) {
        if (b.x >= p.x - p.width/2 && b.x <= p.x + p.width/2) {
            // Hit!
            b.y = 92;
            b.vy = -Math.abs(b.vy) * 1.05; // Bounce up
            b.speed *= 1.05;

            // Add "English" (spin) based on where it hit the paddle
            const hitPoint = (b.x - p.x) / (p.width / 2); // -1 to 1
            b.vx = hitPoint * 1.5; // Steer ball
        }
    }

    // AI (Top)
    if (b.y <= 8 && b.y >= 5) {
        if (b.x >= a.x - a.width/2 && b.x <= a.x + a.width/2) {
             // Hit!
             b.y = 8;
             b.vy = Math.abs(b.vy) * 1.05; // Bounce down
             b.speed *= 1.05;

             const hitPoint = (b.x - a.x) / (a.width / 2);
             b.vx = hitPoint * 1.5;
        }
    }

    // 4. Scoring
    if (b.y > 100) {
        // AI Scored
        a.score += 1;
        if (a.score >= WIN_SCORE) {
            setWinner(opponentTeam);
            setGameState('finished');
        } else {
            resetBall('player');
        }
    } else if (b.y < 0) {
        // Player Scored
        p.score += 1;
        if (p.score >= WIN_SCORE) {
            setWinner(playerTeam);
            setGameState('finished');
        } else {
            resetBall('ai');
        }
    }

    // 5. AI Movement
    // Simple tracking with reaction delay simulation
    const targetX = b.y < 60 ? b.x : 50; // Only track if ball is in AI half or returning to center
    const dx = targetX - a.x;

    // AI Speed limit
    if (Math.abs(dx) > a.speed) {
        a.x += Math.sign(dx) * a.speed;
    } else {
        a.x = targetX;
    }
    a.x = Math.max(a.width/2, Math.min(100 - a.width/2, a.x));
  };

  // --- Rendering ---
  const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      // Clear
      ctx.fillStyle = '#111827';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Scale factors
      const w = canvas.width;
      const h = canvas.height;
      const scalex = (val: number) => (val / 100) * w;
      const scaley = (val: number) => (val / 100) * h;

      // Draw Court Lines
      ctx.strokeStyle = '#374151';
      ctx.lineWidth = 2;
      ctx.setLineDash([10, 10]);
      ctx.beginPath();
      ctx.moveTo(0, h/2);
      ctx.lineTo(w, h/2);
      ctx.stroke();
      ctx.setLineDash([]);

      // Draw Center Circle
      ctx.beginPath();
      ctx.arc(w/2, h/2, w * 0.15, 0, Math.PI*2);
      ctx.stroke();

      // Draw Paddles
      const p = player.current;
      const a = ai.current;

      // Player Paddle
      ctx.fillStyle = playerTeam.color;
      ctx.shadowColor = playerTeam.color;
      ctx.shadowBlur = 10;
      ctx.fillRect(
          scalex(p.x - p.width/2), 
          scaley(93), 
          scalex(p.width), 
          scaley(2)
      );

      // AI Paddle
      ctx.fillStyle = opponentTeam.color;
      ctx.shadowColor = opponentTeam.color;
      ctx.fillRect(
          scalex(a.x - a.width/2), 
          scaley(5), 
          scalex(a.width), 
          scaley(2)
      );
      ctx.shadowBlur = 0;

      // Draw Ball
      const b = ball.current;
      ctx.fillStyle = '#fff';
      ctx.beginPath();
      ctx.arc(scalex(b.x), scaley(b.y), scalex(b.radius), 0, Math.PI*2);
      ctx.fill();

      // Draw Scores (Background)
      ctx.fillStyle = 'rgba(255,255,255,0.1)';
      ctx.font = 'bold 80px "Righteous"';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';

      // AI Score
      ctx.fillText(a.score.toString(), w/2, h * 0.25);

      // Player Score
      ctx.fillText(p.score.toString(), w/2, h * 0.75);
  };

  const loop = () => {
      updatePhysics();
      draw();
      requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => {
      requestRef.current = requestAnimationFrame(loop);
      return () => cancelAnimationFrame(requestRef.current!);
  }, [gameState]);


  // --- Sensor Logic ---
  const handleOrientation = (e: DeviceOrientationEvent) => {
    // Standardize Gamma (Left/Right tilt)
    // Some devices use 0-360 range for alpha/beta/gamma differently?
    // Usually gamma is -90 to 90.

    let tilt = e.gamma || 0;

    // Fix for when device is held upside down or weird orientations
    if (Math.abs(tilt) > 90) tilt = Math.sign(tilt) * 90;

    setSensorVal(Math.round(tilt));
    setSensorStatus('Ativo');

    // Map tilt (-30 to 30) to screen position (0 to 100)
    const clampedTilt = Math.max(-30, Math.min(30, tilt));
    const targetPos = ((clampedTilt + 30) / 60) * 100;

    // Smooth update (Low pass filter)
    const smoothing = 0.2;
    player.current.x = player.current.x + (targetPos - player.current.x) * smoothing;

    // Boundary check
    player.current.x = Math.max(player.current.width/2, Math.min(100 - player.current.width/2, player.current.x));
  };

  const handleTouchMove = (e: React.TouchEvent) => {
      const canvas = canvasRef.current;
      if (!canvas) return;

      const rect = canvas.getBoundingClientRect();
      const touchX = e.touches[0].clientX - rect.left;

      // Map pixels to 0-100 percentage
      const percent = (touchX / rect.width) * 100;

      player.current.x = Math.max(player.current.width/2, Math.min(100 - player.current.width/2, percent));
      setSensorStatus('Toque');
  };

  const requestAccess = async () => {
    // Try Sensor Access
    setSensorStatus('Solicitando...');

    if (typeof (DeviceOrientationEvent as any).requestPermission === 'function') {
        try {
            const permission = await (DeviceOrientationEvent as any).requestPermission();
            if (permission === 'granted') {
                window.addEventListener('deviceorientation', handleOrientation);
                setSensorStatus('Conectado (iOS)');
                startGame();
            } else {
                setSensorStatus('Negado (Toque para jogar)');
                startGame(); // Allow playing with touch anyway
            }
        } catch (e) {
            console.error(e);
            setSensorStatus('Erro (Toque para jogar)');
            startGame();
        }
    } else {
        // Android / PC
        window.addEventListener('deviceorientation', handleOrientation);
        // Fallback or additional listener for absolute orientation on some Androids
        window.addEventListener('deviceorientationabsolute', (e: any) => handleOrientation(e));

        // Wait a split second to see if we get data
        setTimeout(() => {
            if (sensorStatus !== 'Ativo') {
                 setSensorStatus('Aguardando/Toque');
            }
        }, 500);

        startGame();
    }
  };

  const startGame = () => {
      setGameState('playing');
      resetBall('ai');
  };

  useEffect(() => {
    return () => {
        window.removeEventListener('deviceorientation', handleOrientation);
    };
  }, []);

  return (
    <div className="fixed inset-0 z-50 bg-gray-900 flex flex-col">
      {/* Header */}
      <div className="flex justify-between items-center p-4 bg-gray-800 border-b border-gray-700 shadow-md z-10">
          <button onClick={onExit} className="p-2 bg-gray-700 hover:bg-gray-600 rounded-full text-white transition-colors">
              <ArrowLeft />
          </button>
          <div className="text-center">
              <h2 className="text-yellow-400 font-brand text-xl tracking-widest">PONG ARENA</h2>
              <div className="text-[10px] text-gray-500 font-mono">
                  Sensor: {sensorStatus} {sensorStatus === 'Ativo' && `(${sensorVal}°)`}
              </div>
          </div>
          <div className="w-10"></div> 
      </div>

      {/* Canvas Container */}
      <div 
        className="flex-1 relative bg-black touch-none"
        onTouchMove={handleTouchMove} // Fallback Control
      >
          <canvas 
            ref={canvasRef} 
            width={400} 
            height={600} 
            className="w-full h-full object-contain block"
          />

          {/* Start Overlay */}
          {gameState === 'start' && (
              <div className="absolute inset-0 bg-black/80 flex flex-col items-center justify-center p-6 text-center z-20">
                  <div className="bg-gray-800 p-8 rounded-2xl border border-gray-700 shadow-2xl max-w-sm w-full">
                    <Smartphone className="w-16 h-16 text-blue-400 mb-4 mx-auto animate-bounce" />
                    <h3 className="text-2xl font-bold text-white mb-2">Controle por Sensor</h3>
                    <p className="text-gray-400 text-sm mb-6 leading-relaxed">
                        Incline seu celular para os lados para mover a barra.
                        <br/>
                        <span className="text-xs text-gray-500 mt-2 block">(Caso o sensor não funcione, arraste com o dedo na tela)</span>
                    </p>
                    <button 
                        onClick={requestAccess}
                        className="w-full py-4 bg-gradient-to-r from-blue-600 to-blue-500 rounded-xl font-bold text-white text-lg shadow-lg hover:shadow-blue-500/50 transition-all transform hover:scale-105"
                    >
                        INICIAR PARTIDA
                    </button>
                  </div>
              </div>
          )}

          {/* Game Over Overlay */}
          {gameState === 'finished' && winner && (
              <div className="absolute inset-0 bg-black/90 flex flex-col items-center justify-center p-6 text-center animate-fadeIn z-20">
                  <Trophy className={`w-24 h-24 mb-6 ${winner.id === playerTeam.id ? 'text-yellow-400 drop-shadow-[0_0_15px_rgba(250,204,21,0.5)]' : 'text-gray-600'}`} />
                  <h2 className="text-5xl font-black text-white mb-2 uppercase brand-font tracking-wider">
                      {winner.id === playerTeam.id ? 'VITÓRIA!' : 'DERROTA'}
                  </h2>
                  <p className="text-xl text-gray-400 mb-10 font-mono">
                      {winner.id === playerTeam.id 
                        ? `O ${playerTeam.name} é imbatível!` 
                        : `O ${opponentTeam.name} levou a melhor.`}
                  </p>
                  <div className="flex flex-col space-y-4 w-full max-w-xs">
                    <button 
                        onClick={() => {
                            player.current.score = 0;
                            ai.current.score = 0;
                            setGameState('playing');
                            resetBall('ai');
                        }}
                        className="w-full py-4 bg-white text-black font-bold rounded-xl hover:bg-gray-200 transition-colors"
                    >
                        JOGAR NOVAMENTE
                    </button>
                    <button 
                        onClick={onExit}
                        className="w-full py-4 bg-transparent text-gray-400 font-bold rounded-xl border border-gray-600 hover:border-white hover:text-white transition-all"
                    >
                        VOLTAR AO MENU
                    </button>
                  </div>
              </div>
          )}
      </div>
    </div>
  );
};

