                                         <Trophy className="w-16 h-16 text-yellow-400 mx-auto animate-bounce" />
                                         <p className="text-yellow-400 font-bold mt-2">CAMPEÃO!</p>
                                     </div>
                                )}
                            </div>
                        </div>

                    </div>
