  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

function shuffle<T>(array: T[]): T[] {
  const newArr = [...array];
  for (let i = newArr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
  }
  return newArr;
}

// --- STATISTICS TYPES ---
interface MatchStats {
    completed: number;
    interrupted: number;
}

interface TeamStats {
    titles: { total: number; elimination: number; points: number; cup: number };
    points: { total: number; elimination: number; points: number; cup: number };
    raceWins: { total: number; elimination: number; points: number; cup: number };
}

interface Statistics {
    matches: {
        total: MatchStats;
        elimination: MatchStats;
        points: MatchStats;
        cup: MatchStats;
    };
    teams: Record<number, TeamStats>;
}

const getInitialStats = (): Statistics => {
    const stats: Statistics = {
        matches: {
            total: { completed: 0, interrupted: 0 },
            elimination: { completed: 0, interrupted: 0 },
            points: { completed: 0, interrupted: 0 },
            cup: { completed: 0, interrupted: 0 }
        },
        teams: {} 
    };
    TEAMS.forEach((_, i) => {
        stats.teams[i] = {
            titles: { total: 0, elimination: 0, points: 0, cup: 0 },
            points: { total: 0, elimination: 0, points: 0, cup: 0 },
            raceWins: { total: 0, elimination: 0, points: 0, cup: 0 }
        };
    });
    return stats;
};

export default function App() {
  const [statistics, setStatistics] = useState<Statistics>(() => {
      const saved = localStorage.getItem('marble_royale_stats_v1');
      const base = getInitialStats();
      if (saved) {
          try {
            const parsed = JSON.parse(saved);
            return { 
                ...base, 
                matches: { ...base.matches, ...parsed.matches }, 
                teams: { ...base.teams, ...parsed.teams } 
            };
          } catch (e) {
            return base;
          }
      }
      return base;
  });

  const saveStats = (newStats: Statistics) => {
      setStatistics(newStats);
      localStorage.setItem('marble_royale_stats_v1', JSON.stringify(newStats));
  };

  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: TEAMS.length - 1, 
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {},
    cupMatches: [],
    currentMatchIndex: 0,
    cupGroups: [],
    cupScores: {},
    cupPhase: 'groups'
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [obstacleSettings] = useState<ObstacleSettings>({
    spinner: true,
    slider: true,
    repulsor: true,
    conveyor: true,
    teleporter: true,
    hollow_circle: true,
    laser: true,
    fan: true,
    funnel: true
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [showStatisticsModal, setShowStatisticsModal] = useState(false);
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  const recordMatchInterruption = () => {
      const newStats: Statistics = JSON.parse(JSON.stringify(statistics));
      const mode = gameState.gameMode;
      newStats.matches.total.interrupted++;
      newStats.matches[mode].interrupted++;
      saveStats(newStats);
  };

  const recordMatchCompletion = (winnerId: number) => {
      const newStats: Statistics = JSON.parse(JSON.stringify(statistics));
      const mode = gameState.gameMode;
      newStats.matches.total.completed++;
      newStats.matches[mode].completed++;
      if (newStats.teams[winnerId]) {
          newStats.teams[winnerId].titles.total++;
          newStats.teams[winnerId].titles[mode]++;
      }
      saveStats(newStats);
  };

  const recordRoundStats = (results: Marble[], roundPoints: Record<number, number>) => {
      const newStats: Statistics = JSON.parse(JSON.stringify(statistics));
      const mode = gameState.gameMode;
      if (results.length > 0) {
          const winnerId = results[0].id;
          if (newStats.teams[winnerId]) {
              newStats.teams[winnerId].raceWins.total++;
              newStats.teams[winnerId].raceWins[mode]++;
          }
      }
      Object.entries(roundPoints).forEach(([idStr, points]) => {
          const id = parseInt(idStr);
          if (newStats.teams[id]) {
              newStats.teams[id].points.total += points;
              newStats.teams[id].points[mode] += points;
          }
      });
      saveStats(newStats);
  };

  const resetStatistics = () => {
      if (window.confirm("Tem certeza que deseja apagar todo o histórico de partidas?")) {
          const reset = getInitialStats();
          saveStats(reset);
      }
  };

  const generateCupSchedule = (marbleIds: number[]) => {
      const shuffled = shuffle(marbleIds);
      const groups = [shuffled.slice(0, 5), shuffled.slice(5, 10), shuffled.slice(10, 15), shuffled.slice(15, 20)];
      const matches: Match[] = [];
      const groupNames = ['A', 'B', 'C', 'D'];
      for (let r = 1; r <= 5; r++) {
          groups.forEach((groupIds, gIdx) => {
              matches.push({
                  id: `g${gIdx}_r${r}`,
                  name: `Grupo ${groupNames[gIdx]} - Rodada ${r}`,
                  marbleIds: groupIds,
                  type: 'group',
                  groupIndex: gIdx,
                  nextPhase: (r === 5 && gIdx === 3)
              });
          });
      }
      return { groups, matches };
  };

  const generateKnockoutMatches = (qualifiers: number[], phaseName: string) => {
      const matches: Match[] = [];
      for (let i = 0; i < qualifiers.length; i += 2) {
          matches.push({
              id: `${phaseName}_${i}`,
              name: `${phaseName} - Jogo ${Math.floor(i/2) + 1}`,
              marbleIds: [qualifiers[i], qualifiers[i+1]],
              type: 'knockout',
              nextPhase: (i === qualifiers.length - 2)
          });
      }
      return matches;
  };

  const handleModeSelect = (mode: GameMode) => {
    let newTotalRounds = 0;
    if (mode === 'elimination') newTotalRounds = TEAMS.length - 1;
    if (mode === 'points') newTotalRounds = 10;
    if (mode === 'cup') newTotalRounds = 35;
    setGameState(prev => ({ ...prev, gameMode: mode, totalRounds: newTotalRounds }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;
    if (gameState.gameMode === 'cup') {
        const { groups, matches } = generateCupSchedule(gameState.marbles.map(m => m.id));
        setGameState(prev => ({
            ...prev,
            phase: 'cup_tree',
            cupGroups: groups,
            cupMatches: matches,
            currentMatchIndex: 0,
            cupScores: {},
            cupPhase: 'groups',
            activeMarbleIds: matches[0].marbleIds,
            round: 1
        }));
    } else {
        setGameState(prev => ({ ...prev, phase: 'racing' }));
        audio.init();
        audio.resume();
        setIsPaused(false);
        setShowExitConfirm(false);
        setIsFollowingBet(false);
    }
  };

  const handleStartCupRacing = () => {
      setGameState(prev => ({ ...prev, phase: 'racing' }));
      audio.init();
      audio.resume();
      setIsPaused(false);
      setShowExitConfirm(false);
      setIsFollowingBet(false);
  };

  const handleExitTournament = () => {
      recordMatchInterruption();
      resetGame();
  };

  const handleSimulateMatch = () => {
      if (gameState.gameMode !== 'cup') return;
      const currentMatch = gameState.cupMatches[gameState.currentMatchIndex];
      if (!currentMatch) return;
      const matchMarbles: Marble[] = gameState.marbles.filter(m => currentMatch.marbleIds.includes(m.id));
      const shuffledResults = shuffle<Marble>(matchMarbles).map((m, i) => ({
          ...m,
          rank: i + 1,
          finished: true,
          finishTime: i * 100
      }));
      handleRaceFinish(shuffledResults);
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'cup') {
        handleCupRaceFinish(results);
        return;
    }
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      recordRoundStats(results, {});
      setGameState(prev => ({ ...prev, phase: 'round_result', lastEliminatedId: loser.id, roundPoints: {} }));
    } else {
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];
      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = { ...updatedMarbles[marbleIndex], score: updatedMarbles[marbleIndex].score + points, rank: index + 1, finished: true, finishTime: m.finishTime || index };
        }
      });
      audio.playFinish();
      recordRoundStats(results, currentRoundPoints);
      setGameState(prev => ({ ...prev, marbles: updatedMarbles, phase: 'round_result', roundPoints: currentRoundPoints }));
    }
  };

  const handleCupRaceFinish = (results: Marble[]) => {
      const match = gameState.cupMatches[gameState.currentMatchIndex];
      const newScores = { ...gameState.cupScores };
      const updatedMarbles = [...gameState.marbles];
      results.forEach((m, idx) => {
          let points = 0;
          if (match.type === 'group') {
              points = CUP_GROUP_POINTS[idx] || 0;
              newScores[m.id] = (newScores[m.id] || 0) + points;
          } else {
              if (idx === 0) points = 1; 
              newScores[m.id] = points;
          }
          const mIdx = updatedMarbles.findIndex(mar => mar.id === m.id);
          if (mIdx !== -1) {
              updatedMarbles[mIdx] = { ...updatedMarbles[mIdx], score: newScores[m.id], rank: idx + 1, finished: true, finishTime: m.finishTime || idx };
          }
      });
      const roundPointsForStats: Record<number, number> = {};
      results.forEach((m, idx) => {
          if (match.type === 'group') roundPointsForStats[m.id] = CUP_GROUP_POINTS[idx] || 0;
          else roundPointsForStats[m.id] = (idx === 0 ? 1 : 0);
      });
      recordRoundStats(results, roundPointsForStats);
      let nextPhase = gameState.cupPhase;
      let nextMatches = [...gameState.cupMatches];
      if (match.nextPhase) {
          if (gameState.cupPhase === 'groups') {
              nextPhase = 'octavas';
              const qualifiers: number[] = [];
              gameState.cupGroups.forEach(group => {
                  const sorted = group.sort((a, b) => (newScores[b] || 0) - (newScores[a] || 0));
                  qualifiers.push(...sorted.slice(0, 4));
              });
              const finalQualifiers: number[] = [];
              for(let i=0; i<4; i++) { finalQualifiers.push(gameState.cupGroups[0][i]); finalQualifiers.push(gameState.cupGroups[1][3-i]); }
              for(let i=0; i<4; i++) { finalQualifiers.push(gameState.cupGroups[2][i]); finalQualifiers.push(gameState.cupGroups[3][3-i]); }
              nextMatches = [...nextMatches, ...generateKnockoutMatches(finalQualifiers, "Oitavas")];
          } else if (gameState.cupPhase === 'octavas') { nextPhase = 'quartas'; }
      }
      const currentMatchIdx = gameState.currentMatchIndex;
      const finishedMatch = { ...match, winnerId: results[0].id };
      nextMatches[currentMatchIdx] = finishedMatch;
      if (match.nextPhase) {
          let winners: number[] = [];
          if (gameState.cupPhase === 'octavas') {
              const octavasMatches = nextMatches.filter(m => m.name.includes("Oitavas"));
              octavasMatches.sort((a, b) => parseInt(a.id.split('_')[1] || "0") - parseInt(b.id.split('_')[1] || "0"));
              winners = octavasMatches.map(m => m.winnerId!).filter(id => id !== undefined);
              nextMatches = [...nextMatches, ...generateKnockoutMatches(winners, "Quartas")];
              nextPhase = 'quartas';
          } else if (gameState.cupPhase === 'quartas') {
              const quartasMatches = nextMatches.filter(m => m.name.includes("Quartas"));
              quartasMatches.sort((a, b) => parseInt(a.id.split('_')[1] || "0") - parseInt(b.id.split('_')[1] || "0"));
              winners = quartasMatches.map(m => m.winnerId!).filter(id => id !== undefined);
              nextMatches = [...nextMatches, ...generateKnockoutMatches(winners, "Semi")];
              nextPhase = 'semi';
          } else if (gameState.cupPhase === 'semi') {
              const semiMatches = nextMatches.filter(m => m.name.includes("Semi"));
              semiMatches.sort((a, b) => parseInt(a.id.split('_')[1] || "0") - parseInt(b.id.split('_')[1] || "0"));
              winners = semiMatches.map(m => m.winnerId!).filter(id => id !== undefined);
              nextMatches = [...nextMatches, ...generateKnockoutMatches(winners, "Final")];
              nextPhase = 'final';
          } else if (gameState.cupPhase === 'final') {
              recordMatchCompletion(results[0].id);
              setGameState(prev => ({ ...prev, phase: 'champion', activeMarbleIds: [results[0].id], marbles: updatedMarbles, cupScores: newScores }));
              audio.playFinish();
              return;
          }
      }
      setGameState(prev => ({ ...prev, marbles: updatedMarbles, cupScores: newScores, cupMatches: nextMatches, cupPhase: nextPhase as any, phase: 'round_result', roundPoints: results.reduce((acc, m, i) => ({ ...acc, [m.id]: (match.type === 'group' ? CUP_GROUP_POINTS[i] : (i===0?1:0)) }), {}) }));
  };

  const handleNextRound = () => {
    setIsFollowingBet(false); 
    if (gameState.gameMode === 'cup') {
        const nextIdx = gameState.currentMatchIndex + 1;
        const currentMatch = gameState.cupMatches[gameState.currentMatchIndex];
        let nextScores = { ...gameState.cupScores };
        if (currentMatch.type === 'group' && gameState.cupPhase !== 'groups') { Object.keys(nextScores).forEach(key => { nextScores[parseInt(key)] = 0; }); }
        if (nextIdx < gameState.cupMatches.length) {
            setGameState(prev => ({ ...prev, cupScores: nextScores, phase: 'cup_tree', currentMatchIndex: nextIdx, activeMarbleIds: prev.cupMatches[nextIdx].marbleIds, round: prev.round + 1 }));
        }
        return;
    }
    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);
      if (nextActiveIds.length === 1) {
        audio.playFinish();
        recordMatchCompletion(nextActiveIds[0]);
        setGameState(prev => ({ ...prev, activeMarbleIds: nextActiveIds, phase: 'champion' }));
      } else {
        setGameState(prev => ({ ...prev, activeMarbleIds: nextActiveIds, phase: 'racing', round: prev.round + 1, lastEliminatedId: null }));
      }
    } else {
      if (gameState.round >= gameState.totalRounds) {
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         audio.playFinish();
         recordMatchCompletion(sortedByScore[0].id);
         setGameState(prev => ({ ...prev, activeMarbleIds: [sortedByScore[0].id], phase: 'champion' }));
      } else {
        setGameState(prev => ({ ...prev, phase: 'racing', round: prev.round + 1, roundPoints: {} }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode, phase: 'betting', round: 1, totalRounds: gameState.gameMode === 'elimination' ? TEAMS.length - 1 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})), activeMarbleIds: INITIAL_MARBLES.map(m => m.id), betMarbleId: null,
      lastEliminatedId: null, roundPoints: {}, cupMatches: [], currentMatchIndex: 0, cupGroups: [], cupScores: {}, cupPhase: 'groups'
    });
    setIsPaused(false); setShowExitConfirm(false); setIsFollowingBet(false);
  };

  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') { timer = setTimeout(() => { handleNextRound(); }, 3000); }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">MARBLE ROYALE</h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">BRASILEIRÃO EDITION</h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">Desenvolvido por Prof Covre</p>
        <div className="flex flex-wrap justify-center gap-2 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           {['elimination', 'points', 'cup'].map(mode => (
             <button key={mode} onClick={() => handleModeSelect(mode as GameMode)} className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === mode ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}>{mode === 'elimination' ? 'MATA-MATA' : mode === 'points' ? 'PONTOS CORRIDOS' : 'COPA'}</button>
           ))}
        </div>
        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400"><Trophy className="mr-2" /> Escolha seu Time</h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3">
              {gameState.marbles.map(m => (
                <button key={m.id} onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))} className={`p-3 rounded-lg flex flex-col items-center transition-all ${gameState.betMarbleId === m.id ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' : 'bg-gray-700 border border-transparent hover:bg-gray-600'}`}>
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden"><img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" /></div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>
          <div className="mb-8 border-t border-gray-700 pt-6">
            <div className="flex justify-between items-center mb-4">
               <h2 className="text-xl font-bold flex items-center text-blue-400"><Settings className="mr-2" /> Configurações</h2>
               <button onClick={() => setShowStatisticsModal(true)} className="flex items-center text-sm bg-purple-700 hover:bg-purple-600 text-white px-3 py-1.5 rounded transition-colors"><BarChart2 className="w-4 h-4 mr-2" />Estatísticas</button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {['gravity', 'restitution'].map(key => (
                <div key={key}>
                  <label className="text-xs text-gray-400 block mb-1">{key === 'gravity' ? 'Gravidade' : 'Elasticidade'} ({(physicsConfig[key as keyof PhysicsConfig] * 100).toFixed(0)}%)</label>
                  <input type="range" min="0.1" max={key === 'gravity' ? "0.8" : "0.9"} step={key === 'gravity' ? "0.05" : "0.1"} value={physicsConfig[key as keyof PhysicsConfig]} onChange={(e) => setPhysicsConfig(prev => ({...prev, [key]: parseFloat(e.target.value)}))} className="w-full accent-blue-500" />
                </div>
              ))}
            </div>
          </div>
          <button disabled={gameState.betMarbleId === null} onClick={handleStartTournament} className={`w-full py-4 rounded-lg font-black text-xl tracking-widest transition-all flex items-center justify-center ${gameState.betMarbleId !== null ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1' : 'bg-gray-700 text-gray-500 cursor-not-allowed'}`}>{gameState.gameMode === 'cup' ? 'VER CHAVEAMENTO' : 'INICIAR CORRIDA'}</button>
        </div>
        {showStatisticsModal && (
           <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-gray-800 border border-gray-600 rounded-xl p-6 max-w-4xl w-full shadow-2xl animate-in zoom-in-95 flex flex-col max-h-[90vh]">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-2xl font-bold flex items-center text-purple-400"><BarChart2 className="mr-2 w-6 h-6"/> Histórico e Estatísticas</h3>
                    <button onClick={() => setShowStatisticsModal(false)}><X className="text-gray-400 hover:text-white" /></button>
                 </div>
                 <div className="overflow-y-auto pr-2 custom-scrollbar">
                     <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
                         {['total', 'elimination', 'points', 'cup'].map(m => (
                             <div key={m} className="bg-gray-700 p-3 rounded-lg text-center">
                                 <div className="text-gray-400 text-xs uppercase mb-1">{m === 'total' ? 'Total' : m === 'elimination' ? 'Mata-Mata' : m === 'points' ? 'Pontos' : 'Copas'}</div>
                                 <div className="text-2xl font-bold">{statistics.matches[m as keyof Statistics['matches']].completed}</div>
                                 <div className="text-xs text-red-400">Interr: {statistics.matches[m as keyof Statistics['matches']].interrupted}</div>
                             </div>
                         ))}
                     </div>
                     <h4 className="text-lg font-bold mb-3 text-white border-b border-gray-700 pb-2">Desempenho por Time</h4>
                     <div className="overflow-x-auto">
                         <table className="w-full text-left text-sm">
                             <thead className="text-gray-400 uppercase font-mono text-xs"><tr><th className="p-2">Time</th><th className="p-2 text-center text-yellow-500">Títulos</th><th className="p-2 text-center text-green-400">Corridas</th><th className="p-2 text-center text-blue-400">Pontos</th></tr></thead>
                             <tbody className="divide-y divide-gray-700">
                                 {Object.entries(statistics.teams).sort(([, a]: [string, TeamStats], [, b]: [string, TeamStats]) => b.titles.total - a.titles.total || b.raceWins.total - a.raceWins.total || b.points.total - a.points.total).map(([idStr, stats]: [string, TeamStats]) => {
                                         const team = TEAMS[parseInt(idStr)];
                                         return (
                                             <tr key={idStr} className="hover:bg-gray-700/50">
                                                 <td className="p-2 flex items-center space-x-2"><img src={team.logo} className="w-6 h-6 object-contain" /><span className="font-bold">{team.name}</span></td>
                                                 <td className="p-2 text-center font-mono font-bold text-yellow-500 text-lg">{stats.titles.total > 0 ? <span className="flex items-center justify-center"><Trophy className="w-3 h-3 mr-1"/>{stats.titles.total}</span> : '-'}</td>
                                                 <td className="p-2 text-center font-mono">{stats.raceWins.total}</td>
                                                 <td className="p-2 text-center font-mono text-gray-400">{stats.points.total}</td>
                                             </tr>
                                         )
                                     })}
                             </tbody>
                         </table>
                     </div>
                 </div>
                 <div className="mt-6 flex justify-between items-center border-t border-gray-700 pt-4">
                    <button onClick={resetStatistics} className="flex items-center text-red-500 hover:text-red-400 text-xs font-bold px-3 py-2 rounded hover:bg-red-900/20 transition-colors"><Trash2 className="w-4 h-4 mr-2" />RESETAR DADOS</button>
                    <button onClick={() => setShowStatisticsModal(false)} className="px-6 py-2 bg-gray-600 hover:bg-gray-500 text-white font-bold rounded-lg">FECHAR</button>
                 </div>
              </div>
           </div>
        )}
      </div>
    );
  }

  if (gameState.phase === 'cup_tree') {
      const getSortedGroup = (groupIdx: number) => [...(gameState.cupGroups[groupIdx] || [])].sort((a, b) => (gameState.cupScores[b] || 0) - (gameState.cupScores[a] || 0));
      const getTeam = (id: number | undefined) => id !== undefined ? gameState.marbles.find(m => m.id === id) : undefined;
      const isGroupFinished = (gIdx: number) => gameState.currentMatchIndex > (16 + gIdx);
      const getWinnerFromMatch = (phaseName: string, bracketMatchIndex: number) => { const targetId = `${phaseName}_${bracketMatchIndex * 2}`; const m = gameState.cupMatches.find(match => match.id === targetId); return m?.winnerId; };
      const leadersA = getSortedGroup(0); const leadersB = getSortedGroup(1); const leadersC = getSortedGroup(2); const leadersD = getSortedGroup(3);
      const projections = (gameState.cupPhase === 'groups') ? [{ t1: leadersA[0], t2: leadersB[3] },{ t1: leadersA[1], t2: leadersB[2] },{ t1: leadersA[2], t2: leadersB[1] },{ t1: leadersA[3], t2: leadersB[0] },{ t1: leadersC[0], t2: leadersD[3] },{ t1: leadersC[1], t2: leadersD[2] },{ t1: leadersC[2], t2: leadersD[1] },{ t1: leadersC[3], t2: leadersD[0] },] : [];
      const renderBracketMatch = (phaseName: string, index: number, proj?: {t1: number | undefined, t2: number | undefined}, t1Ready: boolean = true, t2Ready: boolean = true, lT: string = "", lB: string = "") => {
         const targetId = `${phaseName}_${index * 2}`; const match = gameState.cupMatches.find(m => m.id === targetId);
         let t1Id = match ? match.marbleIds[0] : (t1Ready && proj ? proj.t1 : undefined);
         let t2Id = match ? match.marbleIds[1] : (t2Ready && proj ? proj.t2 : undefined);
         const team1 = getTeam(t1Id); const team2 = getTeam(t2Id); const winnerId = match?.winnerId;
         return (
             <div className={`p-2 rounded-lg border flex flex-col justify-center text-xs mb-4 min-w-[160px] ${match ? 'bg-gray-800 border-gray-600' : 'bg-gray-800/50 border-gray-700 border-dashed opacity-70'}`}>
                 <div className="flex justify-between items-center mb-1"><span className="text-[10px] text-gray-500 font-mono">JOGO {index + 1}</span></div>
                 <div className="mb-1"><div className={`flex items-center space-x-2 p-1 rounded ${winnerId === t1Id && t1Id !== undefined ? 'bg-green-900/30' : ''}`}><div className={`w-4 h-4 rounded-full flex items-center justify-center p-[1px] ${winnerId === t1Id && t1Id !== undefined ? 'bg-yellow-400' : 'bg-gray-400'}`}>{team1 ? <img src={team1.logoUrl} className="w-full h-full object-contain rounded-full" /> : <div className="w-full h-full bg-gray-600 rounded-full" />}</div><div className="flex flex-col overflow-hidden"><span className={`truncate font-mono ${winnerId === t1Id && t1Id !== undefined ? 'text-green-400 font-bold' : 'text-gray-300'}`}>{team1 ? team1.name : (gameState.cupPhase==='groups' ? '???' : '')}</span>{!team1 && lT && <span className="text-[9px] text-gray-500 uppercase">{lT}</span>}</div>{winnerId === t1Id && t1Id !== undefined && <Medal className="w-3 h-3 text-yellow-500 ml-auto" />}</div></div>
                 <div><div className={`flex items-center space-x-2 p-1 rounded ${winnerId === t2Id && t2Id !== undefined ? 'bg-green-900/30' : ''}`}><div className={`w-4 h-4 rounded-full flex items-center justify-center p-[1px] ${winnerId === t2Id && t2Id !== undefined ? 'bg-yellow-400' : 'bg-gray-400'}`}>{team2 ? <img src={team2.logoUrl} className="w-full h-full object-contain rounded-full" /> : <div className="w-full h-full bg-gray-600 rounded-full" />}</div><div className="flex flex-col overflow-hidden"><span className={`truncate font-mono ${winnerId === t2Id && t2Id !== undefined ? 'text-green-400 font-bold' : 'text-gray-300'}`}>{team2 ? team2.name : (gameState.cupPhase==='groups' ? '???' : '')}</span>{!team2 && lB && <span className="text-[9px] text-gray-500 uppercase">{lB}</span>}</div>{winnerId === t2Id && t2Id !== undefined && <Medal className="w-3 h-3 text-yellow-500 ml-auto" />}</div></div>
             </div>
         );
      };
      return (
          <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-start p-4 text-white overflow-y-auto">
             <div className="w-full max-w-7xl mt-4">
                 <div className="flex justify-between items-center mb-6"><div><h1 className="text-3xl font-bold brand-font text-yellow-400">ORGANIZAÇÃO DA COPA</h1><p className="text-gray-400 text-sm">Próximo: {gameState.cupMatches[gameState.currentMatchIndex]?.name}</p></div><button onClick={handleStartCupRacing} className="bg-green-600 hover:bg-green-500 text-white px-8 py-3 rounded-lg font-bold flex items-center shadow-lg animate-pulse"><PlayCircle className="mr-2 w-6 h-6" /> IR PARA PARTIDA</button></div>
                 <div className="overflow-x-auto pb-4 custom-scrollbar"><div className="flex gap-4 min-w-[800px] justify-between">
                        <div className="flex flex-col w-1/4 min-w-[180px]"><h3 className="text-center font-bold text-blue-400 mb-4 bg-gray-800 p-2 rounded">OITAVAS</h3><div className="flex flex-col gap-2">{[0,1,2,3,4,5,6,7].map(i => renderBracketMatch("Oitavas", i, projections[i], i < 4 ? isGroupFinished(0) && isGroupFinished(1) : isGroupFinished(2) && isGroupFinished(3)))}</div></div>
                        <div className="flex flex-col w-1/4 min-w-[180px]"><h3 className="text-center font-bold text-purple-400 mb-4 bg-gray-800 p-2 rounded">QUARTAS</h3><div className="flex flex-col justify-around h-full py-8">{[0,1,2,3].map(i => renderBracketMatch("Quartas", i, { t1: getWinnerFromMatch('Oitavas', i*2), t2: getWinnerFromMatch('Oitavas', i*2+1) }))}</div></div>
                        <div className="flex flex-col w-1/4 min-w-[180px]"><h3 className="text-center font-bold text-orange-400 mb-4 bg-gray-800 p-2 rounded">SEMI</h3><div className="flex flex-col justify-around h-full py-16">{[0,1].map(i => renderBracketMatch("Semi", i, { t1: getWinnerFromMatch('Quartas', i*2), t2: getWinnerFromMatch('Quartas', i*2+1) }))}</div></div>
                        <div className="flex flex-col w-1/4 min-w-[180px]"><h3 className="text-center font-bold text-yellow-400 mb-4 bg-gray-800 p-2 rounded">FINAL</h3><div className="flex flex-col justify-center h-full py-20">{renderBracketMatch("Final", 0, { t1: getWinnerFromMatch('Semi', 0), t2: getWinnerFromMatch('Semi', 1) })}{gameState.cupPhase === 'final' && gameState.cupMatches.find(m => m.name.includes("Final"))?.winnerId && (<div className="mt-4 text-center"><Trophy className="w-16 h-16 text-yellow-400 mx-auto animate-bounce" /><p className="text-yellow-400 font-bold mt-2">CAMPEÃO!</p></div>)}</div></div>
                    </div></div>
             </div>
          </div>
      )
  }

  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;
    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8"><Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" /><div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2"><img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" /></div></div>
        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>
        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}><h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3><p className="text-gray-300">{playerWon ? `Sua aposta no ${champion.name} deu certo!` : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}.`}</p></div>
        <button onClick={resetGame} className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform">NOVO TORNEIO</button>
      </div>
    );
