  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">
      <div className="absolute inset-0 z-0"><RaceEngine key={gameState.round} activeMarbles={activeMarblesList} config={physicsConfig} obstacleSettings={obstacleSettings} onRaceFinish={handleRaceFinish} betMarbleId={gameState.betMarbleId} isPaused={isPaused} isFollowingBet={isFollowingBet}/></div>
      {gameState.gameMode === 'cup' && !gameState.activeMarbleIds.includes(gameState.betMarbleId!) && !isPaused && (<div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-50"><button onClick={handleSimulateMatch} className="flex items-center space-x-2 bg-blue-600 hover:bg-blue-500 text-white font-bold py-3 px-6 rounded-full shadow-lg border-2 border-blue-400 animate-pulse"><FastForward className="fill-current" /><span>SIMULAR PARTIDA</span></button></div>)}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">{gameState.gameMode === 'cup' ? gameState.cupMatches[gameState.currentMatchIndex]?.name : 'Rodada'}</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.gameMode === 'cup' ? '' : `${gameState.round} `}<span className="text-sm text-gray-500">{gameState.gameMode === 'cup' ? '' : `/ ${gameState.totalRounds}`}</span></div>
         </div>
         <div className="flex flex-col items-end pointer-events-auto">
             <button onClick={() => setIsPaused(true)} className="bg-yellow-600/80 p-2 rounded-full border border-yellow-400 text-white mb-2 shadow-lg"><Pause className="w-6 h-6" /></button>
             {gameState.gameMode === 'points' && (<div className="bg-black/50 p-3 rounded-lg border border-gray-700 text-white min-w-[150px]"><div className="text-xs text-gray-400 uppercase mb-1">Top Pontos</div>{gameState.marbles.sort((a,b) => b.score - a.score).slice(0, 3).map((m, i) => (<div key={m.id} className="flex justify-between text-xs mb-1"><span>{i+1}. {m.name}</span><span className="font-mono">{m.score}</span></div>))}</div>)}
             {gameState.gameMode === 'elimination' && (<div className="bg-black/50 p-3 rounded-lg border border-gray-700 text-white text-right"><div className="text-xs text-gray-400 uppercase">Sobreviventes</div><div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div></div>)}
         </div>
      </div>
      {isPaused && (<div className="absolute inset-0 z-50 bg-black/80 flex items-center justify-center p-4"><div className="bg-gray-800 p-8 rounded-2xl max-w-sm w-full text-center"><h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2><div className="flex flex-col space-y-4"><button onClick={() => setIsPaused(false)} className="w-full py-4 bg-green-600 text-white font-bold rounded-lg text-xl">RETOMAR</button><button onClick={() => setShowExitConfirm(true)} className="w-full py-4 bg-gray-700 text-gray-300 font-bold rounded-lg text-xl">SAIR DO JOGO</button></div></div></div>)}
      {showExitConfirm && (<div className="absolute inset-0 z-50 bg-black/90 flex items-center justify-center p-4"><div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl max-w-sm w-full text-center"><Skull className="w-16 h-16 text-red-500 mx-auto mb-4" /><h2 className="text-2xl font-bold text-white mb-2">ABANDONAR?</h2><div className="flex space-x-4 mt-8"><button onClick={() => setShowExitConfirm(false)} className="flex-1 py-3 bg-gray-700 text-white font-bold rounded-lg">CANCELAR</button><button onClick={() => { setShowExitConfirm(false); setIsPaused(false); handleExitTournament(); }} className="flex-1 py-3 bg-red-600 text-white font-bold rounded-lg">SAIR</button></div></div></div>)}
      {gameState.phase === 'round_result' && (<div className="absolute inset-0 z-50 bg-black/80 flex items-center justify-center p-4"><div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA</h2>
            {gameState.gameMode === 'elimination' ? (<div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6"><Skull className="w-8 h-8 text-red-500 mx-auto mb-2" /><div className="text-red-400 font-bold uppercase mb-1">Eliminado</div><div className="text-xl text-white font-mono">{gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}</div></div>) : 
            (<div className="bg-gray-900/50 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">{[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (<div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 text-sm"><span>{idx + 1}. {m.name}</span><div className="flex flex-col text-right"><span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span></div></div>))}</div>)}
            <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden"><div className="h-full bg-blue-500 animate-[width_3s_linear] w-full origin-left" style={{ animationDuration: '3s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div><style>{`@keyframes shrink { from { width: 100%; } to { width: 0%; } }`}</style></div>
          </div></div>)}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           <Camera className="w-4 h-4 text-yellow-400" />
           <span className="text-gray-300 font-bold uppercase text-sm">
             {isFollowingBet ? 'CÂMERA: VOCÊ' : 'CÂMERA: LÍDER'}
           </span>
        </button>
      )}
    </div>
  );
}

