             {gameState.gameMode === 'elimination' && (<div className="bg-black/50 p-2 rounded text-white text-right"><div className="text-[10px] uppercase">Sobreviventes</div><div className="text-xl font-bold">{activeMarblesList.length}</div></div>)}
