      </div>
      {isPaused && (<div className="absolute inset-0 z-50 bg-black/80 flex items-center justify-center p-4"><div className="bg-gray-800 p-8 rounded-2xl max-w-sm w-full text-center"><h2 className="text-2xl font-bold text-white mb-8 brand-font">PAUSA</h2><div className="flex flex-col space-y-4"><button onClick={() => setIsPaused(false)} className="w-full py-3 bg-green-600 text-white font-bold rounded">RETOMAR</button><button onClick={() => setShowExitConfirm(true)} className="w-full py-3 bg-gray-700 text-gray-300 font-bold rounded">SAIR</button></div></div></div>)}
