      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({ x, y, vx: Math.cos(angle) * velocity, vy: Math.sin(angle) * velocity, life: 1.0, decay: 0.02 + Math.random() * 0.03, color: color, size: 1 + Math.random() * 2 });
