    const timeSinceStart = Date.now() - startTime.current;
    if (!gateOpenRef.current && timeSinceStart > GATE_DELAY) { gateOpenRef.current = true; audio.playPinHit(15); spawnParticles(COURSE_WIDTH/2, GATE_Y, '#10b981', 30, 8); }
    const STEPS = 8; const dt = 1 / STEPS; timeRef.current += 1; const now = Date.now();
    const marbles = marblesRef.current; const dynamicObjs = dynamicRef.current;
    for (let i = particlesRef.current.length - 1; i >= 0; i--) { const p = particlesRef.current[i]; p.x += p.vx; p.y += p.vy; p.life -= p.decay; if (p.life <= 0) particlesRef.current.splice(i, 1); }
    let totalSpeed = 0;

