export default function App() {
  // Load Stats from LocalStorage
  const [statistics, setStatistics] = useState<Statistics>(() => {
      const saved = localStorage.getItem('marble_royale_stats_v1');
      if (saved) {
          try {
              const parsed = JSON.parse(saved);
              // Merge with initial to ensure new teams/fields exist if version changed slightly
              const merged = { 
                  ...INITIAL_STATS, 
                  matches: { ...INITIAL_STATS.matches, ...parsed.matches }, 
                  teams: { ...INITIAL_STATS.teams, ...parsed.teams } 
              };
              return merged;
          } catch(e) {
              return JSON.parse(JSON.stringify(INITIAL_STATS));
          }
      }
      return JSON.parse(JSON.stringify(INITIAL_STATS));
  });

  const saveStats = (newStats: Statistics) => {
      setStatistics(newStats);
      localStorage.setItem('marble_royale_stats_v1', JSON.stringify(newStats));
  };

  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: TEAMS.length - 1, 
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {},
    cupMatches: [],
    currentMatchIndex: 0,
    cupGroups: [],
    cupScores: {},
    cupPhase: 'groups'
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  // Obstacle settings still exist but menu is removed
  const [obstacleSettings, setObstacleSettings] = useState<ObstacleSettings>({
    spinner: true,
    slider: true,
    repulsor: true,
    conveyor: true,
    teleporter: true,
    hollow_circle: true,
    laser: true,
    fan: true,
    funnel: true
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [showStatisticsModal, setShowStatisticsModal] = useState(false);

  // Default to false (Follow Leader)
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Statistics Helpers ---

  const recordMatchInterruption = () => {
      const newStats = JSON.parse(JSON.stringify(statistics));
      const mode = gameState.gameMode;
      newStats.matches.total.interrupted++;
      if (newStats.matches[mode]) newStats.matches[mode].interrupted++;
      saveStats(newStats);
  };

  const recordMatchCompletion = (winnerId: number) => {
      const newStats = JSON.parse(JSON.stringify(statistics));
      const mode = gameState.gameMode;

      // Match Counts
      newStats.matches.total.completed++;
      if (newStats.matches[mode]) newStats.matches[mode].completed++;

      // Team Title
      if (newStats.teams[winnerId]) {
          newStats.teams[winnerId].titles.total++;
          newStats.teams[winnerId].titles[mode]++;
      }

      saveStats(newStats);
  };

  const recordRoundStats = (results: Marble[], roundPoints: Record<number, number>) => {
      const newStats = JSON.parse(JSON.stringify(statistics));
      const mode = gameState.gameMode;

      // Race Winner (First place in results)
      // Note: In inverted elimination, the first place "wins" the race to leave the competition.
      if (results.length > 0) {
          const winners = results.filter(m => m.finished).sort((a,b) => a.rank - b.rank);
          if (winners.length > 0) {
              const winnerId = winners[0].id;
              if (newStats.teams[winnerId]) {
                  newStats.teams[winnerId].raceWins.total++;
                  newStats.teams[winnerId].raceWins[mode]++;
              }
          }
      }

      // Points accumulation
      Object.entries(roundPoints).forEach(([idStr, points]) => {
          const id = parseInt(idStr);
          if (newStats.teams[id]) {
              newStats.teams[id].points.total += points;
              newStats.teams[id].points[mode] += points;
          }
      });

      saveStats(newStats);
  };

  const resetStatistics = () => {
      if (window.confirm("Tem certeza que deseja apagar todo o histórico de partidas?")) {
          const reset = JSON.parse(JSON.stringify(INITIAL_STATS));
          saveStats(reset);
      }
  };


  // --- Cup Logic Generators ---

  const generateCupSchedule = (marbleIds: number[]) => {
      // 1. Shuffle teams and assign 4 groups
      const shuffled = shuffle(marbleIds);
      const groups = [
          shuffled.slice(0, 5),
          shuffled.slice(5, 10),
          shuffled.slice(10, 15),
          shuffled.slice(15, 20)
      ];

      // 2. Generate 5 rounds of races for each group
      const matches: Match[] = [];
      const groupNames = ['A', 'B', 'C', 'D'];

      for (let r = 1; r <= 5; r++) {
          groups.forEach((groupIds, gIdx) => {
              matches.push({
                  id: `g${gIdx}_r${r}`,
                  name: `Grupo ${groupNames[gIdx]} - Rodada ${r}`,
                  marbleIds: groupIds,
                  type: 'group',
                  groupIndex: gIdx,
                  nextPhase: (r === 5 && gIdx === 3) // Last match of groups triggers next phase
              });
          });
      }

      return { groups, matches };
  };

  const generateKnockoutMatches = (qualifiers: number[], phaseName: string) => {
      const matches: Match[] = [];
      // Pairs: 0 vs 1, 2 vs 3, etc.
      for (let i = 0; i < qualifiers.length; i += 2) {
          matches.push({
              id: `${phaseName}_${i}`, // ID is strictly tied to index (0, 2, 4...)
              name: `${phaseName} - Jogo ${Math.floor(i/2) + 1}`,
              marbleIds: [qualifiers[i], qualifiers[i+1]],
              type: 'knockout',
              nextPhase: (i === qualifiers.length - 2)
          });
      }
      return matches;
  };

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    let newTotalRounds = 0;
    if (mode === 'elimination' || mode === 'inverted_elimination') newTotalRounds = TEAMS.length - 1;
    if (mode === 'points') newTotalRounds = 10;
    // Cup rounds are dynamic based on matches, but we can set a placeholder
    if (mode === 'cup') newTotalRounds = 35; // 20 group + 8 + 4 + 2 + 1

    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: newTotalRounds
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    // Setup for Cup if selected
    if (gameState.gameMode === 'cup') {
        const { groups, matches } = generateCupSchedule(gameState.marbles.map(m => m.id));
        setGameState(prev => ({
            ...prev,
            phase: 'cup_tree', // Show bracket/groups first!
            cupGroups: groups,
            cupMatches: matches,
            currentMatchIndex: 0,
            cupScores: {}, // Reset scores
            cupPhase: 'groups',
            activeMarbleIds: matches[0].marbleIds, // Pre-load first match
            round: 1
        }));
    } else {
        setGameState(prev => ({ ...prev, phase: 'racing' }));
        audio.init();
        audio.resume();
        setIsPaused(false);
        setShowExitConfirm(false);
        setIsFollowingBet(false);
    }
  };

  const handleStartCupRacing = () => {
      setGameState(prev => ({ ...prev, phase: 'racing' }));
      audio.init();
      audio.resume();
      setIsPaused(false);
      setShowExitConfirm(false);
      setIsFollowingBet(false);
  };

  const handleExitTournament = () => {
      recordMatchInterruption();
      resetGame();
  };

  // Used for simulating non-player matches
  const handleSimulateMatch = () => {
      if (gameState.gameMode !== 'cup') return;

      const currentMatch = gameState.cupMatches[gameState.currentMatchIndex];
      if (!currentMatch) return; // Guard clause

      // Simulate random results
      const matchMarbles: Marble[] = gameState.marbles.filter(m => currentMatch.marbleIds.includes(m.id));
      // CRITICAL FIX: Ensure simulated results have valid rank and finished status
      const shuffledResults = shuffle<Marble>(matchMarbles).map((m, i) => ({
          ...m,
          rank: i + 1,
          finished: true,
          finishTime: i * 100 // Dummy time
      }));

      // Update state immediately without running physics
      handleRaceFinish(shuffledResults);
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'cup') {
        handleCupRaceFinish(results);
        return;
    }

    // Existing Modes Logic
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();

      // Update Stats (0 points for elimination mode usually, but we record race wins)
      recordRoundStats(results, {});

      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else if (gameState.gameMode === 'inverted_elimination') {
      const loser = results.find(m => m.finished);
      if (loser) {
        audio.playEliminated();
        recordRoundStats(results, {});
        setGameState(prev => ({
            ...prev,
            phase: 'round_result',
            lastEliminatedId: loser.id,
            roundPoints: {}
        }));
      }
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score AND persist rank/status
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points,
            rank: index + 1,        // FIX: Update Rank
            finished: true,         // FIX: Update Status
            finishTime: m.finishTime || index
          };
        }
      });

      audio.playFinish();

      // Update Stats
      recordRoundStats(results, currentRoundPoints);

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleCupRaceFinish = (results: Marble[]) => {
      const match = gameState.cupMatches[gameState.currentMatchIndex];
      const newScores = { ...gameState.cupScores };
      const updatedMarbles = [...gameState.marbles];

      // Assign Points logic
      results.forEach((m, idx) => {
          let points = 0;
          if (match.type === 'group') {
              points = CUP_GROUP_POINTS[idx] || 0;
              // For group phase, we accumulate
              newScores[m.id] = (newScores[m.id] || 0) + points;
          } else {
              // Knockout: RESET Score to be pure binary (Winner 1, Loser 0)
              // This removes the confusion of "Total Points" from group stage persisting
              if (idx === 0) points = 1; 
              newScores[m.id] = points; // OVERWRITE, do not accumulate
          }

          // Update main marble objects score for global tracking if needed
          // CRITICAL FIX: Also update rank and finished status so UI displays correct order
          const mIdx = updatedMarbles.findIndex(mar => mar.id === m.id);
          if (mIdx !== -1) {
              updatedMarbles[mIdx] = {
                  ...updatedMarbles[mIdx],
                  score: newScores[m.id],
                  rank: idx + 1,       // 1st place = 1
                  finished: true,
                  finishTime: m.finishTime || idx
              };
          }
      });

      // Stats Update: Calculate points gained this specific round for stats
      const roundPointsForStats: Record<number, number> = {};
      results.forEach((m, idx) => {
          if (match.type === 'group') roundPointsForStats[m.id] = CUP_GROUP_POINTS[idx] || 0;
          else roundPointsForStats[m.id] = (idx === 0 ? 1 : 0); // Knockout wins count as 1 point in stats generally
      });
      recordRoundStats(results, roundPointsForStats);

      // Check if we need to generate next phase
      let nextPhase = gameState.cupPhase;
      let nextMatches = [...gameState.cupMatches];
      let championId: number | null = null;

      if (match.nextPhase) {
          if (gameState.cupPhase === 'groups') {
              nextPhase = 'octavas';
              // Determine Qualifiers (Top 4 from each group)
              const qualifiers: number[] = [];
              gameState.cupGroups.forEach(group => {
                  const sorted = group.sort((a, b) => (newScores[b] || 0) - (newScores[a] || 0));
                  qualifiers.push(...sorted.slice(0, 4));
              });

              const finalQualifiers: number[] = [];

              // A vs B (A1xB4, A2xB3, A3xB2, A4xB1)
              for(let i=0; i<4; i++) {
                 finalQualifiers.push(gameState.cupGroups[0][i]); // A
                 finalQualifiers.push(gameState.cupGroups[1][3-i]); // B
              }
              // C vs D (C1xD4, C2xD3, C3xD2, C4xD1)
              for(let i=0; i<4; i++) {
                 finalQualifiers.push(gameState.cupGroups[2][i]); // C
                 finalQualifiers.push(gameState.cupGroups[3][3-i]); // D
              }

              nextMatches = [...nextMatches, ...generateKnockoutMatches(finalQualifiers, "Oitavas")];

          } else if (gameState.cupPhase === 'octavas') {
              nextPhase = 'quartas';
          }
      }

      // Hack for Knockout Progression:
      const currentMatchIdx = gameState.currentMatchIndex;
      // Mark winner ID on the finished match
      const finishedMatch = { ...match, winnerId: results[0].id };
      nextMatches[currentMatchIdx] = finishedMatch;

      // Logic to generate next round matches if phase ended
      if (match.nextPhase) {
          let winners: number[] = [];

          if (gameState.cupPhase === 'octavas') {
              // FIX: Ensure strict sorting by ID to guarantee Bracket Order (Match 1 vs Match 2)
              const octavasMatches = nextMatches.filter(m => m.name.includes("Oitavas"));
              octavasMatches.sort((a, b) => {
                  // ID format: Oitavas_0, Oitavas_2, etc.
                  const idxA = parseInt(a.id.split('_')[1] || "0");
                  const idxB = parseInt(b.id.split('_')[1] || "0");
                  return idxA - idxB;
              });
              winners = octavasMatches.map(m => m.winnerId!).filter(id => id !== undefined);
              nextMatches = [...nextMatches, ...generateKnockoutMatches(winners, "Quartas")];
              nextPhase = 'quartas';
          } else if (gameState.cupPhase === 'quartas') {
              const quartasMatches = nextMatches.filter(m => m.name.includes("Quartas"));
              quartasMatches.sort((a, b) => {
                  const idxA = parseInt(a.id.split('_')[1] || "0");
                  const idxB = parseInt(b.id.split('_')[1] || "0");
                  return idxA - idxB;
              });
              winners = quartasMatches.map(m => m.winnerId!).filter(id => id !== undefined);
              nextMatches = [...nextMatches, ...generateKnockoutMatches(winners, "Semi")];
              nextPhase = 'semi';
          } else if (gameState.cupPhase === 'semi') {
              const semiMatches = nextMatches.filter(m => m.name.includes("Semi"));
              semiMatches.sort((a, b) => {
                  const idxA = parseInt(a.id.split('_')[1] || "0");
                  const idxB = parseInt(b.id.split('_')[1] || "0");
                  return idxA - idxB;
              });
              winners = semiMatches.map(m => m.winnerId!).filter(id => id !== undefined);
              nextMatches = [...nextMatches, ...generateKnockoutMatches(winners, "Final")];
              nextPhase = 'final';
          } else if (gameState.cupPhase === 'final') {
              // Champion!
              championId = results[0].id;
              recordMatchCompletion(championId);

              setGameState(prev => ({
                  ...prev,
                  phase: 'champion',
                  activeMarbleIds: [championId!],
                  marbles: updatedMarbles,
                  cupScores: newScores
              }));
              audio.playFinish();
              return;
          }
      }

      setGameState(prev => ({
          ...prev,
          marbles: updatedMarbles,
          cupScores: newScores,
          cupMatches: nextMatches,
          cupPhase: nextPhase as any,
          phase: 'round_result',
          roundPoints: results.reduce((acc, m, i) => ({ ...acc, [m.id]: (match.type === 'group' ? CUP_GROUP_POINTS[i] : (i===0?1:0)) }), {})
      }));
  };

  const handleNextRound = () => {
    // CRITICAL: Always reset camera to follow leader at start of new round
    setIsFollowingBet(false); 

    if (gameState.gameMode === 'cup') {
        const nextIdx = gameState.currentMatchIndex + 1;

        // CHECK IF WE NEED TO RESET SCORES FOR KNOCKOUT
        const currentMatch = gameState.cupMatches[gameState.currentMatchIndex];
        let nextScores = { ...gameState.cupScores };

        // If we just finished a group match, but the NEXT state phase is no longer groups (e.g., we just finished the last group game),
        // we should reset scores so Knockout starts at 0.
        // We can check if we are transitioning phases essentially.
        if (currentMatch.type === 'group' && gameState.cupPhase !== 'groups') {
            Object.keys(nextScores).forEach(key => {
                nextScores[parseInt(key)] = 0;
            });
        }

        if (nextIdx < gameState.cupMatches.length) {
            setGameState(prev => ({
                ...prev,
                cupScores: nextScores, // Apply reset scores
                phase: 'cup_tree', // VOLTA PARA A TREE PARA MOSTRAR ATUALIZAÇÕES
                currentMatchIndex: nextIdx,
                activeMarbleIds: prev.cupMatches[nextIdx].marbleIds,
                round: prev.round + 1
            }));
        } else {
             // End of cup (should be handled in Final logic, but failsafe)
        }
        return;
    }

    if (gameState.gameMode === 'elimination' || gameState.gameMode === 'inverted_elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish();
        recordMatchCompletion(nextActiveIds[0]);
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         recordMatchCompletion(winnerIds[0]);

         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        // Points Mode: Just increment round, phase -> racing
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: (gameState.gameMode === 'elimination' || gameState.gameMode === 'inverted_elimination') ? TEAMS.length - 1 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {},
      cupMatches: [],
      currentMatchIndex: 0,
      cupGroups: [],
      cupScores: {},
      cupPhase: 'groups'
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const toggleObstacle = (key: keyof ObstacleSettings) => {
    setObstacleSettings(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      // 3 Seconds Popup Duration
      timer = setTimeout(() => {
        handleNextRound();
      }, 3000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);


  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest uppercase">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex flex-wrap justify-center gap-2 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             ELIMINAÇÃO
           </button>
           <button 
             onClick={() => handleModeSelect('inverted_elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'inverted_elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             ELIMINAÇÃO INVERTIDA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
           <button 
             onClick={() => handleModeSelect('cup')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'cup' ? 'bg-yellow-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             COPA
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono text-center">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <div className="flex justify-between items-center mb-4">
               <h2 className="text-xl font-bold flex items-center text-blue-400">
                  <Settings className="mr-2" /> Configurações
               </h2>
               {/* STATISTICS BUTTON - REPLACES OBSTACLES CONFIG */}
               <button 
                  onClick={() => setShowStatisticsModal(true)}
                  className="flex items-center text-sm bg-purple-700 hover:bg-purple-600 text-white px-3 py-1.5 rounded transition-colors"
               >
                  <BarChart2 className="w-4 h-4 mr-2" />
                  Estatísticas
               </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex w-full">
            <button 
                disabled={gameState.betMarbleId === null}
                onClick={handleStartTournament}
                className={`w-full py-4 rounded-lg font-black text-xl tracking-widest transition-all flex items-center justify-center ${
                gameState.betMarbleId !== null
                    ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                    : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
            >
                {gameState.gameMode === 'cup' ? 'VER CHAVEAMENTO' : 'INICIAR CORRIDA'}
            </button>
          </div>

        </div>

        {/* Statistics Modal */}
        {showStatisticsModal && (
           <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-gray-800 border border-gray-600 rounded-xl p-6 max-w-4xl w-full shadow-2xl animate-in zoom-in-95 flex flex-col max-h-[90vh]">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-2xl font-bold flex items-center text-purple-400 uppercase"><BarChart2 className="mr-2 w-6 h-6"/> Histórico e Estatísticas</h3>
                    <button onClick={() => setShowStatisticsModal(false)}><X className="text-gray-400 hover:text-white" /></button>
                 </div>

                 <div className="overflow-y-auto pr-2 custom-scrollbar">
                     {/* General Match Stats */}
                     <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-3 mb-8">
                         <div className="bg-gray-700 p-2 rounded-lg text-center">
                             <div className="text-gray-400 text-[10px] uppercase mb-1">Total</div>
                             <div className="text-xl font-bold">{statistics.matches.total.completed}</div>
                         </div>
                         <div className="bg-gray-700 p-2 rounded-lg text-center">
                             <div className="text-gray-400 text-[10px] uppercase mb-1">Eliminação</div>
                             <div className="text-xl font-bold text-red-400">{statistics.matches.elimination.completed}</div>
                         </div>
                         <div className="bg-gray-700 p-2 rounded-lg text-center">
                             <div className="text-gray-400 text-[10px] uppercase mb-1">Inv. Eliminação</div>
                             <div className="text-xl font-bold text-red-300">{statistics.matches.inverted_elimination?.completed || 0}</div>
                         </div>
                         <div className="bg-gray-700 p-2 rounded-lg text-center">
                             <div className="text-gray-400 text-[10px] uppercase mb-1">Pontos</div>
                             <div className="text-xl font-bold text-blue-400">{statistics.matches.points.completed}</div>
                         </div>
                         <div className="bg-gray-700 p-2 rounded-lg text-center">
                             <div className="text-gray-400 text-[10px] uppercase mb-1">Copas</div>
                             <div className="text-xl font-bold text-yellow-400">{statistics.matches.cup.completed}</div>
                         </div>
                     </div>

                     {/* Team Table */}
                     <h4 className="text-lg font-bold mb-3 text-white border-b border-gray-700 pb-2">Desempenho por Time</h4>
                     <div className="overflow-x-auto">
                         <table className="w-full text-left text-sm">
                             <thead className="text-gray-400 uppercase font-mono text-xs">
                                 <tr>
                                     <th className="p-2">Time</th>
                                     <th className="p-2 text-center text-yellow-500" title="Títulos Totais">Títulos</th>
                                     <th className="p-2 text-center text-green-400" title="Vitórias em Corridas">Vitórias</th>
                                     <th className="p-2 text-center text-blue-400" title="Pontos Totais Acumulados">Pontos</th>
                                 </tr>
                             </thead>
                             <tbody className="divide-y divide-gray-700">
                                 {Object.entries(statistics.teams)
                                     .sort(([, a]: [string, TeamStats], [, b]: [string, TeamStats]) => {
                                         if (b.titles.total !== a.titles.total) return b.titles.total - a.titles.total;
                                         if (b.raceWins.total !== a.raceWins.total) return b.raceWins.total - a.raceWins.total;
                                         return b.points.total - a.points.total;
                                     })
                                     .map(([idStr, stats]: [string, TeamStats]) => {
                                         const team = TEAMS[parseInt(idStr)];
                                         return (
                                             <tr key={idStr} className="hover:bg-gray-700/50">
                                                 <td className="p-2 flex items-center space-x-2">
                                                     <img src={team.logo} className="w-6 h-6 object-contain" />
                                                     <span className="font-bold">{team.name}</span>
                                                 </td>
                                                 <td className="p-2 text-center font-mono font-bold text-yellow-500">
                                                     {stats.titles.total > 0 ? stats.titles.total : '-'}
                                                 </td>
                                                 <td className="p-2 text-center font-mono">
                                                     {stats.raceWins.total}
                                                 </td>
                                                 <td className="p-2 text-center font-mono text-gray-400">
                                                     {stats.points.total}
                                                 </td>
                                             </tr>
                                         )
                                     })}
                             </tbody>
                         </table>
                     </div>
                 </div>

                 <div className="mt-6 flex justify-between items-center border-t border-gray-700 pt-4">
                    <button 
                      onClick={resetStatistics}
                      className="flex items-center text-red-500 hover:text-red-400 text-xs font-bold px-3 py-2 rounded hover:bg-red-900/20 transition-colors"
                    >
                        <Trash2 className="w-4 h-4 mr-2" />
                        RESETAR DADOS
                    </button>
                    <button 
                      onClick={() => setShowStatisticsModal(false)}
                      className="px-6 py-2 bg-gray-600 hover:bg-gray-500 text-white font-bold rounded-lg"
                    >
                      FECHAR
                    </button>
                 </div>
              </div>
           </div>
        )}

      </div>
    );
  }

  // 1.5 CUP TREE VIEW (New Phase)
  if (gameState.phase === 'cup_tree') {
      const getSortedGroup = (groupIdx: number) => {
         const groupIds = gameState.cupGroups[groupIdx] || [];
         return [...groupIds].sort((a, b) => (gameState.cupScores[b] || 0) - (gameState.cupScores[a] || 0));
      };

      const getTeam = (id: number | undefined) => id !== undefined ? gameState.marbles.find(m => m.id === id) : undefined;
      const getTeamName = (id: number | undefined) => getTeam(id)?.name || "???";

      // Helper: Check if group matches are finished (5 rounds)
      const isGroupFinished = (gIdx: number) => gameState.currentMatchIndex > (16 + gIdx);

      // Helper: Get winner from a specific previous match by ID (strictly index-based logic)
      const getWinnerFromMatch = (phaseName: string, bracketMatchIndex: number) => {
          // bracketMatchIndex comes in as 0, 1, 2, 3...
          // The generator uses i, i+2... so ID is phaseName + "_" + (bracketMatchIndex * 2)
          const targetId = `${phaseName}_${bracketMatchIndex * 2}`;
          const m = gameState.cupMatches.find(match => match.id === targetId);
          return m?.winnerId;
      };

      // Bracket Projection Helpers
      const leadersA = getSortedGroup(0);
      const leadersB = getSortedGroup(1);
      const leadersC = getSortedGroup(2);
      const leadersD = getSortedGroup(3);

      const projections = (gameState.cupPhase === 'groups') ? [
          { t1: leadersA[0], t2: leadersB[3] },
          { t1: leadersA[1], t2: leadersB[2] },
          { t1: leadersA[2], t2: leadersB[1] },
          { t1: leadersA[3], t2: leadersB[0] },
          { t1: leadersC[0], t2: leadersD[3] },
          { t1: leadersC[1], t2: leadersD[2] },
          { t1: leadersC[2], t2: leadersD[1] },
          { t1: leadersC[3], t2: leadersD[0] },
      ] : [];

      const octavasLabels = [
          { t: "1º GRUPO A", b: "4º GRUPO B" },
          { t: "2º GRUPO A", b: "3º GRUPO B" },
          { t: "3º GRUPO A", b: "2º GRUPO B" },
          { t: "4º GRUPO A", b: "1º GRUPO B" },
          { t: "1º GRUPO C", b: "4º GRUPO D" },
          { t: "2º GRUPO C", b: "3º GRUPO D" },
          { t: "3º GRUPO C", b: "2º GRUPO D" },
          { t: "4º GRUPO C", b: "1º GRUPO D" },
      ];

      const renderBracketMatch = (phaseName: string, index: number, projection?: {t1: number | undefined, t2: number | undefined}, t1Ready: boolean = true, t2Ready: boolean = true, labelTop: string = "", labelBottom: string = "") => {
         // Find actual match by ID
         const targetId = `${phaseName}_${index * 2}`;
         const match = gameState.cupMatches.find(m => m.id === targetId);

         let team1Id = match ? match.marbleIds[0] : (t1Ready && projection ? projection.t1 : undefined);
         let team2Id = match ? match.marbleIds[1] : (t2Ready && projection ? projection.t2 : undefined);

         const team1 = getTeam(team1Id);
         const team2 = getTeam(team2Id);

         // Highlight winner
         const winnerId = match?.winnerId;

         return (
             <div className={`p-2 rounded-lg border flex flex-col justify-center text-xs mb-4 min-w-[160px] ${match ? 'bg-gray-800 border-gray-600' : 'bg-gray-800/50 border-gray-700 border-dashed opacity-70'}`}>
                 <div className="flex justify-between items-center mb-1">
                     <span className="text-[10px] text-gray-500 font-mono uppercase">JOGO {index + 1}</span>
                 </div>

                 {/* Team 1 */}
                 <div className="mb-1">
                     <div className={`flex items-center space-x-2 p-1 rounded ${winnerId === team1Id && team1Id !== undefined ? 'bg-green-900/30' : ''}`}>
                          <div className={`w-4 h-4 rounded-full flex items-center justify-center p-[1px] ${winnerId === team1Id && team1Id !== undefined ? 'bg-yellow-400' : 'bg-gray-400'}`}>
                              {team1 ? <img src={team1.logoUrl} className="w-full h-full object-contain rounded-full" /> : <div className="w-full h-full bg-gray-600 rounded-full" />}
                          </div>
                          <div className="flex flex-col overflow-hidden">
                              <span className={`truncate font-mono ${winnerId === team1Id && team1Id !== undefined ? 'text-green-400 font-bold' : 'text-gray-300'}`}>
                                  {team1 ? team1.name : (gameState.cupPhase==='groups' ? '???' : '')}
                              </span>
                              {!team1 && labelTop && <span className="text-[9px] text-gray-500 uppercase">{labelTop}</span>}
                          </div>
                          {winnerId === team1Id && team1Id !== undefined && <Medal className="w-3 h-3 text-yellow-500 ml-auto" />}
                     </div>
                 </div>

                 {/* Team 2 */}
                 <div>
                     <div className={`flex items-center space-x-2 p-1 rounded ${winnerId === team2Id && team2Id !== undefined ? 'bg-green-900/30' : ''}`}>
                          <div className={`w-4 h-4 rounded-full flex items-center justify-center p-[1px] ${winnerId === team2Id && team2Id !== undefined ? 'bg-yellow-400' : 'bg-gray-400'}`}>
                              {team2 ? <img src={team2.logoUrl} className="w-full h-full object-contain rounded-full" /> : <div className="w-full h-full bg-gray-600 rounded-full" />}
                          </div>
                          <div className="flex flex-col overflow-hidden">
                              <span className={`truncate font-mono ${winnerId === team2Id && team2Id !== undefined ? 'text-green-400 font-bold' : 'text-gray-300'}`}>
                                  {team2 ? team2.name : (gameState.cupPhase==='groups' ? '???' : '')}
                              </span>
                              {!team2 && labelBottom && <span className="text-[9px] text-gray-500 uppercase">{labelBottom}</span>}
                          </div>
                          {winnerId === team2Id && team2Id !== undefined && <Medal className="w-3 h-3 text-yellow-500 ml-auto" />}
                     </div>
                 </div>
             </div>
         );
      };

      return (
          <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-start p-4 text-white overflow-y-auto">
             <div className="w-full max-w-7xl mt-4">
                 <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                     <div>
                        <h1 className="text-3xl font-bold brand-font text-yellow-400 uppercase">ORGANIZAÇÃO DA COPA</h1>
                        <p className="text-gray-400 text-sm">Próximo: {gameState.cupMatches[gameState.currentMatchIndex]?.name}</p>
                     </div>
                     <button 
                        onClick={handleStartCupRacing}
                        className="bg-green-600 hover:bg-green-500 text-white px-8 py-3 rounded-lg font-bold flex items-center shadow-lg animate-pulse"
                     >
                         <PlayCircle className="mr-2 w-6 h-6" /> IR PARA PARTIDA
                     </button>
                 </div>

                 {/* FULL BRACKET SCROLL VIEW */}
                 <div className="overflow-x-auto pb-4 custom-scrollbar">
                    <div className="flex gap-4 min-w-[800px] justify-between">

                        {/* COLUNA 1: OITAVAS */}
                        <div className="flex flex-col w-1/4 min-w-[180px]">
                            <h3 className="text-center font-bold text-blue-400 mb-4 bg-gray-800 p-2 rounded uppercase">OITAVAS</h3>
                            <div className="flex flex-col gap-2">
                                {[0,1,2,3,4,5,6,7].map(i => {
                                    let t1Ready = true;
                                    let t2Ready = true;

                                    if (gameState.cupPhase === 'groups') {
                                        if (i < 4) {
                                            // Matches 0-3: A vs B
                                            t1Ready = isGroupFinished(0); // A finished?
                                            t2Ready = isGroupFinished(1); // B finished?
                                        } else {
                                            // Matches 4-7: C vs D
                                            t1Ready = isGroupFinished(2); // C finished?
                                            t2Ready = isGroupFinished(3); // D finished?
                                        }
                                    }
                                    return renderBracketMatch("Oitavas", i, projections[i], t1Ready, t2Ready, octavasLabels[i].t, octavasLabels[i].b);
                                })}
                            </div>
                        </div>

                        {/* COLUNA 2: QUARTAS */}
                        <div className="flex flex-col w-1/4 min-w-[180px]">
                            <h3 className="text-center font-bold text-purple-400 mb-4 bg-gray-800 p-2 rounded uppercase">QUARTAS</h3>
                            <div className="flex flex-col justify-around h-full gap-4 py-8">
                                {[0,1,2,3].map(i => {
                                    // Immediate projection: Winners of Octavas
                                    const w1 = getWinnerFromMatch('Oitavas', i*2); // Oitavas_0 (Jogo 1)
                                    const w2 = getWinnerFromMatch('Oitavas', i*2+1); // Oitavas_2 (Jogo 2)
                                    return renderBracketMatch("Quartas", i, { t1: w1, t2: w2 }, true, true, `VENC. OIT ${i*2+1}`, `VENC. OIT ${i*2+2}`);
                                })}
                            </div>
                        </div>

                        {/* COLUNA 3: SEMI */}
                        <div className="flex flex-col w-1/4 min-w-[180px]">
                            <h3 className="text-center font-bold text-orange-400 mb-4 bg-gray-800 p-2 rounded uppercase">SEMI</h3>
                            <div className="flex flex-col justify-around h-full gap-8 py-16">
                                {[0,1].map(i => {
                                    // Immediate projection: Winners of Quartas
                                    const w1 = getWinnerFromMatch('Quartas', i*2);
                                    const w2 = getWinnerFromMatch('Quartas', i*2+1);
                                    return renderBracketMatch("Semi", i, { t1: w1, t2: w2 }, true, true, `VENC. QRT ${i*2+1}`, `VENC. QRT ${i*2+2}`);
                                })}
                            </div>
                        </div>

                        {/* COLUNA 4: FINAL */}
                        <div className="flex flex-col w-1/4 min-w-[180px]">
                            <h3 className="text-center font-bold text-yellow-400 mb-4 bg-gray-800 p-2 rounded uppercase">FINAL</h3>
                            <div className="flex flex-col justify-center h-full py-20">
                                {(() => {
                                    // Immediate projection: Winners of Semi
                                    const w1 = getWinnerFromMatch('Semi', 0);
                                    const w2 = getWinnerFromMatch('Semi', 1);
                                    return renderBracketMatch("Final", 0, { t1: w1, t2: w2 }, true, true, "VENC. SEMI 1", "VENC. SEMI 2");
                                })()}
                                {gameState.cupPhase === 'final' && gameState.cupMatches.find(m => m.name.includes("Final"))?.winnerId && (
                                     <div className="mt-4 text-center">
                                         <Trophy className="w-16 h-16 text-yellow-400 mx-auto animate-bounce" />
                                         <p className="text-yellow-400 font-bold mt-2 uppercase">CAMPEÃO!</p>
                                     </div>
                                )}
                            </div>
                        </div>

                    </div>
                 </div>

                 {/* Groups Display (Simplified at bottom) */}
                 {gameState.cupPhase === 'groups' && (
                 <div className="mt-8 border-t border-gray-700 pt-6">
                     <h2 className="text-xl font-bold mb-4 flex items-center text-gray-400 uppercase"><LayoutGrid className="mr-2"/> GRUPOS (Simulação p/ Oitavas)</h2>
                     <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                         {gameState.cupGroups.map((group, idx) => {
                             const sortedIds = getSortedGroup(idx);
                             return (
                                 <div key={idx} className="bg-gray-800 rounded p-2 text-xs">
                                     <h3 className="font-bold text-center mb-2 uppercase">GRUPO {['A','B','C','D'][idx]}</h3>
                                     {sortedIds.map((id, rank) => (
                                         <div key={id} className={`flex justify-between p-1 ${rank < 4 ? 'text-white' : 'text-gray-500'}`}>
                                            <span>{rank+1}. {gameState.marbles.find(m=>m.id===id)?.name}</span>
                                            <span>{gameState.cupScores[id]||0}</span>
                                         </div>
                                     ))}
                                 </div>
                             )
                         })}
                     </div>
                 </div>
                 )}

             </div>
          </div>
      )
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font uppercase">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4 uppercase">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold uppercase">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2 uppercase">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform uppercase"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  const isCupMatchWithoutPlayer = gameState.gameMode === 'cup' && !gameState.activeMarbleIds.includes(gameState.betMarbleId!);

  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        {/* key={gameState.round} ensures the component Re-mounts completely when round changes.
            This resets the physics engine and guarantees a fresh start for every round. */}
        <RaceEngine 
          key={gameState.round}
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          obstacleSettings={obstacleSettings}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
          gameMode={gameState.gameMode}
        />
      </div>

      {/* CUP SIMULATION OVERLAY */}
      {isCupMatchWithoutPlayer && !isPaused && (
          <div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-50 animate-in fade-in zoom-in">
              <button 
                onClick={handleSimulateMatch}
                className="flex items-center space-x-2 bg-blue-600 hover:bg-blue-500 text-white font-bold py-3 px-6 rounded-full shadow-lg border-2 border-blue-400 animate-pulse uppercase"
              >
                 <FastForward className="fill-current" />
                 <span>SIMULAR PARTIDA</span>
              </button>
              <div className="text-center mt-2 text-xs text-gray-400 bg-black/50 p-1 rounded uppercase">
                  Ou continue assistindo
              </div>
          </div>
      )}

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">
                  {gameState.gameMode === 'cup' ? gameState.cupMatches[gameState.currentMatchIndex]?.name : 'Rodada'}
              </div>
              <div className="text-2xl font-mono text-yellow-400">
                  {gameState.gameMode === 'cup' ? '' : `${gameState.round} `}
                  <span className="text-sm text-gray-500">
                      {gameState.gameMode === 'cup' ? '' : `/ ${gameState.totalRounds}`}
                  </span>
              </div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {(gameState.gameMode === 'elimination' || gameState.gameMode === 'inverted_elimination') && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}

             {gameState.gameMode === 'cup' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right max-h-40 overflow-y-auto">
                   <div className="text-xs text-gray-400 font-bold uppercase mb-1">
                       {gameState.cupPhase === 'groups' ? `Grupo ${['A','B','C','D'][gameState.cupMatches[gameState.currentMatchIndex]?.groupIndex || 0]}` : 'Placar'}
                   </div>
                   {gameState.activeMarbleIds.map(id => {
                       const m = gameState.marbles.find(mar => mar.id === id);
                       return (
                           <div key={id} className="flex justify-between text-xs space-x-2">
                               <span>{m?.name}</span>
                               {/* Only show numeric score in groups */}
                               {gameState.cupPhase === 'groups' && <span className="text-yellow-500 font-bold">{gameState.cupScores[id] || 0}</span>}
                           </div>
                       )
                   })}
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font uppercase">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center uppercase"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center uppercase"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2 uppercase">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8 uppercase">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg uppercase"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all uppercase"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal - 3 Seconds Duration */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font uppercase">FIM DA RODADA {gameState.gameMode === 'cup' ? '' : gameState.round}</h2>

            {(gameState.gameMode === 'elimination' || gameState.gameMode === 'inverted_elimination') ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono uppercase">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400 uppercase">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        {/* Check match type of the CURRENT FINISHED match (which index is pointing to) */}
                        {gameState.gameMode === 'cup' && gameState.cupMatches[gameState.currentMatchIndex]?.type !== 'group' ? (
                            <span className={idx===0 ? "text-green-400 font-bold uppercase" : "text-red-500 uppercase"}>{idx===0 ? "VENCEU" : "ELIMINADO"}</span>
                        ) : (
                            <>
                                <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                                <span className="text-[10px] text-gray-500 uppercase">Total: {gameState.gameMode === 'cup' ? gameState.cupScores[m.id] : m.score}</span>
                            </>
                        )}
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {(gameState.gameMode === 'elimination' || gameState.gameMode === 'inverted_elimination') && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6 uppercase">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar - 3 Seconds */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_3s_linear] w-full origin-left" style={{ animationDuration: '3s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Toggle Camera */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <Camera className="w-4 h-4 text-gray-400" />}

           {isFollowingBet ? (
               <div className="flex items-center space-x-2">
                   <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                       <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
                   </div>
                   <span className="font-bold text-yellow-400 uppercase">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
               </div>
           ) : (
               <span className="text-gray-300 font-bold uppercase text-sm uppercase">CÂMERA: LÍDER</span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings, GameMode } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
  gameMode: GameMode;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, isFollowingBet, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Cache for loaded images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);
  const gateOpenRef = useRef(false);

  // Constants
  const COURSE_WIDTH = 600;
  const GATE_Y = 180; // Position of the starting gate
  const GATE_DELAY = 3000; // Time before gate opens (ms)

  // --- Particle Helper ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03, // Random fade speed
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 12 + Math.floor(Math.random() * 4); 
    const segmentHeight = 450;
    let currentY = 0;

    // --- OBSTÁCULO INICIAL: PLINKO DE PINOS MÓVEIS ---
    const plinkoStartY = GATE_Y + 100;
    const plinkoRows = 10; 
    const plinkoRowHeight = 55; 
    const plinkoEndY = plinkoStartY + (plinkoRows * plinkoRowHeight);

    // Paredes
    lines.push({ x1: 0, y1: 0, x2: 0, y2: plinkoEndY, type: 'wall' }); 
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH, y2: plinkoEndY, type: 'wall' }); 

    // Gerar Pinos Móveis com Espaçamento Igual
    for (let r = 0; r < plinkoRows; r++) {
        const py = plinkoStartY + (r * plinkoRowHeight);
        const isEven = r % 2 === 0;

        // Espaçamento e distribuição
        const pinRadius = 9;
        const spacing = 70; // Espaçamento fixo

        // Configuração de Movimento da Linha
        // Alterna direção para caos, velocidade lenta
        const rowSpeed = 0.05 * (isEven ? 1 : -1); 
        const rowRange = 70; // AUMENTADO: Amplitude do movimento (Antes era 35)

        // Começa em uma posição que garante pinos centrais
        // Para 600px e espaçamento 70, temos ~8 pinos.
        // StartX = 35 centraliza.
        const startX = 35;

        for (let x = startX; x < COURSE_WIDTH; x += spacing) {
             pins.push({
                 x: x, 
                 y: py,
                 radius: pinRadius, 
                 type: 'pin',
                 initialX: x,
                 speed: rowSpeed,
                 range: rowRange
             });
        }
    }

    // --- FUNIL PÓS-PLINKO ---
    const funnelHeight = 180;
    const funnelExitGap = 70;

    // Parede Funil Esquerda
    lines.push({
        x1: 0, y1: plinkoEndY,
        x2: COURSE_WIDTH / 2 - funnelExitGap / 2, y2: plinkoEndY + funnelHeight,
        type: 'wall'
    });

    // Parede Funil Direita
    lines.push({
        x1: COURSE_WIDTH, y1: plinkoEndY,
        x2: COURSE_WIDTH / 2 + funnelExitGap / 2, y2: plinkoEndY + funnelHeight,
        type: 'wall'
    });

    // Atualizar onde começa a geração procedural
    currentY = plinkoEndY + funnelHeight + 50;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 10 });
            options.push({ type: 'slider_v', weight: 10 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 15 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 10 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 4 });

        if (options.length === 0) return 'none';

        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;

        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = pickObstacleType();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      // -- DYNAMIC MOVING OBSTACLES --

      if (type === 'spinner') {
        // --- DOUBLE SPINNERS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 150,
          angle: 0,
          speed: 0.12,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 150,
          angle: Math.PI / 2,
          speed: -0.15,
        });

        // CENTRAL OBSTACLE: Force marbles into the spinners
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 300, radius: 25, type: 'bumper' });

      } else if (type === 'slider_h') {
        // --- MOVING SLIDERS (Cross Horizontal) ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        dynamics.push({
            id: `slide_h_top_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 200,
            width: 200,
            angle: 0,
            speed: 2.5,
            range: 180,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 200
        });

        dynamics.push({
            id: `slide_h_bot_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 350,
            width: 200,
            angle: 0,
            speed: -3.0, 
            range: 180,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 350
        });

      } else if (type === 'slider_v') {
        // --- VERTICAL CRUSHERS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
            id: `slide_v_L_${i}`,
            type: 'slider_v',
            x: COURSE_WIDTH * 0.25,
            y: currentY + 250,
            width: 120,
            angle: 0,
            speed: 1.5,
            range: 80,
            initialX: COURSE_WIDTH * 0.25,
            initialY: currentY + 250
        });

        dynamics.push({
            id: `slide_v_R_${i}`,
            type: 'slider_v',
            x: COURSE_WIDTH * 0.75,
            y: currentY + 350, 
            width: 120,
            angle: 0,
            speed: 1.5,
            range: 80,
            initialX: COURSE_WIDTH * 0.75,
            initialY: currentY + 350
        });

        // CENTRAL OBSTACLE: Block the easy path in the middle
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 300, radius: 28, type: 'bumper' });

      } else if (type === 'repulsor') {
        // --- REPULSORS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `repulse_${i}`,
          type: 'repulsor',
          x: COURSE_WIDTH / 2,
          y: currentY + 300,
          width: 50, 
          range: 140, 
          angle: 0,
          speed: 0.1, 
          force: 3.0
        });

      } else if (type === 'conveyor') {
        // --- CONVEYOR BELTS ---
        const dirType = Math.floor(Math.random() * 5);
        let angle = Math.PI / 2;
        let cx = COURSE_WIDTH * 0.5;
        let width = 200; 
        let height = 100; 

        if (dirType === 1) { angle = Math.PI / 4; cx = COURSE_WIDTH * 0.4; } 
        else if (dirType === 2) { angle = 3 * Math.PI / 4; cx = COURSE_WIDTH * 0.6; } 
        else if (dirType === 3) { angle = 0; cx = COURSE_WIDTH * 0.3; width = 150; height = 150; } 
        else if (dirType === 4) { angle = Math.PI; cx = COURSE_WIDTH * 0.7; width = 150; height = 150; }

        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'wall' });

        dynamics.push({
          id: `conveyor_${i}`,
          type: 'conveyor',
          x: cx,
          y: currentY + 250,
          width: width, 
          height: height, 
          angle: angle, 
          speed: 0.1, 
          force: 18 
        });

        // CENTRAL OBSTACLE: Add a pin to disrupt smooth conveyor flow
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 250, radius: 20, type: 'bumper' });

      } else if (type === 'teleporter') {
        // --- ADVANCED TELEPORTERS ---
        const isTrap = Math.random() > 0.5; 
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);

        let targetY;
        if (isTrap) {
            targetY = Math.max(100, currentY - (300 + Math.random() * 400));
        } else {
            targetY = currentY + (500 + Math.random() * 300);
        }

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `teleport_${i}`,
          type: 'teleporter',
          x: entranceX,
          y: currentY + 200,
          width: 70, 
          destX: exitX,
          destY: targetY,
          angle: 0,
          speed: 0,
          blinkPhase: Math.random() * Math.PI * 2,
          blinkSpeed: 0.02 + Math.random() * 0.02, 
          active: true
        });

        pins.push({ x: entranceX + (Math.random() > 0.5 ? 80 : -80), y: currentY + 200, radius: 20, type: 'bumper' });

      } else if (type === 'hollow_circle') {
        // --- HOLLOW CIRCLE (New Obstacle) ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });

        dynamics.push({
           id: `hollow_${i}`,
           type: 'hollow_circle',
           x: COURSE_WIDTH / 2 + (Math.random() - 0.5) * 60,
           y: currentY + 250,
           width: 250, // Diameter
           angle: 0,
           speed: (Math.random() > 0.5 ? 1 : -1) * (0.02 + Math.random() * 0.02),
           range: Math.PI / 2.5 // Gap size
        });

      } else if (type === 'laser') {
        // --- LASER CANNONS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
          id: `laser_${i}`,
          type: 'laser',
          x: COURSE_WIDTH * 0.1, 
          y: currentY + 300,
          width: 0, 
          height: COURSE_WIDTH * 0.8, 
          angle: 0, 
          speed: 0,
          force: 25, 
          active: true,
          timer: 0
        });
        lines.push({ x1: 0, y1: currentY + 280, x2: COURSE_WIDTH * 0.15, y2: currentY + 320, type: 'wall' });

        // CENTRAL OBSTACLE: Add a pin to make avoiding the laser harder
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 300, radius: 22, type: 'bumper' });

      } else if (type === 'funnel') {
        // --- BIG FUNNEL ---
        const funnelTopY = currentY + 50;
        const funnelHeight = 250;
        const exitGap = 55; // Marbles are radius 18 (diam 36). 55 gives clearance.

        // Left Angle Wall
        lines.push({
            x1: 0, y1: funnelTopY,
            x2: COURSE_WIDTH/2 - exitGap/2, y2: funnelTopY + funnelHeight,
            type: 'wall'
        });

        // Right Angle Wall
        lines.push({
            x1: COURSE_WIDTH, y1: funnelTopY,
            x2: COURSE_WIDTH/2 + exitGap/2, y2: funnelTopY + funnelHeight,
            type: 'wall'
        });

        // Chaos Pin below the exit to scatter them
        pins.push({ x: COURSE_WIDTH/2, y: funnelTopY + funnelHeight + 80, radius: 20, type: 'bumper' });

      } else if (type === 'funnel') {
         // --- WIND CANNONS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `fan_${i}_1`,
          type: 'fan',
          x: 20, 
          y: currentY + 250,
          width: 40,
          height: 300, 
          angle: 0, 
          speed: 0,
          force: 0.7
        });

        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 25, type: 'bumper' });

        // CENTRAL OBSTACLES: Catch marbles being blown
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 200, radius: 15, type: 'bumper' });
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 350, radius: 15, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Area
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (isPaused) {
        audio.updateRolling(0);
        return;
    }

    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    // Gate Logic - Handle start
    const timeSinceStart = Date.now() - startTime.current;

    // If we haven't opened the gate yet
    if (!gateOpenRef.current) {
        if (timeSinceStart > GATE_DELAY) {
            gateOpenRef.current = true;
            audio.playPinHit(15); // Loud gong/sound for start
            spawnParticles(COURSE_WIDTH/2, GATE_Y, '#10b981', 30, 8); // Explosion of green particles
        }
    }

    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    // Update Particles
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life -= p.decay;
        if (p.life <= 0) {
            particlesRef.current.splice(i, 1);
        }
    }

    let totalSpeed = 0;

    // --- MERCY RULE CHECK ---
    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    const totalMarbles = marbles.length;

    if (totalMarbles > 1 && activeMarblesCount === 1 && gameMode !== 'inverted_elimination') {
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = totalMarbles; 
            loser.finishTime = now - startTime.current + 99999; 
        }

        if (!raceFinished.current) {
            raceFinished.current = true;
            const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
            audio.playFinish(); 
            setTimeout(() => onRaceFinish(sorted), 1000);
            return;
        }
    }

    // Separate dynamic types
    const fans: DynamicObstacle[] = [];
    const repulsors: DynamicObstacle[] = [];
    const conveyors: DynamicObstacle[] = [];
    const lasers: DynamicObstacle[] = [];
    const teleporters: DynamicObstacle[] = [];
    const hollowCircles: DynamicObstacle[] = [];
    const solidDynamics: DynamicObstacle[] = [];

    dynamicObjs.forEach(obj => {
      if (obj.type === 'fan') { fans.push(obj); return; }
      if (obj.type === 'repulsor') { repulsors.push(obj); return; }
      if (obj.type === 'conveyor') { conveyors.push(obj); return; }
      if (obj.type === 'laser') { lasers.push(obj); return; }
      if (obj.type === 'teleporter') { teleporters.push(obj); return; }
      if (obj.type === 'hollow_circle') { hollowCircles.push(obj); }

      if (obj.type !== 'hollow_circle') {
          solidDynamics.push(obj);
      }

      if (obj.type === 'spinner' || obj.type === 'hollow_circle') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      }
    });

    lasers.forEach(l => {
       l.timer = (l.timer || 0) + 1;
       if (l.timer > 180) {
           l.active = !l.active;
           l.timer = 0;
       }
    });

    // Update Teleporter Opacity/State (Intermittent logic)
    teleporters.forEach(t => {
        if (t.blinkPhase !== undefined && t.blinkSpeed !== undefined) {
            const val = Math.sin(timeRef.current * t.blinkSpeed + t.blinkPhase);
            const opacity = (val + 1) / 2; 
            t.active = opacity > 0.3; 
            t.timer = opacity; 
        }
    });

    // --- UPDATE MOVING PINS (PLINKO) ---
    pinsRef.current.forEach(pin => {
         if (pin.initialX !== undefined && pin.speed !== undefined && pin.range !== undefined) {
             pin.x = pin.initialX + Math.sin(timeRef.current * pin.speed) * pin.range;
         }
    });

    const dynamicLines: LineSegment[] = [];
    solidDynamics.forEach(obj => {
      const halfW = obj.width / 2;
      const dx = Math.cos(obj.angle) * halfW;
      const dy = Math.sin(obj.angle) * halfW;
      dynamicLines.push({
        x1: obj.x - dx, y1: obj.y - dy,
        x2: obj.x + dx, y2: obj.y + dy,
        type: obj.type === 'spinner' ? 'bouncer' : 'floor'
      });
    });

    // START GATE PHYSICAL BARRIER
    const gateLine: LineSegment = { x1: 0, y1: GATE_Y, x2: COURSE_WIDTH, y2: GATE_Y, type: 'wall' };

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // --- SAFETY BOUNDARIES ---
        if (m.x < m.radius) {
            m.x = m.radius;
            m.vx = Math.abs(m.vx) * 0.5; 
        } else if (m.x > COURSE_WIDTH - m.radius) {
            m.x = COURSE_WIDTH - m.radius;
            m.vx = -Math.abs(m.vx) * 0.5; 
        }

        // Fan Physics
        for (const fan of fans) {
          const dx = m.x - fan.x;
          const dy = m.y - fan.y;
          const localX = dx * Math.cos(-fan.angle) - dy * Math.sin(-fan.angle);
          const localY = dx * Math.sin(-fan.angle) + dy * Math.cos(-fan.angle);
          const halfWidth = fan.width / 2; 
          const range = fan.height || 200;

          if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
             const force = fan.force || 0.5;
             const forceX = Math.cos(fan.angle) * force;
             const forceY = Math.sin(fan.angle) * force;
             m.vx += forceX * dt;
             m.vy += forceY * dt;

             if (Math.random() < 0.1) {
                spawnParticles(m.x, m.y, '#e2e8f0', 1, 1);
             }
          }
        }

        // Repulsor Physics
        for (const rep of repulsors) {
          const dx = m.x - rep.x;
          const dy = m.y - rep.y;
          const distSq = dx*dx + dy*dy;
          const range = rep.range || 100;

          if (distSq < range * range) {
             const dist = Math.sqrt(distSq);
             const nx = dx / dist;
             const ny = dy / dist;
             const pulse = (Math.sin(timeRef.current * rep.speed) + 1) * 0.5;
             const force = (rep.force || 1) * (1 - dist/range) * (0.5 + pulse);
             m.vx += nx * force * dt * 50;
             m.vy += ny * force * dt * 50;
          }
        }

        // Conveyor Physics
        for (const conv of conveyors) {
           const dx = m.x - conv.x;
           const dy = m.y - conv.y;

           const localParallel = dx * Math.cos(-conv.angle) - dy * Math.sin(-conv.angle); 
           const localPerp = dx * Math.sin(-conv.angle) + dy * Math.cos(-conv.angle); 

           const halfLength = conv.width / 2;
           const halfWidth = (conv.height || 50) / 2;

           if (Math.abs(localParallel) < halfLength && Math.abs(localPerp) < halfWidth) {
              const force = conv.force || 10;
              const forceX = Math.cos(conv.angle) * force;
              const forceY = Math.sin(conv.angle) * force;
              m.vx += forceX * dt;
              m.vy += forceY * dt;

              if (Math.random() < 0.05) {
                 spawnParticles(m.x, m.y, 'rgba(255,255,255,0.3)', 1, 0.5);
              }
           }
        }

        // Hollow Circle Physics
        for (const circle of hollowCircles) {
           const dx = m.x - circle.x;
           const dy = m.y - circle.y;
           const dist = Math.sqrt(dx*dx + dy*dy);
           const r = (circle.width / 2);
           const thickness = 6;

           if (dist + m.radius >= r - thickness && dist - m.radius <= r + thickness) {
               let angle = Math.atan2(dy, dx);
               if (angle < 0) angle += Math.PI * 2;

               let rot = circle.angle % (Math.PI * 2);
               if (rot < 0) rot += Math.PI * 2;

               let diff = Math.abs(angle - rot);
               if (diff > Math.PI) diff = Math.PI * 2 - diff; 

               const halfGap = (circle.range || 1.0) / 2;

               if (diff < halfGap) {
                   // Inside gap
               } else {
                   const nx = dx / dist;
                   const ny = dy / dist;

                   const pushSign = dist < r ? -1 : 1;
                   const overlap = (m.radius + thickness) - Math.abs(dist - r);

                   if (overlap > 0) {
                       m.x += nx * pushSign * overlap * 0.5;
                       m.y += ny * pushSign * overlap * 0.5;

                       const nX = nx * pushSign;
                       const nY = ny * pushSign;

                       const dot = m.vx * nX + m.vy * nY;

                       m.vx = (m.vx - 2 * dot * nX) * config.restitution;
                       m.vy = (m.vy - 2 * dot * nY) * config.restitution;

                       m.vx *= config.friction;
                       m.vy *= config.friction;
                   }
               }
           }
        }

        // Laser Physics
        for (const laser of lasers) {
            if (!laser.active) continue;
            const len = laser.height || 300;
            const lx1 = laser.x;
            const ly1 = laser.y;
            const lx2 = lx1 + Math.cos(laser.angle) * len;
            const ly2 = ly1 + Math.sin(laser.angle) * len;

            const A = m.x - lx1;
            const B = m.y - ly1;
            const C = lx2 - lx1;
            const D = ly2 - ly1;

            const dot = A * C + B * D;
            const lenSq = C * C + D * D;
            let param = -1;
            if (lenSq !== 0) param = dot / lenSq;

            let xx, yy;

            if (param < 0) {
                xx = lx1; yy = ly1;
            } else if (param > 1) {
                xx = lx2; yy = ly2;
            } else {
                xx = lx1 + param * C;
                yy = ly1 + param * D;
            }

            const dx = m.x - xx;
            const dy = m.y - yy;
            const dist = Math.sqrt(dx * dx + dy * dy);

            if (dist < m.radius + 5) { 
                const force = laser.force || 20;
                m.vx += (dx/dist) * force * dt * 10;
                m.vy += (dy/dist) * force * dt * 10;
                m.vx += (Math.random() - 0.5) * 10;
                m.vy += (Math.random() - 0.5) * 10;
                spawnParticles(m.x, m.y, '#ef4444', 3, 4);
            }
        }

        // Teleporter Physics
        for (const tele of teleporters) {
            if (!tele.active) continue; 

            const dx = m.x - tele.x;
            const dy = m.y - tele.y;
            const dist = Math.sqrt(dx*dx + dy*dy);

            if (dist < (tele.width/2) && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {

                 const isBackwards = (tele.destY || 0) < tele.y;
                 const color = isBackwards ? '#ef4444' : '#d946ef';

                 spawnParticles(m.x, m.y, color, 15, 4); 

                 m.x = tele.destX || m.x;
                 m.y = tele.destY || m.y;

                 m.vx *= 0.2; 
                 m.vy = isBackwards ? 0 : Math.abs(m.vy) + 2; 

                 teleportCooldowns.current[m.id] = now + 1500; 
                 audio.playPinHit(8); 

                 spawnParticles(m.x, m.y, '#06b6d4', 15, 4); 
            }
        }

        m.angle += m.omega * dt;
        m.omega *= 0.999; 

        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        if (m.vx*m.vx + m.vy*m.vy < 0.2) {
             m.vx += (Math.random() - 0.5); 
             m.vy += 0.5; 
        }

        // CHECK GATE COLLISION
        if (!gateOpenRef.current) {
            checkLineCollision(m, gateLine);
        }

        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
          spawnParticles(m.x, m.y, '#10b981', 10, 4);

          // NEW: In Inverted Elimination, the race ends as soon as the first marble crosses.
          if (gameMode === 'inverted_elimination' && !raceFinished.current) {
              raceFinished.current = true;
              onRaceFinish(marblesRef.current);
              return;
          }
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    // --- CAMERA LOGIC ---
    let targetY = cameraY.current;

    // Explicit Camera Logic:
    // 1. If following bet -> Follow bet marble.
    // 2. If bet marble finishes or isFollowingBet is false -> Follow Leader (1st place active marble).
    if (isFollowingBet && betMarbleId !== null) {
        const betMarble = marbles.find(m => m.id === betMarbleId);
        // Only follow if it exists and hasn't finished (or maybe follow even if finished? Usually better to follow active)
        if (betMarble && !betMarble.finished) {
            targetY = betMarble.y - 300; 
        } else {
             // Fallback to leader if bet marble is finished
             const activeMarblesList = marbles.filter(m => !m.finished);
             if (activeMarblesList.length > 0) {
                 activeMarblesList.sort((a, b) => b.y - a.y);
                 targetY = activeMarblesList[0].y - 300;
             }
        }
    } else {
        // Follow Leader Logic - STRICTLY follow the first place marble
        const activeMarblesList = marbles.filter(m => !m.finished);
        if (activeMarblesList.length > 0) {
          activeMarblesList.sort((a, b) => b.y - a.y);
          // Changed: Do NOT average top 3. Just take the leader.
          // This ensures the camera stays with the leader even if they are far ahead.
          targetY = activeMarblesList[0].y - 300;
        } 
    }

    cameraY.current += (targetY - cameraY.current) * 0.08;

    if (marbles.filter(m => !m.finished).length === 0) {
      if (!raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
      }
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean, cx: number, cy: number) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
        if (intensity > 3.0) {
            spawnParticles(cx, cy, isBouncy ? '#ef4444' : '#94a3b8', Math.floor(intensity), intensity * 0.5);
        }
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy, closeX, closeY);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBumper = pin.type === 'bumper';

      const intensity = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
      if (intensity > 1) {
          audio.playPinHit(intensity);
      }

      // Calculate approximate contact point
      const cx = pin.x + nx * pin.radius;
      const cy = pin.y + ny * pin.radius;

      resolveCollisionPhysics(ball, nx, ny, isBumper, cx, cy);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) {
             audio.playPinHit(dot * 0.5);
             if (dot > 5) {
                 const cx = m1.x + nx * m1.radius;
                 const cy = m1.y + ny * m1.radius;
                 spawnParticles(cx, cy, '#fff', 3, 2);
             }
         }

         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    gateOpenRef.current = false; // Reset Gate
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};
    particlesRef.current = [];

    // Preload Images
    activeMarbles.forEach(m => {
        const img = new Image();
        img.src = m.logoUrl;
        // REMOVED crossOrigin = "Anonymous" to allow non-CORS CDNs to display (tainted canvas is OK here)
        imagesRef.current[m.id] = img;
    });

    // HORIZONTAL START POSITIONS
    const totalWidth = COURSE_WIDTH * 0.9;
    const startX = COURSE_WIDTH * 0.05;
    const spacing = totalWidth / Math.max(1, activeMarbles.length);

    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: startX + (spacing * index) + (spacing/2), // Evenly spaced horizontally
      y: GATE_Y - 50, // Just above the gate
      vx: 0,
      vy: 0,
      angle: 0,
      omega: 0,
      finished: false,
      rank: 0
    }));

    audio.resume();

  }, [activeMarbles]); 

  // --- Drawing Subroutines ---

  const drawRepulsor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const pulse = (Math.sin(timeRef.current * obj.speed) + 1) * 0.5;
    const currentRadius = obj.width/2 + pulse * (obj.range! - obj.width/2);

    ctx.beginPath();
    ctx.arc(0, 0, obj.width/2, 0, Math.PI * 2);
    ctx.fillStyle = '#8b5cf6';
    ctx.fill();

    ctx.beginPath();
    ctx.arc(0, 0, currentRadius, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(139, 92, 246, ${1 - pulse})`;
    ctx.lineWidth = 2;
    ctx.stroke();
  };

  const drawConveyor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const length = obj.width;  
    const thickness = obj.height || 50; 

    ctx.beginPath();
    ctx.rect(-length/2, -thickness/2, length, thickness);
    ctx.fillStyle = '#334155';
    ctx.fill();
    ctx.strokeStyle = '#475569';
    ctx.stroke();

    const spacing = 40;
    const offset = (timeRef.current * obj.speed * 50) % spacing;

    ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';

    for(let x = -length/2; x < length/2; x += spacing) {
        const currentX = x + offset;
        if (currentX > length/2) continue;

        ctx.save();
        ctx.translate(currentX, 0); 
        ctx.beginPath();
        ctx.moveTo(-5, -8);
        ctx.lineTo(5, 0);
        ctx.lineTo(-5, 8);
        ctx.fill();
        ctx.restore();
    }
  };

  const drawLaser = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
     ctx.fillStyle = '#111';
     ctx.beginPath();
     ctx.arc(0, 0, 10, 0, Math.PI * 2);
     ctx.fill();
     ctx.strokeStyle = '#ef4444';
     ctx.lineWidth = 2;
     ctx.stroke();

     if (obj.active) {
         const len = obj.height || 300;
         ctx.beginPath();
         ctx.moveTo(0, 0);
         ctx.lineTo(len, 0); 

         ctx.shadowColor = '#ef4444';
         ctx.shadowBlur = 15;
         ctx.strokeStyle = '#fca5a5';
         ctx.lineWidth = 4;
         ctx.stroke();

         ctx.shadowBlur = 0;
         ctx.strokeStyle = '#fff';
         ctx.lineWidth = 1;
         ctx.stroke();
     } else {
         ctx.fillStyle = timeRef.current % 30 < 15 ? '#ef4444' : '#550000';
         ctx.beginPath();
         ctx.arc(0, 0, 4, 0, Math.PI * 2);
         ctx.fill();
     }
  };

  const drawTeleporter = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle, isExit = false) => {
      const opacity = obj.timer !== undefined ? obj.timer : 1.0;
      if (opacity < 0.1 && !isExit) return; 

      ctx.save();
      ctx.globalAlpha = isExit ? 1.0 : opacity; 

      const radius = obj.width / 2;
      const angleOffset = timeRef.current * (isExit ? -0.1 : 0.1);
      const isBackwards = (obj.destY || 0) < obj.y;

      const primaryColor = isExit ? '#06b6d4' : (isBackwards ? '#ef4444' : '#d946ef');
      const glowColor = isExit ? 'rgba(6,182,212,0.5)' : (isBackwards ? 'rgba(239, 68, 68, 0.5)' : 'rgba(217,70,239,0.5)');

      ctx.beginPath();
      ctx.arc(0, 0, radius, 0, Math.PI * 2);
      ctx.strokeStyle = primaryColor;
      ctx.lineWidth = 3;
      ctx.shadowColor = primaryColor;
      ctx.shadowBlur = 10 * opacity;
      ctx.stroke();
      ctx.shadowBlur = 0;

      ctx.save();
      ctx.rotate(angleOffset);
      for(let i=0; i<3; i++) {
          ctx.rotate((Math.PI * 2) / 3);
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.quadraticCurveTo(radius/2, 0, radius, radius/2);
          ctx.strokeStyle = glowColor;
          ctx.lineWidth = 2;
          ctx.stroke();
      }
      ctx.restore();

      ctx.fillStyle = '#fff';
      ctx.font = '10px Arial';
      ctx.textAlign = 'center';

      let label = isExit ? 'OUT' : (isBackwards ? 'TRAP' : 'IN');
      if (!isExit && opacity < 0.3) label = ''; 

      ctx.fillText(label, 0, 4);
      ctx.restore(); 
  };

  const drawParticles = (ctx: CanvasRenderingContext2D) => {
      particlesRef.current.forEach(p => {
          ctx.globalAlpha = p.life;
          ctx.fillStyle = p.color;
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
          ctx.fill();
      });
      ctx.globalAlpha = 1.0;
  };

  const drawLeaderboard = (ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) => {
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 110; // Slightly wider for names
    const itemHeight = 18;
    const startX = 10; 
    const startY = 90; 

    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.font = 'bold 10px "Roboto Mono"'; 
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    sorted.forEach((m, index) => {
       const y = startY + 10 + index * itemHeight; 

       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#6b7280';
       ctx.fillText(`${index + 1}.`, startX + 5, y);

       // Small colored dot fallback if needed, but mainly name color
       ctx.fillStyle = m.color; 
       ctx.beginPath();
       ctx.arc(startX + 25, y, 3, 0, Math.PI*2);
       ctx.fill();

       ctx.fillStyle = m.finished ? '#10b981' : '#e5e7eb';
       ctx.fillText(m.name, startX + 35, y);

       if (m.id === betMarbleId) {
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 1;
          ctx.strokeRect(startX + 2, y - 8, boxWidth - 4, 16);
       }
    });
  };

  // --- Render Loop ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Static Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa';
      if (l.type === 'wall') ctx.lineWidth = 6;
      else ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
      ctx.stroke();
    });

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       if (obj.type === 'teleporter') {
           ctx.save();
           ctx.translate(obj.x, obj.y);
           drawTeleporter(ctx, obj, false);
           ctx.restore();
           if (obj.destX !== undefined && obj.destY !== undefined) {
               ctx.save();
               ctx.translate(obj.destX, obj.destY);
               drawTeleporter(ctx, obj, true);
               ctx.restore();
           }
           return;
       }

       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);

          const range = obj.height || 200;
          const gradient = ctx.createLinearGradient(0, 0, range, 0);
          gradient.addColorStop(0, 'rgba(255, 255, 255, 0.4)');
          gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

          ctx.fillStyle = gradient;
          ctx.fillRect(0, -obj.width/2, range, obj.width);

          ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
          ctx.lineWidth = 1;
          const offset = (timeRef.current * 5) % 50;
          for(let i=0; i<3; i++) {
             const yPos = -obj.width/2 + (obj.width/4) * (i+1);
             ctx.beginPath();
             ctx.moveTo(10 + offset, yPos);
             ctx.lineTo(range - 20, yPos);
             ctx.stroke();
          }

       } else if (obj.type === 'repulsor') {
          drawRepulsor(ctx, obj);
       } else if (obj.type === 'conveyor') {
          drawConveyor(ctx, obj);
       } else if (obj.type === 'laser') {
          drawLaser(ctx, obj);
       } else if (obj.type === 'hollow_circle') {
             const r = obj.width / 2;
             const gap = obj.range || 1.0;

             ctx.beginPath();
             ctx.arc(0, 0, r, gap/2, Math.PI * 2 - gap/2);
             ctx.strokeStyle = '#d946ef'; 
             ctx.lineWidth = 12;
             ctx.lineCap = 'round'; 
             ctx.stroke();

             ctx.beginPath();
             ctx.arc(0, 0, r - 10, 0, Math.PI * 2);
             ctx.strokeStyle = 'rgba(217, 70, 239, 0.3)';
             ctx.lineWidth = 2;
             ctx.stroke();
       } else {
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();

         if (obj.type === 'spinner') {
           ctx.beginPath();
           ctx.arc(0, 0, 5, 0, Math.PI * 2);
           ctx.fillStyle = '#fff';
           ctx.fill();
         }
       }
       ctx.restore();
    });

    // DRAW GATE (If Closed)
    if (!gateOpenRef.current) {
        ctx.beginPath();
        ctx.moveTo(0, GATE_Y);
        ctx.lineTo(COURSE_WIDTH, GATE_Y);
        ctx.strokeStyle = '#ef4444'; // Red barrier
        ctx.lineWidth = 10;
        ctx.stroke();

        // Draw Countdown Text
        const elapsed = Date.now() - startTime.current;
        const timeLeft = Math.max(0, Math.ceil((GATE_DELAY - elapsed) / 1000));

        ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
        ctx.font = 'bold 80px "Righteous"';
        ctx.textAlign = 'center';
        ctx.fillText(timeLeft.toString(), COURSE_WIDTH / 2, GATE_Y + 150);
        ctx.font = '20px "Roboto Mono"';
        ctx.fillText("PREPARAR...", COURSE_WIDTH / 2, GATE_Y + 180);
    }

    drawParticles(ctx);

    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    // Draw Finish Line
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    for(let i=0; i<20; i++) {
        ctx.fillStyle = i%2===0 ? '#fff' : '#000';
        ctx.fillRect(i * (COURSE_WIDTH/20), finishLineY.current, COURSE_WIDTH/20, 10);
    }

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(-m.angle); 

      // Draw Background Circle (White) to make transparency logos pop
      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.fillStyle = '#ffffff';
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 5;
      ctx.fill();
      ctx.shadowBlur = 0;

      // Draw Logo Image clipped to circle
      ctx.save();
      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.clip();

      const img = imagesRef.current[m.id];
      if (img && img.complete && img.naturalHeight !== 0) {
        ctx.drawImage(img, -m.radius, -m.radius, m.radius * 2, m.radius * 2);
      } else {
        // Fallback: Solid Color if image fails
        ctx.fillStyle = m.color;
        ctx.fill();
      }
      ctx.restore();

      // Draw Border Ring (Team Color)
      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.strokeStyle = m.color;
      ctx.lineWidth = 2;
      ctx.stroke();

      // Glass Shine Effect
      ctx.beginPath();
      ctx.arc(-m.radius*0.3, -m.radius*0.3, m.radius*0.25, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.4)';
      ctx.fill();

      ctx.restore(); 

      // Selection Highlight
      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.radius + 6, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (!m.finished) {
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - m.radius - 8);
      }
    });

    ctx.restore(); 

    drawLeaderboard(ctx, canvas.width, canvas.height);
  };

  useEffect(() => {
    const loop = () => {
      update();
      draw();
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings, GameMode } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
  gameMode: GameMode;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, isFollowingBet, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Pinball Kicker State
  const lineActivityRef = useRef<Record<number, number>>({}); // index -> frames remaining

  // Cache for loaded images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);
  const gateOpenRef = useRef(false);

  // Constants
  const COURSE_WIDTH = 600;
  const GATE_Y = 180; // Position of the starting gate
  const GATE_DELAY = 3000; // Time before gate opens (ms)

  // --- Particle Helper ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03, // Random fade speed
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 12 + Math.floor(Math.random() * 4); 
    const segmentHeight = 450;
    let currentY = 0;

    // --- OBSTÁCULO INICIAL: PLINKO DE PINOS MÓVEIS ---
    const plinkoStartY = GATE_Y + 100;
    const plinkoRows = 10; 
    const plinkoRowHeight = 55; 
    const plinkoEndY = plinkoStartY + (plinkoRows * plinkoRowHeight);

    // Paredes
    lines.push({ x1: 0, y1: 0, x2: 0, y2: plinkoEndY, type: 'wall' }); 
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH, y2: plinkoEndY, type: 'wall' }); 

    // Gerar Pinos Móveis com Espaçamento Igual
    for (let r = 0; r < plinkoRows; r++) {
        const py = plinkoStartY + (r * plinkoRowHeight);
        const isEven = r % 2 === 0;
        const pinRadius = 9;
        const spacing = 70; 
        const rowSpeed = 0.05 * (isEven ? 1 : -1); 
        const rowRange = 70; 
        const startX = 35;

        for (let x = startX; x < COURSE_WIDTH; x += spacing) {
             pins.push({
                 x: x, 
                 y: py,
                 radius: pinRadius, 
                 type: 'pin',
                 initialX: x,
                 speed: rowSpeed,
                 range: rowRange
             });
        }
    }

    // --- FUNIL PÓS-PLINKO ---
    const funnelHeight = 180;
    const funnelExitGap = 70;

    lines.push({
        x1: 0, y1: plinkoEndY,
        x2: COURSE_WIDTH / 2 - funnelExitGap / 2, y2: plinkoEndY + funnelHeight,
        type: 'wall'
    });

    lines.push({
        x1: COURSE_WIDTH, y1: plinkoEndY,
        x2: COURSE_WIDTH / 2 + funnelExitGap / 2, y2: plinkoEndY + funnelHeight,
        type: 'wall'
    });

    currentY = plinkoEndY + funnelHeight + 50;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 10 });
            options.push({ type: 'slider_v', weight: 10 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 15 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 10 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 4 });

        if (options.length === 0) return 'none';
        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;
        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = pickObstacleType();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      // Randomized side bar size (Pinball Kickers)
      const getSideWidth = () => COURSE_WIDTH * (0.15 + Math.random() * 0.25);

      if (type === 'spinner') {
        const sw = getSideWidth();
        lines.push({ x1: 0, y1: currentY, x2: sw, y2: currentY + 100, type: 'bouncer' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH - sw, y2: currentY + 100, type: 'bouncer' });
        dynamics.push({ id: `spin_${i}_1`, type: 'spinner', x: COURSE_WIDTH * 0.35, y: currentY + 250, width: 150, angle: 0, speed: 0.12 });
        dynamics.push({ id: `spin_${i}_2`, type: 'spinner', x: COURSE_WIDTH * 0.65, y: currentY + 350, width: 150, angle: Math.PI / 2, speed: -0.15 });
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 300, radius: 25, type: 'bumper' });
      } else if (type === 'slider_h') {
        const sw = getSideWidth();
        lines.push({ x1: 0, y1: currentY + 50, x2: sw, y2: currentY + 150, type: 'bouncer' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH - sw, y2: currentY + 150, type: 'bouncer' });
        dynamics.push({ id: `slide_h_top_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 200, width: 200, angle: 0, speed: 2.5, range: 180, initialX: COURSE_WIDTH / 2, initialY: currentY + 200 });
        dynamics.push({ id: `slide_h_bot_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 350, width: 200, angle: 0, speed: -3.0, range: 180, initialX: COURSE_WIDTH / 2, initialY: currentY + 350 });
      } else if (type === 'slider_v') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });
        dynamics.push({ id: `slide_v_L_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.25, y: currentY + 250, width: 120, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.25, initialY: currentY + 250 });
        dynamics.push({ id: `slide_v_R_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.75, y: currentY + 350, width: 120, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.75, initialY: currentY + 350 });
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 300, radius: 28, type: 'bumper' });
      } else if (type === 'repulsor') {
        const sw = getSideWidth();
        lines.push({ x1: 0, y1: currentY + 50, x2: sw, y2: currentY + 150, type: 'bouncer' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH - sw, y2: currentY + 150, type: 'bouncer' });
        dynamics.push({ id: `repulse_${i}`, type: 'repulsor', x: COURSE_WIDTH / 2, y: currentY + 300, width: 50, range: 140, angle: 0, speed: 0.1, force: 3.0 });
      } else if (type === 'conveyor') {
        const dirType = Math.floor(Math.random() * 5);
        let angle = Math.PI / 2; let cx = COURSE_WIDTH * 0.5; let width = 200; let height = 100; 
        if (dirType === 1) { angle = Math.PI / 4; cx = COURSE_WIDTH * 0.4; } 
        else if (dirType === 2) { angle = 3 * Math.PI / 4; cx = COURSE_WIDTH * 0.6; } 
        else if (dirType === 3) { angle = 0; cx = COURSE_WIDTH * 0.3; width = 150; height = 150; } 
        else if (dirType === 4) { angle = Math.PI; cx = COURSE_WIDTH * 0.7; width = 150; height = 150; }
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'wall' });
        dynamics.push({ id: `conveyor_${i}`, type: 'conveyor', x: cx, y: currentY + 250, width: width, height: height, angle: angle, speed: 0.1, force: 18 });
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 250, radius: 20, type: 'bumper' });
      } else if (type === 'teleporter') {
        const sw = getSideWidth();
        lines.push({ x1: 0, y1: currentY + 50, x2: sw, y2: currentY + 150, type: 'bouncer' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH - sw, y2: currentY + 150, type: 'bouncer' });
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        let targetY = Math.random() > 0.5 ? Math.max(100, currentY - (300 + Math.random() * 400)) : currentY + (500 + Math.random() * 300);
        dynamics.push({ id: `teleport_${i}`, type: 'teleporter', x: entranceX, y: currentY + 200, width: 70, destX: exitX, destY: targetY, angle: 0, speed: 0, blinkPhase: Math.random() * Math.PI * 2, blinkSpeed: 0.02 + Math.random() * 0.02, active: true });
        pins.push({ x: entranceX + (Math.random() > 0.5 ? 80 : -80), y: currentY + 200, radius: 20, type: 'bumper' });
      } else if (type === 'hollow_circle') {
        const sw = getSideWidth();
        lines.push({ x1: 0, y1: currentY + 50, x2: sw, y2: currentY + 150, type: 'bouncer' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH - sw, y2: currentY + 150, type: 'bouncer' });
        dynamics.push({ id: `hollow_${i}`, type: 'hollow_circle', x: COURSE_WIDTH / 2 + (Math.random() - 0.5) * 60, y: currentY + 250, width: 250, angle: 0, speed: (Math.random() > 0.5 ? 1 : -1) * (0.02 + Math.random() * 0.02), range: Math.PI / 2.5 });
      } else if (type === 'laser') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });
        dynamics.push({ id: `laser_${i}`, type: 'laser', x: COURSE_WIDTH * 0.1, y: currentY + 300, width: 0, height: COURSE_WIDTH * 0.8, angle: 0, speed: 0, force: 25, active: true, timer: 0 });
        lines.push({ x1: 0, y1: currentY + 280, x2: COURSE_WIDTH * 0.15, y2: currentY + 320, type: 'wall' });
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 300, radius: 22, type: 'bumper' });
      } else if (type === 'funnel') {
        const funnelTopY = currentY + 50; const funnelHeight = 250; const exitGap = 55;
        lines.push({ x1: 0, y1: funnelTopY, x2: COURSE_WIDTH/2 - exitGap/2, y2: funnelTopY + funnelHeight, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: funnelTopY, x2: COURSE_WIDTH/2 + exitGap/2, y2: funnelTopY + funnelHeight, type: 'wall' });
        pins.push({ x: COURSE_WIDTH/2, y: funnelTopY + funnelHeight + 80, radius: 20, type: 'bumper' });
      } else if (type === 'fan') {
        const sw = getSideWidth();
        lines.push({ x1: 0, y1: currentY, x2: sw, y2: currentY + 100, type: 'bouncer' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH - sw, y2: currentY + 100, type: 'bouncer' });
        dynamics.push({ id: `fan_${i}_1`, type: 'fan', x: 20, y: currentY + 250, width: 40, height: 300, angle: 0, speed: 0, force: 0.7 });
        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 25, type: 'bumper' });
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 200, radius: 15, type: 'bumper' });
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 350, radius: 15, type: 'bumper' });
      }
      currentY += segmentHeight;
    }

    const finalSw = COURSE_WIDTH * (0.2 + Math.random() * 0.15);
    lines.push({ x1: 0, y1: currentY, x2: finalSw, y2: currentY + 200, type: 'bouncer' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH - finalSw, y2: currentY + 200, type: 'bouncer' });

    finishLineY.current = currentY + 250;
    linesRef.current = lines; pinsRef.current = pins; dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (isPaused || raceFinished.current) { audio.updateRolling(0); return; }

    // Gate Logic
    const timeSinceStart = Date.now() - startTime.current;
    if (!gateOpenRef.current && timeSinceStart > GATE_DELAY) {
        gateOpenRef.current = true;
        audio.playPinHit(15);
        spawnParticles(COURSE_WIDTH/2, GATE_Y, '#10b981', 30, 8);
    }

    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    // Randomly activate pinball kickers
    if (Math.random() < 0.008) {
        const bouncerIndices = linesRef.current.reduce((acc, l, idx) => {
            if (l.type === 'bouncer') acc.push(idx);
            return acc;
        }, [] as number[]);
        if (bouncerIndices.length > 0) {
            const randomIdx = bouncerIndices[Math.floor(Math.random() * bouncerIndices.length)];
            lineActivityRef.current[randomIdx] = 12; // Active for ~200ms
            // Only play audio if near camera
            const l = linesRef.current[randomIdx];
            if (Math.abs(l.y1 - cameraY.current) < 800) audio.playPinHit(8);
        }
    }
    // Decay timers
    Object.keys(lineActivityRef.current).forEach(key => {
        const idx = parseInt(key);
        lineActivityRef.current[idx]--;
        if (lineActivityRef.current[idx] <= 0) delete lineActivityRef.current[idx];
    });

    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx; p.y += p.vy; p.life -= p.decay;
        if (p.life <= 0) particlesRef.current.splice(i, 1);
    }

    let totalSpeed = 0;

    // Mercy Rule
    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    const totalMarbles = marbles.length;
    if (totalMarbles > 1 && activeMarblesCount === 1 && gameMode !== 'inverted_elimination') {
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = totalMarbles; 
            loser.finishTime = now - startTime.current + 99999; 
        }
        if (!raceFinished.current) {
            raceFinished.current = true;
            const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
            audio.playFinish(); 
            setTimeout(() => onRaceFinish(sorted), 1000);
            return;
        }
    }

    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner' || obj.type === 'hollow_circle') obj.angle += obj.speed;
      else if (obj.type === 'slider_h') obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      else if (obj.type === 'slider_v') obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      else if (obj.type === 'laser') { obj.timer = (obj.timer || 0) + 1; if (obj.timer > 180) { obj.active = !obj.active; obj.timer = 0; } }
      else if (obj.type === 'teleporter') { if (obj.blinkPhase !== undefined && obj.blinkSpeed !== undefined) { const val = Math.sin(timeRef.current * obj.blinkSpeed + obj.blinkPhase); const opacity = (val + 1) / 2; obj.active = opacity > 0.3; obj.timer = opacity; } }
    });
    pinsRef.current.forEach(pin => { if (pin.initialX !== undefined && pin.speed !== undefined && pin.range !== undefined) pin.x = pin.initialX + Math.sin(timeRef.current * pin.speed) * pin.range; });

    const dynamicLines: LineSegment[] = [];
    dynamicObjs.forEach(obj => { if (['spinner', 'slider_h', 'slider_v'].includes(obj.type)) { const halfW = obj.width / 2; const dx = Math.cos(obj.angle) * halfW; const dy = Math.sin(obj.angle) * halfW; dynamicLines.push({ x1: obj.x - dx, y1: obj.y - dy, x2: obj.x + dx, y2: obj.y + dy, type: obj.type === 'spinner' ? 'bouncer' : 'floor' }); } });
    const gateLine: LineSegment = { x1: 0, y1: GATE_Y, x2: COURSE_WIDTH, y2: GATE_Y, type: 'wall' };

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i]; if (m.finished) continue;
        m.vy += config.gravity * dt; m.x += m.vx * dt; m.y += m.vy * dt;
        if (m.x < m.radius) { m.x = m.radius; m.vx = Math.abs(m.vx) * 0.5; } else if (m.x > COURSE_WIDTH - m.radius) { m.x = COURSE_WIDTH - m.radius; m.vx = -Math.abs(m.vx) * 0.5; }

        dynamicObjs.forEach(obj => {
          if (obj.type === 'fan') {
            const dx = m.x - obj.x; const dy = m.y - obj.y; const localX = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle); const localY = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle);
            if (localX > 0 && localX < (obj.height || 200) && Math.abs(localY) < obj.width / 2) { const force = obj.force || 0.5; m.vx += Math.cos(obj.angle) * force * dt; m.vy += Math.sin(obj.angle) * force * dt; if (Math.random() < 0.1) spawnParticles(m.x, m.y, '#e2e8f0', 1, 1); }
          } else if (obj.type === 'repulsor') {
            const dx = m.x - obj.x; const dy = m.y - obj.y; const distSq = dx*dx + dy*dy; const range = obj.range || 100;
            if (distSq < range * range) { const dist = Math.sqrt(distSq); const force = (obj.force || 1) * (1 - dist/range) * (0.5 + (Math.sin(timeRef.current * obj.speed) + 1) * 0.5); m.vx += (dx/dist) * force * dt * 50; m.vy += (dy/dist) * force * dt * 50; }
          } else if (obj.type === 'conveyor') {
            const dx = m.x - obj.x; const dy = m.y - obj.y; const localParallel = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle); const localPerp = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle);
            if (Math.abs(localParallel) < obj.width / 2 && Math.abs(localPerp) < (obj.height || 50) / 2) { const force = obj.force || 10; m.vx += Math.cos(obj.angle) * force * dt; m.vy += Math.sin(obj.angle) * force * dt; if (Math.random() < 0.05) spawnParticles(m.x, m.y, 'rgba(255,255,255,0.3)', 1, 0.5); }
          } else if (obj.type === 'laser' && obj.active) {
            const len = obj.height || 300; const lx1 = obj.x; const ly1 = obj.y; const lx2 = lx1 + Math.cos(obj.angle) * len; const ly2 = ly1 + Math.sin(obj.angle) * len;
            const A = m.x - lx1; const B = m.y - ly1; const C = lx2 - lx1; const D = ly2 - ly1; const dot = A * C + B * D; const lenSq = C * C + D * D; let param = lenSq !== 0 ? dot / lenSq : -1;
            let xx = param < 0 ? lx1 : (param > 1 ? lx2 : lx1 + param * C), yy = param < 0 ? ly1 : (param > 1 ? ly2 : ly1 + param * D);
            const dx = m.x - xx; const dy = m.y - yy; const dist = Math.sqrt(dx * dx + dy * dy);
            if (dist < m.radius + 5) { const force = laser.force || 20; m.vx += (dx/dist) * force * dt * 10; m.vy += (dy/dist) * force * dt * 10; spawnParticles(m.x, m.y, '#ef4444', 3, 4); }
          } else if (obj.type === 'teleporter' && obj.active) {
            const dx = m.x - obj.x; const dy = m.y - obj.y; if (Math.sqrt(dx*dx + dy*dy) < obj.width/2 && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) { spawnParticles(m.x, m.y, (obj.destY||0)<obj.y ? '#ef4444' : '#d946ef', 15, 4); m.x = obj.destX || m.x; m.y = obj.destY || m.y; m.vx *= 0.2; m.vy = (obj.destY||0)<obj.y ? 0 : Math.abs(m.vy) + 2; teleportCooldowns.current[m.id] = now + 1500; audio.playPinHit(8); spawnParticles(m.x, m.y, '#06b6d4', 15, 4); }
          } else if (obj.type === 'hollow_circle') {
            const dx = m.x - obj.x; const dy = m.y - obj.y; const dist = Math.sqrt(dx*dx + dy*dy); const r = obj.width / 2;
            if (dist + m.radius >= r - 6 && dist - m.radius <= r + 6) { let angle = Math.atan2(dy, dx); if (angle < 0) angle += Math.PI * 2; let rot = obj.angle % (Math.PI * 2); if (rot < 0) rot += Math.PI * 2; let diff = Math.abs(angle - rot); if (diff > Math.PI) diff = Math.PI * 2 - diff; if (diff >= (obj.range || 1.0) / 2) { const nx = dx / dist; const ny = dy / dist; const ps = dist < r ? -1 : 1; const overlap = (m.radius + 6) - Math.abs(dist - r); if (overlap > 0) { m.x += nx * ps * overlap * 0.5; m.y += ny * ps * overlap * 0.5; const nX = nx * ps, nY = ny * ps, dot = m.vx * nX + m.vy * nY; m.vx = (m.vx - 2 * dot * nX) * config.restitution; m.vy = (m.vy - 2 * dot * nY) * config.restitution; m.vx *= config.friction; m.vy *= config.friction; } } }
          }
        });

        m.angle += m.omega * dt; m.omega *= 0.999; m.vx *= Math.pow(config.friction, dt); m.vy *= Math.pow(config.friction, dt);
        if (m.vx*m.vx + m.vy*m.vy < 0.2) { m.vx += (Math.random() - 0.5); m.vy += 0.5; }

        if (!gateOpenRef.current) checkLineCollision(m, gateLine);
        linesRef.current.forEach((l, idx) => checkLineCollision(m, l, false, idx));
        dynamicLines.forEach(dl => checkLineCollision(m, dl, true));
        pinsRef.current.forEach(p => checkPinCollision(m, p));
        for (let j = i + 1; j < marbles.length; j++) if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);

        if (m.y > finishLineY.current) {
          m.finished = true; m.finishTime = now - startTime.current; m.rank = marbles.filter(b => b.finished).length; audio.playPinHit(10); spawnParticles(m.x, m.y, '#10b981', 10, 4);
          if (gameMode === 'inverted_elimination') { raceFinished.current = true; onRaceFinish(marblesRef.current); return; }
        }
        if (!m.finished) totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
      }
    }
    audio.updateRolling(totalSpeed);
    let targetY = cameraY.current;
    if (isFollowingBet && betMarbleId !== null && !marbles.find(m => m.id === betMarbleId)?.finished) targetY = (marbles.find(m => m.id === betMarbleId)?.y || 0) - 300;
    else if (marbles.filter(m => !m.finished).length > 0) targetY = marbles.filter(m => !m.finished).sort((a, b) => b.y - a.y)[0].y - 300;
    cameraY.current += (targetY - cameraY.current) * 0.08;
    if (marbles.filter(m => !m.finished).length === 0 && !raceFinished.current) { raceFinished.current = true; onRaceFinish([...marbles].sort((a, b) => a.rank - b.rank)); }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean, cx: number, cy: number, customRestitution?: number) => {
    const vDotN = ball.vx * nx + ball.vy * ny; if (vDotN > 0) return; 
    const intensity = Math.abs(vDotN); if (intensity > 1.0) { audio.playBump(intensity); if (intensity > 3.0) spawnParticles(cx, cy, isBouncy ? '#ef4444' : '#94a3b8', Math.floor(intensity), intensity * 0.5); }

    const res = customRestitution !== undefined ? customRestitution : (isBouncy ? 1.5 : config.restitution);
