    const closeX = line.x1 + t * dx, closeY = line.y1 + t * dy, distX = ball.x - closeX, distY = ball.y - closeY, distSq = distX*distX + distY*distY;
    if (distSq < ball.radius * ball.radius) { 
        const dist = Math.sqrt(distSq), nx = distX / dist, ny = distY / dist; 
        ball.x += nx * (ball.radius - dist); ball.y += ny * (ball.radius - dist); 

        const isActiveKicker = lineIndex !== undefined && lineActivityRef.current[lineIndex] > 0;
        const kickerRestitution = isActiveKicker ? 3.0 : undefined;

        resolveCollisionPhysics(ball, nx, ny, (isDynamic || line.type === 'bouncer') || isActiveKicker, closeX, closeY, kickerRestitution); 
        if (isDynamic) { ball.vx += (Math.random() - 0.5) * 2; ball.vy += (Math.random() - 0.5) * 2; } 
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x, dy = ball.y - pin.y, distSq = dx*dx + dy*dy, minDist = ball.radius + pin.radius;
    if (distSq < minDist * minDist) { const dist = Math.sqrt(distSq), nx = dx / dist, ny = dy / dist; ball.x += nx * (minDist - dist); ball.y += ny * (minDist - dist); if (dist > 1) audio.playPinHit(dist); resolveCollisionPhysics(ball, nx, ny, pin.type === 'bumper', pin.x + nx * pin.radius, pin.y + ny * pin.radius); }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x, dy = m2.y - m1.y, distSq = dx*dx + dy*dy, minDist = m1.radius + m2.radius;
    if (distSq < minDist * minDist) { const dist = Math.sqrt(distSq), nx = dx / dist, ny = dy / dist, overlap = (minDist - dist) * 0.5; m1.x -= nx * overlap; m1.y -= ny * overlap; m2.x += nx * overlap; m2.y += ny * overlap; const dvx = m1.vx - m2.vx, dvy = m1.vy - m2.vy, dot = dvx * nx + dvy * ny; if (dot > 0) { if (dot > 2) audio.playPinHit(dot * 0.5); const impulse = dot * 0.9; m1.vx -= impulse * nx; m1.vy -= impulse * ny; m2.vx += impulse * nx; m2.vy += impulse * ny; } }
  };

  useEffect(() => {
    generateLevel(); raceFinished.current = false; gateOpenRef.current = false; startTime.current = Date.now(); cameraY.current = 0; timeRef.current = 0; teleportCooldowns.current = {}; particlesRef.current = []; lineActivityRef.current = {};
    activeMarbles.forEach(m => { const img = new Image(); img.src = m.logoUrl; imagesRef.current[m.id] = img; });
    const spacing = (COURSE_WIDTH * 0.9) / Math.max(1, activeMarbles.length);
    marblesRef.current = activeMarbles.map((m, index) => ({ ...m, x: COURSE_WIDTH * 0.05 + (spacing * index) + (spacing/2), y: GATE_Y - 50, vx: 0, vy: 0, angle: 0, omega: 0, finished: false, rank: 0 }));
    audio.resume();
  }, [activeMarbles]); 

  const draw = () => {
    const canvas = canvasRef.current; if (!canvas) return; const ctx = canvas.getContext('2d'); if (!ctx) return;
    if (canvas.width !== canvas.offsetWidth || canvas.height !== canvas.offsetHeight) { canvas.width = canvas.offsetWidth; canvas.height = canvas.offsetHeight; }
    ctx.fillStyle = '#1f2937'; ctx.fillRect(0, 0, canvas.width, canvas.height); ctx.save(); const scale = canvas.width / COURSE_WIDTH; ctx.scale(scale, scale);
    ctx.translate(0, -Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100)));

    linesRef.current.forEach((l, idx) => { 
        const isActive = lineActivityRef.current[idx] > 0;
        ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : (isActive ? '#fff' : (l.type === 'bouncer' ? '#fbbf24' : '#60a5fa')); 
        ctx.lineWidth = l.type === 'wall' ? 6 : 4; 

        if (isActive) {
            ctx.shadowBlur = 15;
            ctx.shadowColor = '#fff';
        }

        ctx.beginPath(); ctx.moveTo(l.x1, l.y1); ctx.lineTo(l.x2, l.y2); ctx.stroke(); 
        ctx.shadowBlur = 0;
    });

    dynamicRef.current.forEach(obj => {
       ctx.save(); ctx.translate(obj.x, obj.y); ctx.rotate(obj.angle);
       if (obj.type === 'teleporter') { const opacity = obj.timer || 1; const r = obj.width/2; ctx.globalAlpha = opacity; ctx.beginPath(); ctx.arc(0,0,r,0,Math.PI*2); ctx.strokeStyle = (obj.destY||0)<obj.y ? '#ef4444' : '#d946ef'; ctx.lineWidth = 3; ctx.stroke(); }
       else if (obj.type === 'fan') { ctx.fillStyle = '#64748b'; ctx.fillRect(-10, -obj.width/2, 20, obj.width); const grad = ctx.createLinearGradient(0,0,obj.height||200,0); grad.addColorStop(0,'rgba(255,255,255,0.4)'); grad.addColorStop(1,'rgba(255,255,255,0)'); ctx.fillStyle = grad; ctx.fillRect(0,-obj.width/2,obj.height||200,obj.width); }
       else if (obj.type === 'laser' && obj.active) { ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(obj.height||300,0); ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 4; ctx.stroke(); }
       else if (obj.type === 'hollow_circle') { ctx.beginPath(); ctx.arc(0,0,obj.width/2, (obj.range||1)/2, Math.PI*2-(obj.range||1)/2); ctx.strokeStyle='#d946ef'; ctx.lineWidth=12; ctx.stroke(); }
