const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, isFollowingBet, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Pinball Kicker State
  const lineActivityRef = useRef<Record<number, number>>({}); // index -> frames remaining

  // Cache for loaded images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);
  const gateOpenRef = useRef(false);

  // Constants
  const COURSE_WIDTH = 600;
  const GATE_Y = 180; // Position of the starting gate
  const GATE_DELAY = 3000; // Time before gate opens (ms)

  // --- Particle Helper ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03, // Random fade speed
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 12 + Math.floor(Math.random() * 4); 
    const segmentHeight = 450;
    let currentY = 0;

    // --- OBSTÁCULO INICIAL: PLINKO DE PINOS MÓVEIS ---
    const plinkoStartY = GATE_Y + 100;
    const plinkoRows = 10; 
    const plinkoRowHeight = 55; 
    const plinkoEndY = plinkoStartY + (plinkoRows * plinkoRowHeight);

    // Paredes
    lines.push({ x1: 0, y1: 0, x2: 0, y2: plinkoEndY, type: 'wall' }); 
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH, y2: plinkoEndY, type: 'wall' }); 

    // Gerar Pinos Móveis com Espaçamento Igual
    for (let r = 0; r < plinkoRows; r++) {
        const py = plinkoStartY + (r * plinkoRowHeight);
        const isEven = r % 2 === 0;
        const pinRadius = 9;
        const spacing = 70; 
        const rowSpeed = 0.05 * (isEven ? 1 : -1); 
        const rowRange = 70; 
        const startX = 35;

        for (let x = startX; x < COURSE_WIDTH; x += spacing) {
             pins.push({
                 x: x, 
                 y: py,
                 radius: pinRadius, 
                 type: 'pin',
                 initialX: x,
                 speed: rowSpeed,
                 range: rowRange
             });
        }
    }

    // --- FUNIL PÓS-PLINKO ---
    const funnelHeight = 180;
    const funnelExitGap = 70;

    lines.push({
        x1: 0, y1: plinkoEndY,
        x2: COURSE_WIDTH / 2 - funnelExitGap / 2, y2: plinkoEndY + funnelHeight,
        type: 'wall'
    });

    lines.push({
        x1: COURSE_WIDTH, y1: plinkoEndY,
        x2: COURSE_WIDTH / 2 + funnelExitGap / 2, y2: plinkoEndY + funnelHeight,
        type: 'wall'
    });

    currentY = plinkoEndY + funnelHeight + 50;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 10 });
            options.push({ type: 'slider_v', weight: 10 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 15 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 10 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 4 });

        if (options.length === 0) return 'none';
        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;
        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = pickObstacleType();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      // Randomized side bar size (Pinball Kickers)
      const getSideWidth = () => COURSE_WIDTH * (0.15 + Math.random() * 0.25);

      if (type === 'spinner') {
        const sw = getSideWidth();
        lines.push({ x1: 0, y1: currentY, x2: sw, y2: currentY + 100, type: 'bouncer' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH - sw, y2: currentY + 100, type: 'bouncer' });
        dynamics.push({ id: `spin_${i}_1`, type: 'spinner', x: COURSE_WIDTH * 0.35, y: currentY + 250, width: 150, angle: 0, speed: 0.12 });
        dynamics.push({ id: `spin_${i}_2`, type: 'spinner', x: COURSE_WIDTH * 0.65, y: currentY + 350, width: 150, angle: Math.PI / 2, speed: -0.15 });
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 300, radius: 25, type: 'bumper' });
      } else if (type === 'slider_h') {
        const sw = getSideWidth();
        lines.push({ x1: 0, y1: currentY + 50, x2: sw, y2: currentY + 150, type: 'bouncer' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH - sw, y2: currentY + 150, type: 'bouncer' });
        dynamics.push({ id: `slide_h_top_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 200, width: 200, angle: 0, speed: 2.5, range: 180, initialX: COURSE_WIDTH / 2, initialY: currentY + 200 });
        dynamics.push({ id: `slide_h_bot_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 350, width: 200, angle: 0, speed: -3.0, range: 180, initialX: COURSE_WIDTH / 2, initialY: currentY + 350 });
      } else if (type === 'slider_v') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });
        dynamics.push({ id: `slide_v_L_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.25, y: currentY + 250, width: 120, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.25, initialY: currentY + 250 });
        dynamics.push({ id: `slide_v_R_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.75, y: currentY + 350, width: 120, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.75, initialY: currentY + 350 });
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 300, radius: 28, type: 'bumper' });
      } else if (type === 'repulsor') {
        const sw = getSideWidth();
        lines.push({ x1: 0, y1: currentY + 50, x2: sw, y2: currentY + 150, type: 'bouncer' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH - sw, y2: currentY + 150, type: 'bouncer' });
        dynamics.push({ id: `repulse_${i}`, type: 'repulsor', x: COURSE_WIDTH / 2, y: currentY + 300, width: 50, range: 140, angle: 0, speed: 0.1, force: 3.0 });
      } else if (type === 'conveyor') {
        const dirType = Math.floor(Math.random() * 5);
        let angle = Math.PI / 2; let cx = COURSE_WIDTH * 0.5; let width = 200; let height = 100; 
        if (dirType === 1) { angle = Math.PI / 4; cx = COURSE_WIDTH * 0.4; } 
        else if (dirType === 2) { angle = 3 * Math.PI / 4; cx = COURSE_WIDTH * 0.6; } 
        else if (dirType === 3) { angle = 0; cx = COURSE_WIDTH * 0.3; width = 150; height = 150; } 
        else if (dirType === 4) { angle = Math.PI; cx = COURSE_WIDTH * 0.7; width = 150; height = 150; }
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'wall' });
        dynamics.push({ id: `conveyor_${i}`, type: 'conveyor', x: cx, y: currentY + 250, width: width, height: height, angle: angle, speed: 0.1, force: 18 });
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 250, radius: 20, type: 'bumper' });
      } else if (type === 'teleporter') {
        const sw = getSideWidth();
        lines.push({ x1: 0, y1: currentY + 50, x2: sw, y2: currentY + 150, type: 'bouncer' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH - sw, y2: currentY + 150, type: 'bouncer' });
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        let targetY = Math.random() > 0.5 ? Math.max(100, currentY - (300 + Math.random() * 400)) : currentY + (500 + Math.random() * 300);
        dynamics.push({ id: `teleport_${i}`, type: 'teleporter', x: entranceX, y: currentY + 200, width: 70, destX: exitX, destY: targetY, angle: 0, speed: 0, blinkPhase: Math.random() * Math.PI * 2, blinkSpeed: 0.02 + Math.random() * 0.02, active: true });
        pins.push({ x: entranceX + (Math.random() > 0.5 ? 80 : -80), y: currentY + 200, radius: 20, type: 'bumper' });
      } else if (type === 'hollow_circle') {
        const sw = getSideWidth();
        lines.push({ x1: 0, y1: currentY + 50, x2: sw, y2: currentY + 150, type: 'bouncer' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH - sw, y2: currentY + 150, type: 'bouncer' });
        dynamics.push({ id: `hollow_${i}`, type: 'hollow_circle', x: COURSE_WIDTH / 2 + (Math.random() - 0.5) * 60, y: currentY + 250, width: 250, angle: 0, speed: (Math.random() > 0.5 ? 1 : -1) * (0.02 + Math.random() * 0.02), range: Math.PI / 2.5 });
      } else if (type === 'laser') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });
        dynamics.push({ id: `laser_${i}`, type: 'laser', x: COURSE_WIDTH * 0.1, y: currentY + 300, width: 0, height: COURSE_WIDTH * 0.8, angle: 0, speed: 0, force: 25, active: true, timer: 0 });
        lines.push({ x1: 0, y1: currentY + 280, x2: COURSE_WIDTH * 0.15, y2: currentY + 320, type: 'wall' });
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 300, radius: 22, type: 'bumper' });
      } else if (type === 'funnel') {
        const funnelTopY = currentY + 50; const funnelHeight = 250; const exitGap = 55;
        lines.push({ x1: 0, y1: funnelTopY, x2: COURSE_WIDTH/2 - exitGap/2, y2: funnelTopY + funnelHeight, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: funnelTopY, x2: COURSE_WIDTH/2 + exitGap/2, y2: funnelTopY + funnelHeight, type: 'wall' });
        pins.push({ x: COURSE_WIDTH/2, y: funnelTopY + funnelHeight + 80, radius: 20, type: 'bumper' });
      } else if (type === 'fan') {
        const sw = getSideWidth();
        lines.push({ x1: 0, y1: currentY, x2: sw, y2: currentY + 100, type: 'bouncer' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH - sw, y2: currentY + 100, type: 'bouncer' });
        dynamics.push({ id: `fan_${i}_1`, type: 'fan', x: 20, y: currentY + 250, width: 40, height: 300, angle: 0, speed: 0, force: 0.7 });
        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 25, type: 'bumper' });
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 200, radius: 15, type: 'bumper' });
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 350, radius: 15, type: 'bumper' });
      }
      currentY += segmentHeight;
    }

    const finalSw = COURSE_WIDTH * (0.2 + Math.random() * 0.15);
    lines.push({ x1: 0, y1: currentY, x2: finalSw, y2: currentY + 200, type: 'bouncer' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH - finalSw, y2: currentY + 200, type: 'bouncer' });

    finishLineY.current = currentY + 250;
    linesRef.current = lines; pinsRef.current = pins; dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (isPaused || raceFinished.current) { audio.updateRolling(0); return; }

    // Gate Logic
    const timeSinceStart = Date.now() - startTime.current;
    if (!gateOpenRef.current && timeSinceStart > GATE_DELAY) {
        gateOpenRef.current = true;
        audio.playPinHit(15);
        spawnParticles(COURSE_WIDTH/2, GATE_Y, '#10b981', 30, 8);
    }

    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    // Randomly activate pinball kickers
    if (Math.random() < 0.008) {
        const bouncerIndices = linesRef.current.reduce((acc, l, idx) => {
            if (l.type === 'bouncer') acc.push(idx);
            return acc;
        }, [] as number[]);
        if (bouncerIndices.length > 0) {
            const randomIdx = bouncerIndices[Math.floor(Math.random() * bouncerIndices.length)];
            lineActivityRef.current[randomIdx] = 12; // Active for ~200ms
            // Only play audio if near camera
            const l = linesRef.current[randomIdx];
            if (Math.abs(l.y1 - cameraY.current) < 800) audio.playPinHit(8);
        }
    }
    // Decay timers
    Object.keys(lineActivityRef.current).forEach(key => {
        const idx = parseInt(key);
        lineActivityRef.current[idx]--;
        if (lineActivityRef.current[idx] <= 0) delete lineActivityRef.current[idx];
    });

    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx; p.y += p.vy; p.life -= p.decay;
        if (p.life <= 0) particlesRef.current.splice(i, 1);
    }

    let totalSpeed = 0;

    // Mercy Rule
    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    const totalMarbles = marbles.length;
    if (totalMarbles > 1 && activeMarblesCount === 1 && gameMode !== 'inverted_elimination') {
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = totalMarbles; 
            loser.finishTime = now - startTime.current + 99999; 
        }
        if (!raceFinished.current) {
            raceFinished.current = true;
            const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
            audio.playFinish(); 
            setTimeout(() => onRaceFinish(sorted), 1000);
            return;
        }
    }

    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner' || obj.type === 'hollow_circle') obj.angle += obj.speed;
      else if (obj.type === 'slider_h') obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      else if (obj.type === 'slider_v') obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      else if (obj.type === 'laser') { obj.timer = (obj.timer || 0) + 1; if (obj.timer > 180) { obj.active = !obj.active; obj.timer = 0; } }
      else if (obj.type === 'teleporter') { if (obj.blinkPhase !== undefined && obj.blinkSpeed !== undefined) { const val = Math.sin(timeRef.current * obj.blinkSpeed + obj.blinkPhase); const opacity = (val + 1) / 2; obj.active = opacity > 0.3; obj.timer = opacity; } }
    });
    pinsRef.current.forEach(pin => { if (pin.initialX !== undefined && pin.speed !== undefined && pin.range !== undefined) pin.x = pin.initialX + Math.sin(timeRef.current * pin.speed) * pin.range; });

    const dynamicLines: LineSegment[] = [];
    dynamicObjs.forEach(obj => { if (['spinner', 'slider_h', 'slider_v'].includes(obj.type)) { const halfW = obj.width / 2; const dx = Math.cos(obj.angle) * halfW; const dy = Math.sin(obj.angle) * halfW; dynamicLines.push({ x1: obj.x - dx, y1: obj.y - dy, x2: obj.x + dx, y2: obj.y + dy, type: obj.type === 'spinner' ? 'bouncer' : 'floor' }); } });
    const gateLine: LineSegment = { x1: 0, y1: GATE_Y, x2: COURSE_WIDTH, y2: GATE_Y, type: 'wall' };

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i]; if (m.finished) continue;
        m.vy += config.gravity * dt; m.x += m.vx * dt; m.y += m.vy * dt;
        if (m.x < m.radius) { m.x = m.radius; m.vx = Math.abs(m.vx) * 0.5; } else if (m.x > COURSE_WIDTH - m.radius) { m.x = COURSE_WIDTH - m.radius; m.vx = -Math.abs(m.vx) * 0.5; }

        dynamicObjs.forEach(obj => {
          if (obj.type === 'fan') {
            const dx = m.x - obj.x; const dy = m.y - obj.y; const localX = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle); const localY = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle);
            if (localX > 0 && localX < (obj.height || 200) && Math.abs(localY) < obj.width / 2) { const force = obj.force || 0.5; m.vx += Math.cos(obj.angle) * force * dt; m.vy += Math.sin(obj.angle) * force * dt; if (Math.random() < 0.1) spawnParticles(m.x, m.y, '#e2e8f0', 1, 1); }
          } else if (obj.type === 'repulsor') {
            const dx = m.x - obj.x; const dy = m.y - obj.y; const distSq = dx*dx + dy*dy; const range = obj.range || 100;
            if (distSq < range * range) { const dist = Math.sqrt(distSq); const force = (obj.force || 1) * (1 - dist/range) * (0.5 + (Math.sin(timeRef.current * obj.speed) + 1) * 0.5); m.vx += (dx/dist) * force * dt * 50; m.vy += (dy/dist) * force * dt * 50; }
          } else if (obj.type === 'conveyor') {
            const dx = m.x - obj.x; const dy = m.y - obj.y; const localParallel = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle); const localPerp = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle);
            if (Math.abs(localParallel) < obj.width / 2 && Math.abs(localPerp) < (obj.height || 50) / 2) { const force = obj.force || 10; m.vx += Math.cos(obj.angle) * force * dt; m.vy += Math.sin(obj.angle) * force * dt; if (Math.random() < 0.05) spawnParticles(m.x, m.y, 'rgba(255,255,255,0.3)', 1, 0.5); }
          } else if (obj.type === 'laser' && obj.active) {
            const len = obj.height || 300; const lx1 = obj.x; const ly1 = obj.y; const lx2 = lx1 + Math.cos(obj.angle) * len; const ly2 = ly1 + Math.sin(obj.angle) * len;
            const A = m.x - lx1; const B = m.y - ly1; const C = lx2 - lx1; const D = ly2 - ly1; const dot = A * C + B * D; const lenSq = C * C + D * D; let param = lenSq !== 0 ? dot / lenSq : -1;
            let xx = param < 0 ? lx1 : (param > 1 ? lx2 : lx1 + param * C), yy = param < 0 ? ly1 : (param > 1 ? ly2 : ly1 + param * D);
            const dx = m.x - xx; const dy = m.y - yy; const dist = Math.sqrt(dx * dx + dy * dy);
            // Fix: Replaced 'laser.force' with 'obj.force' to fix the "Cannot find name 'laser'" error.
            if (dist < m.radius + 5) { const force = obj.force || 20; m.vx += (dx/dist) * force * dt * 10; m.vy += (dy/dist) * force * dt * 10; spawnParticles(m.x, m.y, '#ef4444', 3, 4); }
          } else if (obj.type === 'teleporter' && obj.active) {
            const dx = m.x - obj.x; const dy = m.y - obj.y; if (Math.sqrt(dx*dx + dy*dy) < obj.width/2 && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) { spawnParticles(m.x, m.y, (obj.destY||0)<obj.y ? '#ef4444' : '#d946ef', 15, 4); m.x = obj.destX || m.x; m.y = obj.destY || m.y; m.vx *= 0.2; m.vy = (obj.destY||0)<obj.y ? 0 : Math.abs(m.vy) + 2; teleportCooldowns.current[m.id] = now + 1500; audio.playPinHit(8); spawnParticles(m.x, m.y, '#06b6d4', 15, 4); }
          } else if (obj.type === 'hollow_circle') {
            const dx = m.x - obj.x; const dy = m.y - obj.y; const dist = Math.sqrt(dx*dx + dy*dy); const r = obj.width / 2;
            if (dist + m.radius >= r - 6 && dist - m.radius <= r + 6) { let angle = Math.atan2(dy, dx); if (angle < 0) angle += Math.PI * 2; let rot = obj.angle % (Math.PI * 2); if (rot < 0) rot += Math.PI * 2; let diff = Math.abs(angle - rot); if (diff > Math.PI) diff = Math.PI * 2 - diff; if (diff >= (obj.range || 1.0) / 2) { const nx = dx / dist; const ny = dy / dist; const ps = dist < r ? -1 : 1; const overlap = (m.radius + 6) - Math.abs(dist - r); if (overlap > 0) { m.x += nx * ps * overlap * 0.5; m.y += ny * ps * overlap * 0.5; const nX = nx * ps, nY = ny * ps, dot = m.vx * nX + m.vy * nY; m.vx = (m.vx - 2 * dot * nX) * config.restitution; m.vy = (m.vy - 2 * dot * nY) * config.restitution; m.vx *= config.friction; m.vy *= config.friction; } } }
          }
        });

        m.angle += m.omega * dt; m.omega *= 0.999; m.vx *= Math.pow(config.friction, dt); m.vy *= Math.pow(config.friction, dt);
        if (m.vx*m.vx + m.vy*m.vy < 0.2) { m.vx += (Math.random() - 0.5); m.vy += 0.5; }

        if (!gateOpenRef.current) checkLineCollision(m, gateLine);
        linesRef.current.forEach((l, idx) => checkLineCollision(m, l, false, idx));
        dynamicLines.forEach(dl => checkLineCollision(m, dl, true));
        pinsRef.current.forEach(p => checkPinCollision(m, p));
        for (let j = i + 1; j < marbles.length; j++) if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);

        if (m.y > finishLineY.current) {
          m.finished = true; m.finishTime = now - startTime.current; m.rank = marbles.filter(b => b.finished).length; audio.playPinHit(10); spawnParticles(m.x, m.y, '#10b981', 10, 4);
          if (gameMode === 'inverted_elimination') { raceFinished.current = true; onRaceFinish(marblesRef.current); return; }
        }
        if (!m.finished) totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
      }
    }
    audio.updateRolling(totalSpeed);
    let targetY = cameraY.current;
    if (isFollowingBet && betMarbleId !== null && !marbles.find(m => m.id === betMarbleId)?.finished) targetY = (marbles.find(m => m.id === betMarbleId)?.y || 0) - 300;
    else if (marbles.filter(m => !m.finished).length > 0) targetY = marbles.filter(m => !m.finished).sort((a, b) => b.y - a.y)[0].y - 300;
    cameraY.current += (targetY - cameraY.current) * 0.08;
    if (marbles.filter(m => !m.finished).length === 0 && !raceFinished.current) { raceFinished.current = true; onRaceFinish([...marbles].sort((a, b) => a.rank - b.rank)); }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean, cx: number, cy: number, customRestitution?: number) => {
    const vDotN = ball.vx * nx + ball.vy * ny; if (vDotN > 0) return; 
    const intensity = Math.abs(vDotN); if (intensity > 1.0) { audio.playBump(intensity); if (intensity > 3.0) spawnParticles(cx, cy, isBouncy ? '#ef4444' : '#94a3b8', Math.floor(intensity), intensity * 0.5); }

    const res = customRestitution !== undefined ? customRestitution : (isBouncy ? 1.5 : config.restitution);
    const jN = -(1 + res) * vDotN; ball.vx += jN * nx; ball.vy += jN * ny;
    const tx = -ny, ty = nx, vDotT = ball.vx * tx + ball.vy * ty, vSurf = vDotT + ball.omega * ball.radius;
    const jT_ideal = -vSurf / (3.5 / 1.0), maxJt = 0.5 * Math.abs(jN); let jT = Math.abs(jT_ideal) > maxJt ? Math.sign(jT_ideal) * maxJt : jT_ideal;
    ball.vx += jT * tx; ball.vy += jT * ty; ball.omega += (2.5 * jT) / (1.0 * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false, lineIndex?: number) => {
    const dx = line.x2 - line.x1, dy = line.y2 - line.y1, lenSq = dx*dx + dy*dy, t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx, closeY = line.y1 + t * dy, distX = ball.x - closeX, distY = ball.y - closeY, distSq = distX*distX + distY*distY;
    if (distSq < ball.radius * ball.radius) { 
        const dist = Math.sqrt(distSq), nx = distX / dist, ny = distY / dist; 
        ball.x += nx * (ball.radius - dist); ball.y += ny * (ball.radius - dist); 

        const isActiveKicker = lineIndex !== undefined && lineActivityRef.current[lineIndex] > 0;
        const kickerRestitution = isActiveKicker ? 3.0 : undefined;

        resolveCollisionPhysics(ball, nx, ny, (isDynamic || line.type === 'bouncer') || isActiveKicker, closeX, closeY, kickerRestitution); 
        if (isDynamic) { ball.vx += (Math.random() - 0.5) * 2; ball.vy += (Math.random() - 0.5) * 2; } 
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x, dy = ball.y - pin.y, distSq = dx*dx + dy*dy, minDist = ball.radius + pin.radius;
    if (distSq < minDist * minDist) { const dist = Math.sqrt(distSq), nx = dx / dist, ny = dy / dist; ball.x += nx * (minDist - dist); ball.y += ny * (minDist - dist); if (dist > 1) audio.playPinHit(dist); resolveCollisionPhysics(ball, nx, ny, pin.type === 'bumper', pin.x + nx * pin.radius, pin.y + ny * pin.radius); }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x, dy = m2.y - m1.y, distSq = dx*dx + dy*dy, minDist = m1.radius + m2.radius;
    if (distSq < minDist * minDist) { const dist = Math.sqrt(distSq), nx = dx / dist, ny = dy / dist, overlap = (minDist - dist) * 0.5; m1.x -= nx * overlap; m1.y -= ny * overlap; m2.x += nx * overlap; m2.y += ny * overlap; const dvx = m1.vx - m2.vx, dvy = m1.vy - m2.vy, dot = dvx * nx + dvy * ny; if (dot > 0) { if (dot > 2) audio.playPinHit(dot * 0.5); const impulse = dot * 0.9; m1.vx -= impulse * nx; m1.vy -= impulse * ny; m2.vx += impulse * nx; m2.vy += impulse * ny; } }
  };

  useEffect(() => {
    generateLevel(); raceFinished.current = false; gateOpenRef.current = false; startTime.current = Date.now(); cameraY.current = 0; timeRef.current = 0; teleportCooldowns.current = {}; particlesRef.current = []; lineActivityRef.current = {};
    activeMarbles.forEach(m => { const img = new Image(); img.src = m.logoUrl; imagesRef.current[m.id] = img; });
    const spacing = (COURSE_WIDTH * 0.9) / Math.max(1, activeMarbles.length);
    marblesRef.current = activeMarbles.map((m, index) => ({ ...m, x: COURSE_WIDTH * 0.05 + (spacing * index) + (spacing/2), y: GATE_Y - 50, vx: 0, vy: 0, angle: 0, omega: 0, finished: false, rank: 0 }));
    audio.resume();
  }, [activeMarbles]); 

  const draw = () => {
    const canvas = canvasRef.current; if (!canvas) return; const ctx = canvas.getContext('2d'); if (!ctx) return;
    if (canvas.width !== canvas.offsetWidth || canvas.height !== canvas.offsetHeight) { canvas.width = canvas.offsetWidth; canvas.height = canvas.offsetHeight; }
    ctx.fillStyle = '#1f2937'; ctx.fillRect(0, 0, canvas.width, canvas.height); ctx.save(); const scale = canvas.width / COURSE_WIDTH; ctx.scale(scale, scale);
    ctx.translate(0, -Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100)));

    linesRef.current.forEach((l, idx) => { 
        const isActive = lineActivityRef.current[idx] > 0;
        ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : (isActive ? '#fff' : (l.type === 'bouncer' ? '#fbbf24' : '#60a5fa')); 
        ctx.lineWidth = l.type === 'wall' ? 6 : 4; 

        if (isActive) {
            ctx.shadowBlur = 15;
            ctx.shadowColor = '#fff';
        }

        ctx.beginPath(); ctx.moveTo(l.x1, l.y1); ctx.lineTo(l.x2, l.y2); ctx.stroke(); 
        ctx.shadowBlur = 0;
    });

    dynamicRef.current.forEach(obj => {
       ctx.save(); ctx.translate(obj.x, obj.y); ctx.rotate(obj.angle);
       if (obj.type === 'teleporter') { const opacity = obj.timer || 1; const r = obj.width/2; ctx.globalAlpha = opacity; ctx.beginPath(); ctx.arc(0,0,r,0,Math.PI*2); ctx.strokeStyle = (obj.destY||0)<obj.y ? '#ef4444' : '#d946ef'; ctx.lineWidth = 3; ctx.stroke(); }
       else if (obj.type === 'fan') { ctx.fillStyle = '#64748b'; ctx.fillRect(-10, -obj.width/2, 20, obj.width); const grad = ctx.createLinearGradient(0,0,obj.height||200,0); grad.addColorStop(0,'rgba(255,255,255,0.4)'); grad.addColorStop(1,'rgba(255,255,255,0)'); ctx.fillStyle = grad; ctx.fillRect(0,-obj.width/2,obj.height||200,obj.width); }
       else if (obj.type === 'laser' && obj.active) { ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(obj.height||300,0); ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 4; ctx.stroke(); }
       else if (obj.type === 'hollow_circle') { ctx.beginPath(); ctx.arc(0,0,obj.width/2, (obj.range||1)/2, Math.PI*2-(obj.range||1)/2); ctx.strokeStyle='#d946ef'; ctx.lineWidth=12; ctx.stroke(); }
       else { ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b'; ctx.lineWidth=8; ctx.beginPath(); ctx.moveTo(-obj.width/2, 0); ctx.lineTo(obj.width/2, 0); ctx.stroke(); }
       ctx.restore();
    });

    if (!gateOpenRef.current) { ctx.beginPath(); ctx.moveTo(0, GATE_Y); ctx.lineTo(COURSE_WIDTH, GATE_Y); ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 10; ctx.stroke(); ctx.fillStyle = 'rgba(255, 255, 255, 0.8)'; ctx.font = 'bold 80px "Righteous"'; ctx.textAlign = 'center'; ctx.fillText(Math.max(0, Math.ceil((GATE_DELAY - (Date.now()-startTime.current)) / 1000)).toString(), COURSE_WIDTH / 2, GATE_Y + 150); }
    particlesRef.current.forEach(p => { ctx.globalAlpha = p.life; ctx.fillStyle = p.color; ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI*2); ctx.fill(); });
    pinsRef.current.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2); ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af'; ctx.fill(); });
    ctx.fillStyle = '#10b981'; ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    marblesRef.current.forEach(m => {
      ctx.save(); ctx.translate(m.x, m.y); ctx.rotate(-m.angle); ctx.beginPath(); ctx.arc(0,0,m.radius,0,Math.PI*2); ctx.fillStyle='#fff'; ctx.fill();
      ctx.save(); ctx.beginPath(); ctx.arc(0,0,m.radius,0,Math.PI*2); ctx.clip(); const img = imagesRef.current[m.id]; if (img?.complete && img.naturalHeight!==0) ctx.drawImage(img, -m.radius, -m.radius, m.radius*2, m.radius*2); else { ctx.fillStyle = m.color; ctx.fill(); } ctx.restore();
      ctx.beginPath(); ctx.arc(0,0,m.radius,0,Math.PI*2); ctx.strokeStyle=m.color; ctx.lineWidth=2; ctx.stroke(); ctx.restore(); 
      if (m.id === betMarbleId) { ctx.strokeStyle='#fbbf24'; ctx.lineWidth=3; ctx.beginPath(); ctx.arc(m.x,m.y,m.radius+6,0,Math.PI*2); ctx.stroke(); }
      if (!m.finished) { ctx.fillStyle='#fff'; ctx.font='10px Arial'; ctx.textAlign='center'; ctx.fillText(m.name, m.x, m.y - m.radius - 8); }
    });
    ctx.restore();
    const sorted = [...marblesRef.current].sort((a, b) => a.finished && b.finished ? a.rank - b.rank : (a.finished ? -1 : (b.finished ? 1 : b.y - a.y)));
    ctx.fillStyle='rgba(0,0,0,0.5)'; ctx.roundRect(10, 90, 110, sorted.length*18+10, 6); ctx.fill();
    ctx.font='bold 10px "Roboto Mono"'; ctx.textAlign='left'; ctx.textBaseline='middle';
    sorted.forEach((m, idx) => { const y = 100+idx*18; ctx.fillStyle = idx===0?'#fbbf24':idx===1?'#9ca3af':idx===2?'#b45309':'#6b7280'; ctx.fillText(`${idx+1}.`, 15, y); ctx.fillStyle=m.color; ctx.beginPath(); ctx.arc(35, y, 3, 0, Math.PI*2); ctx.fill(); ctx.fillStyle=m.finished?'#10b981':'#e5e7eb'; ctx.fillText(m.name.substring(0,10), 45, y); if (m.id===betMarbleId) { ctx.strokeStyle='#fbbf24'; ctx.strokeRect(12, y-8, 106, 16); } });
  };

  useEffect(() => {
    const loop = () => { update(); draw(); requestRef.current = requestAnimationFrame(loop); };
    requestRef.current = requestAnimationFrame(loop); return () => cancelAnimationFrame(requestRef.current!);
  });

  return <canvas ref={canvasRef} className="w-full h-full block" />;
};

