{m.name}</span></div><div className="flex flex-col text-right">{gameState.gameMode === 'cup' && gameState.cupMatches[gameState.currentMatchIndex]?.type !== 'group' ? (<span className={idx===0 ? "text-green-400 font-bold uppercase" : "text-red-500 uppercase"}>{idx===0 ? "VENCEU" : "ELIMINADO"}</span>) : (<><span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span><span className="text-[10px] text-gray-500 uppercase">Total: {gameState.gameMode === 'cup' ? gameState.cupScores[m.id] : m.score}</span></>)}</div></div>))}</div>)}
