        <button 
          onClick={cycleCameraMode} 
          className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${cameraMode !== 'leader' ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
          {cameraMode === 'leader' ? <Camera className="w-4 h-4 text-gray-400" /> : <Camera className="w-4 h-4 text-yellow-400 animate-pulse" />}
          {cameraMode === 'leader' ? (
            <span className="text-gray-300 font-bold uppercase text-sm">CÂMERA: LÍDER</span>
          ) : cameraMode === 'bet' ? (
            <div className="flex items-center space-x-2">
              <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
              </div>
              <span className="font-bold text-yellow-400 uppercase">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
            </div>
          ) : (
            <span className="text-yellow-400 font-bold uppercase text-sm">CÂMERA: LANTERNA</span>
          )}
        </button>
      )}
    </div>
  );
}

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings, GameMode } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  cameraMode: 'leader' | 'bet' | 'last';
  gameMode: GameMode;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, cameraMode, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Cache for loaded images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);
  const gateOpenRef = useRef(false);

  // Constants
  const COURSE_WIDTH = 600;
  const GATE_Y = 180; // Position of the starting gate
  const GATE_DELAY = 3000; // Time before gate opens (ms)

  // --- Particle Helper ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03, // Random fade speed
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 14 + Math.floor(Math.random() * 4); 
    const segmentHeight = 500;
    let currentY = 0;

    // --- OBSTÁCULO INICIAL: PLINKO DE PINOS MÓVEIS ---
    const plinkoStartY = GATE_Y + 100;
    const plinkoRows = 10; 
    const plinkoRowHeight = 55; 
    const plinkoEndY = plinkoStartY + (plinkoRows * plinkoRowHeight);

    // Paredes iniciais
    lines.push({ x1: 0, y1: 0, x2: 0, y2: plinkoEndY, type: 'wall' }); 
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH, y2: plinkoEndY, type: 'wall' }); 

    for (let r = 0; r < plinkoRows; r++) {
        const py = plinkoStartY + (r * plinkoRowHeight);
        const isEven = r % 2 === 0;
        const pinRadius = 9;
        const spacing = 70; 
        const rowSpeed = 0.05 * (isEven ? 1 : -1); 
        const rowRange = 70; 
        const startX = 35;
        for (let x = startX; x < COURSE_WIDTH; x += spacing) {
             pins.push({ x: x, y: py, radius: pinRadius, type: 'pin', initialX: x, speed: rowSpeed, range: rowRange });
        }
    }

    const funnelHeight = 180;
    lines.push({ x1: 0, y1: plinkoEndY, x2: 120, y2: plinkoEndY + funnelHeight, type: 'wall' });
    lines.push({ x1: 225, y1: plinkoEndY + 60, x2: 180, y2: plinkoEndY + funnelHeight, type: 'wall' });
    lines.push({ x1: 225, y1: plinkoEndY + 60, x2: 270, y2: plinkoEndY + funnelHeight, type: 'wall' });
    lines.push({ x1: 375, y1: plinkoEndY + 60, x2: 330, y2: plinkoEndY + funnelHeight, type: 'wall' });
    lines.push({ x1: 375, y1: plinkoEndY + 60, x2: 420, y2: plinkoEndY + funnelHeight, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: plinkoEndY, x2: 480, y2: plinkoEndY + funnelHeight, type: 'wall' });

    currentY = plinkoEndY + funnelHeight + 50;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 12 });
            options.push({ type: 'slider_v', weight: 10 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 12 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 12 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 10 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 10 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 8 });

        if (options.length === 0) return 'none';
        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;
        for (const opt of options) { if (random < opt.weight) return opt.type; random -= opt.weight; }
        return options[0].type;
    };

    for (let i = 0; i < segments; i++) {
      const type = pickObstacleType();

      // Paredes Laterais e Bumpers Laterais
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      // Adiciona pinos/bumpers nas laterais para aumentar a ação
      for (let by = 0; by < segmentHeight; by += 120) {
        pins.push({ x: 10, y: currentY + by, radius: 15, type: 'bumper' });
        pins.push({ x: COURSE_WIDTH - 10, y: currentY + by + 60, radius: 15, type: 'bumper' });
      }

      if (type === 'spinner') {
        dynamics.push({ id: `spin_${i}_1`, type: 'spinner', x: COURSE_WIDTH * 0.3, y: currentY + 200, width: 140, angle: 0, speed: 0.12 });
        dynamics.push({ id: `spin_${i}_2`, type: 'spinner', x: COURSE_WIDTH * 0.7, y: currentY + 300, width: 140, angle: Math.PI / 2, speed: -0.15 });
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 250, radius: 25, type: 'bumper' });
      } else if (type === 'slider_h') {
        dynamics.push({ id: `slide_h_top_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 150, width: 220, angle: 0, speed: 2.2, range: 170, initialX: COURSE_WIDTH / 2, initialY: currentY + 150 });
        dynamics.push({ id: `slide_h_bot_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 350, width: 220, angle: 0, speed: -2.8, range: 170, initialX: COURSE_WIDTH / 2, initialY: currentY + 350 });
      } else if (type === 'slider_v') {
        dynamics.push({ id: `slide_v_L_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.25, y: currentY + 250, width: 120, angle: 0, speed: 1.4, range: 80, initialX: COURSE_WIDTH * 0.25, initialY: currentY + 250 });
        dynamics.push({ id: `slide_v_R_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.75, y: currentY + 350, width: 120, angle: 0, speed: 1.4, range: 80, initialX: COURSE_WIDTH * 0.75, initialY: currentY + 350 });
      } else if (type === 'repulsor') {
        dynamics.push({ id: `repulse_${i}`, type: 'repulsor', x: COURSE_WIDTH / 2, y: currentY + 250, width: 60, range: 160, angle: 0, speed: 0.1, force: 3.5, initialX: COURSE_WIDTH / 2, initialY: currentY + 250 });
      } else if (type === 'conveyor') {
        dynamics.push({ id: `conveyor_${i}_L`, type: 'conveyor', x: COURSE_WIDTH * 0.2, y: currentY + 250, width: 200, angle: Math.PI / 6, speed: 0, force: 20 });
        dynamics.push({ id: `conveyor_${i}_R`, type: 'conveyor', x: COURSE_WIDTH * 0.8, y: currentY + 250, width: 200, angle: -Math.PI / 6, speed: 0, force: 20 });
      } else if (type === 'teleporter') {
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const targetY = currentY + (600 + Math.random() * 200);
        dynamics.push({ id: `teleport_${i}`, type: 'teleporter', x: entranceX, y: currentY + 150, width: 70, destX: exitX, destY: targetY, angle: 0, speed: 0, active: true });
      } else if (type === 'hollow_circle') {
        dynamics.push({ id: `hollow_${i}`, type: 'hollow_circle', x: COURSE_WIDTH / 2, y: currentY + 250, width: 280, angle: 0, speed: 0.04, range: Math.PI / 2 });
      } else if (type === 'laser') {
        dynamics.push({ id: `laser_${i}`, type: 'laser', x: COURSE_WIDTH * 0.5, y: currentY + 250, width: 0, height: 350, angle: 0, speed: 0, force: 25, active: true, timer: 0 });
      } else if (type === 'fan') {
        dynamics.push({ id: `fan_${i}_1`, type: 'fan', x: 50, y: currentY + 100, width: 100, angle: 0, speed: 0.2, force: 2.0 });
        dynamics.push({ id: `fan_${i}_2`, type: 'fan', x: COURSE_WIDTH - 50, y: currentY + 300, width: 100, angle: Math.PI, speed: 0.2, force: 2.0 });
      } else if (type === 'funnel') {
        const funnelTopY = currentY + 50; const funnelHeight = 300; const exitGap = 60;
        lines.push({ x1: 0, y1: funnelTopY, x2: COURSE_WIDTH/2 - exitGap/2, y2: funnelTopY + funnelHeight, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: funnelTopY, x2: COURSE_WIDTH/2 + exitGap/2, y2: funnelTopY + funnelHeight, type: 'wall' });
        pins.push({ x: COURSE_WIDTH/2, y: funnelTopY + funnelHeight + 80, radius: 25, type: 'bumper' });
      }
      currentY += segmentHeight;
    }
    finishLineY.current = currentY + 250;
    linesRef.current = lines; pinsRef.current = pins; dynamicRef.current = dynamics;
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 
    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) audio.playBump(intensity);
    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx; ball.vy += jN * ny;
    const tx = -ny; const ty = nx; 
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;
    const jT_ideal = -vSurf / 3.5; const mu = 0.5;
    const maxJt = mu * Math.abs(jN);
    let jT = Math.abs(jT_ideal) > maxJt ? Math.sign(jT_ideal) * maxJt : jT_ideal;
    ball.vx += jT * tx; ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / ball.radius;
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1; const dy = line.y2 - line.y1; const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx; const closeY = line.y1 + t * dy;
    const distX = ball.x - closeX; const distY = ball.y - closeY; const distSq = distX*distX + distY*distY;
    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq); const nx = distX / dist; const ny = distY / dist;
      ball.x += nx * (ball.radius - dist); ball.y += ny * (ball.radius - dist);
      resolveCollisionPhysics(ball, nx, ny, isDynamic && (line.type === 'bouncer' || line.type === 'floor'));
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x; const dy = ball.y - pin.y; const distSq = dx*dx + dy*dy; const minDist = ball.radius + pin.radius;
    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq); const nx = dx / dist; const ny = dy / dist;
      ball.x += nx * (minDist - dist); ball.y += ny * (minDist - dist);
      resolveCollisionPhysics(ball, nx, ny, pin.type === 'bumper');
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x; const dy = m2.y - m1.y; const distSq = dx*dx + dy*dy; const minDist = m1.radius + m2.radius;
    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq); const nx = dx / dist; const ny = dy / dist; const overlap = (minDist - dist) * 0.5;
      m1.x -= nx * overlap; m1.y -= ny * overlap; m2.x += nx * overlap; m2.y += ny * overlap;
      const dvx = m1.vx - m2.vx; const dvy = m1.vy - m2.vy; const dot = dvx * nx + dvy * ny;
      if (dot > 0) { const impulse = dot * 0.9; m1.vx -= impulse * nx; m1.vy -= impulse * ny; m2.vx += impulse * nx; m2.vy += impulse * ny; }
    }
  };

  const update = () => {
    if (isPaused || raceFinished.current) { audio.updateRolling(0); return; }
    const timeSinceStart = Date.now() - startTime.current;
    if (!gateOpenRef.current && timeSinceStart > GATE_DELAY) {
        gateOpenRef.current = true;
        audio.playPinHit(15);
        spawnParticles(COURSE_WIDTH/2, GATE_Y, '#10b981', 30, 8);
    }

    const STEPS = 8; const dt = 1 / STEPS; timeRef.current += 1; const now = Date.now();
    const marbles = marblesRef.current; const dynamicObjs = dynamicRef.current;

    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i]; p.x += p.vx; p.y += p.vy; p.life -= p.decay;
        if (p.life <= 0) particlesRef.current.splice(i, 1);
    }

    let totalSpeed = 0;
    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner' || obj.type === 'hollow_circle' || obj.type === 'fan') obj.angle += obj.speed;
      else if (obj.type === 'slider_h') obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      else if (obj.type === 'slider_v') obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      else if (obj.type === 'repulsor') obj.y = obj.initialY! + Math.sin(timeRef.current * 0.025) * 120;
      else if (obj.type === 'teleporter') { obj.active = true; obj.timer = 1.0; }
      else if (obj.type === 'laser') {
        obj.timer = (obj.timer || 0) + 1;
        if (obj.timer > 180) { obj.active = !obj.active; obj.timer = 0; }
      }
    });

    const dynamicLines: LineSegment[] = [];
    dynamicObjs.forEach(obj => {
      if (['spinner', 'slider_h', 'slider_v', 'conveyor'].includes(obj.type)) {
        const halfW = obj.width / 2; const dx = Math.cos(obj.angle) * halfW; const dy = Math.sin(obj.angle) * halfW;
        dynamicLines.push({ x1: obj.x - dx, y1: obj.y - dy, x2: obj.x + dx, y2: obj.y + dy, type: obj.type === 'spinner' ? 'bouncer' : 'floor' });
      }
    });

    pinsRef.current.forEach(pin => {
         if (pin.initialX !== undefined && pin.speed !== undefined && pin.range !== undefined) {
             pin.x = pin.initialX + Math.sin(timeRef.current * pin.speed) * pin.range;
         }
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i]; if (m.finished) continue;
        m.vy += config.gravity * dt; m.x += m.vx * dt; m.y += m.vy * dt;
        m.angle += m.omega * dt; 

        if (m.x < m.radius) { m.x = m.radius; m.vx = Math.abs(m.vx) * 0.5; } 
        else if (m.x > COURSE_WIDTH - m.radius) { m.x = COURSE_WIDTH - m.radius; m.vx = -Math.abs(m.vx) * 0.5; }

        dynamicObjs.forEach(obj => {
            if (obj.type === 'repulsor') {
                const dx = m.x - obj.x; const dy = m.y - obj.y; const distSq = dx*dx + dy*dy; const range = obj.range || 100;
                if (distSq < range * range) {
                    const dist = Math.sqrt(distSq); const nx = dx / dist; const ny = dy / dist;
                    const pulse = (Math.sin(timeRef.current * 0.1) + 1) * 0.5;
                    const force = (obj.force || 1) * (1 - dist/range) * (0.5 + pulse);
                    m.vx += nx * force * dt * 50; m.vy += ny * force * dt * 50;
                }
            } else if (obj.type === 'teleporter' && obj.active) {
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                if (Math.sqrt(dx*dx + dy*dy) < obj.width/2 && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {
                    m.x = obj.destX || m.x; m.y = obj.destY || m.y;
                    m.vx *= 0.2; m.vy = Math.abs(m.vy) + 2;
                    teleportCooldowns.current[m.id] = now + 1500; audio.playPinHit(8);
                    spawnParticles(m.x, m.y, '#06b6d4', 15, 4);
                }
            } else if (obj.type === 'laser' && obj.active) {
                const halfH = (obj.height || 1) / 2;
                if (m.x > obj.x - 5 && m.x < obj.x + 5 && m.y > obj.y - halfH && m.y < obj.y + halfH) {
                  m.vx += (Math.random() - 0.5) * 12; m.vy -= 8; audio.playPinHit(20);
                  spawnParticles(m.x, m.y, '#ef4444', 10, 5);
                }
            } else if (obj.type === 'fan') {
                const dx = m.x - obj.x; const dy = m.y - obj.y; const distSq = dx*dx + dy*dy;
                if (distSq < 200 * 200) {
                    const angleToMarble = Math.atan2(dy, dx);
                    const angleDiff = Math.abs(((angleToMarble - obj.angle + Math.PI * 3) % (Math.PI * 2)) - Math.PI);
                    if (angleDiff < 0.5) {
                        const dist = Math.sqrt(distSq);
                        const force = (obj.force || 1) * (1 - dist / 200);
                        m.vx += Math.cos(obj.angle) * force * dt * 30;
                        m.vy += Math.sin(obj.angle) * force * dt * 30;
                    }
                }
            } else if (obj.type === 'conveyor') {
                const halfW = obj.width / 2;
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                const distLine = Math.abs(dx * Math.sin(obj.angle) - dy * Math.cos(obj.angle));
                if (distLine < m.radius + 5) {
                    const proj = dx * Math.cos(obj.angle) + dy * Math.sin(obj.angle);
                    if (Math.abs(proj) < halfW) {
                        const pushX = Math.cos(obj.angle) * (obj.force || 1);
                        const pushY = Math.sin(obj.angle) * (obj.force || 1);
                        m.vx += pushX * dt * 2; m.vy += pushY * dt * 2;
                    }
                }
            }
        });

        if (!gateOpenRef.current) checkLineCollision(m, { x1: 0, y1: GATE_Y, x2: COURSE_WIDTH, y2: GATE_Y, type: 'wall' });
        linesRef.current.forEach(l => checkLineCollision(m, l));
        dynamicLines.forEach(l => checkLineCollision(m, l, true));
        pinsRef.current.forEach(p => checkPinCollision(m, p));
        for (let j = i + 1; j < marbles.length; j++) if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);

        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          m.rank = marbles.filter(b => b.finished).length;
          audio.playPinHit(10); spawnParticles(m.x, m.y, '#10b981', 10, 4);
          if (gameMode === 'inverted_elimination' && !raceFinished.current) {
              raceFinished.current = true;
              onRaceFinish(marblesRef.current);
              return;
          }
        }
        if (!m.finished) totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy);
      }
    }

    audio.updateRolling(totalSpeed);

    // --- CAMERA LOGIC ---
    const activeMarblesList = marbles.filter(m => !m.finished);
    let targetY = cameraY.current;

    if (activeMarblesList.length > 0) {
        if (cameraMode === 'bet' && betMarbleId !== null) {
            const betMarble = marbles.find(m => m.id === betMarbleId);
            if (betMarble && !betMarble.finished) {
                targetY = betMarble.y - 300;
            } else {
                activeMarblesList.sort((a, b) => b.y - a.y);
                targetY = activeMarblesList[0].y - 300;
            }
        } else if (cameraMode === 'last') {
            activeMarblesList.sort((a, b) => a.y - b.y);
            targetY = activeMarblesList[0].y - 300;
        } else {
            // Default: Leader
            activeMarblesList.sort((a, b) => b.y - a.y);
            targetY = activeMarblesList[0].y - 300;
        }
    }

    cameraY.current += (targetY - cameraY.current) * 0.08;

    if (marbles.filter(m => !m.finished).length === 0 && !raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); setTimeout(() => onRaceFinish(sorted), 1000);
    }
  };

  const drawTeleporter = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle, isExit = false) => {
      ctx.save();
      const radius = obj.width / 2;
      const primaryColor = isExit ? '#06b6d4' : '#d946ef';
      ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI * 2);
      ctx.strokeStyle = primaryColor; ctx.lineWidth = 3;
      ctx.shadowColor = primaryColor; ctx.shadowBlur = 10; ctx.stroke();
      ctx.fillStyle = '#fff'; ctx.font = '10px Arial'; ctx.textAlign = 'center';
      ctx.fillText(isExit ? 'SAÍDA' : 'ENTRADA', 0, 4);
      ctx.restore(); 
  };

  const drawLeaderboard = (ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) => {
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 120; const itemHeight = 20; const startX = 10; const startY = 100; 

    ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 8);
    ctx.fill();
    ctx.font = 'bold 10px "Roboto Mono"'; 
    ctx.textAlign = 'left'; ctx.textBaseline = 'middle';

    sorted.forEach((m, index) => {
       const y = startY + 12 + index * itemHeight; 
       ctx.fillStyle = index === 0 ? '#fbbf24' : '#e5e7eb';
       ctx.fillText(`${index + 1}. ${m.name.substring(0, 10)}`, startX + 5, y);
    });
  };

  const draw = () => {
    const canvas = canvasRef.current; if (!canvas) return;
    const ctx = canvas.getContext('2d'); if (!ctx) return;
    if (canvas.width !== canvas.offsetWidth || canvas.height !== canvas.offsetHeight) { canvas.width = canvas.offsetWidth; canvas.height = canvas.offsetHeight; }
    ctx.fillStyle = '#1f2937'; ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.save(); const scale = canvas.width / COURSE_WIDTH; ctx.scale(scale, scale);
    ctx.translate(0, -Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100)));

    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa'; ctx.lineWidth = l.type === 'wall' ? 6 : 4;
      ctx.beginPath(); ctx.moveTo(l.x1, l.y1); ctx.lineTo(l.x2, l.y2); ctx.stroke();
    });

    dynamicRef.current.forEach(obj => {
       ctx.save(); ctx.translate(obj.x, obj.y); ctx.rotate(obj.angle);
       if (obj.type === 'repulsor') {
          const pulse = (Math.sin(timeRef.current * 0.1) + 1) * 0.5;
          ctx.beginPath(); ctx.arc(0, 0, obj.width/2, 0, Math.PI * 2); ctx.fillStyle = '#8b5cf6'; ctx.fill();
          ctx.beginPath(); ctx.arc(0, 0, obj.width/2 + pulse * 40, 0, Math.PI * 2); ctx.strokeStyle = `rgba(139, 92, 246, ${1 - pulse})`; ctx.lineWidth = 2; ctx.stroke();
       } else if (obj.type === 'teleporter') {
           drawTeleporter(ctx, obj, false);
           if (obj.destX !== undefined && obj.destY !== undefined) {
               ctx.restore(); ctx.save(); ctx.translate(obj.destX, obj.destY); drawTeleporter(ctx, obj, true);
           }
       } else if (obj.type === 'hollow_circle') {
          ctx.beginPath(); ctx.arc(0, 0, obj.width/2, (obj.range||1)/2, Math.PI * 2 - (obj.range||1)/2);
          ctx.strokeStyle = '#d946ef'; ctx.lineWidth = 12; ctx.lineCap = 'round'; ctx.stroke();
       } else if (obj.type === 'spinner' || obj.type === 'slider_h' || obj.type === 'slider_v' || obj.type === 'conveyor') {
          ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : (obj.type === 'conveyor' ? '#10b981' : '#60a5fa');
          ctx.lineWidth = 10; ctx.beginPath(); ctx.moveTo(-obj.width/2, 0); ctx.lineTo(obj.width/2, 0); ctx.stroke();
          if (obj.type === 'conveyor') {
            // Desenha setas na esteira
            ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
            const offset = (timeRef.current * 2) % 20;
            for (let x = -obj.width/2 + offset; x < obj.width/2; x += 20) {
              ctx.beginPath(); ctx.moveTo(x - 5, -5); ctx.lineTo(x, 0); ctx.lineTo(x - 5, 5); ctx.stroke();
            }
          }
       } else if (obj.type === 'laser') {
          if (obj.active) {
            ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 6; ctx.beginPath(); ctx.moveTo(0, -(obj.height||1)/2); ctx.lineTo(0, (obj.height||1)/2); ctx.stroke();
            ctx.shadowColor = '#ef4444'; ctx.shadowBlur = 15; ctx.stroke(); ctx.shadowBlur = 0;
          }
       } else if (obj.type === 'fan') {
          ctx.strokeStyle = '#9ca3af'; ctx.lineWidth = 4;
          ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(30, 0); ctx.stroke();
          ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI * 2); ctx.fillStyle = '#4b5563'; ctx.fill();
          // Vento
          ctx.restore(); ctx.save(); ctx.translate(obj.x, obj.y); ctx.rotate(obj.angle);
          ctx.strokeStyle = 'rgba(255,255,255,0.2)'; ctx.lineWidth = 2;
          const windOff = (timeRef.current * 5) % 100;
          for (let w = 0; w < 3; w++) {
             const yOff = (w - 1) * 15;
             ctx.beginPath(); ctx.moveTo(20 + windOff, yOff); ctx.lineTo(50 + windOff, yOff); ctx.stroke();
          }
       }
       ctx.restore();
    });

    if (!gateOpenRef.current) {
        ctx.beginPath(); ctx.moveTo(0, GATE_Y); ctx.lineTo(COURSE_WIDTH, GATE_Y); ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 10; ctx.stroke();
    }

    pinsRef.current.forEach(p => {
      ctx.beginPath(); ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af'; ctx.fill();
      if (p.type === 'bumper') {
          ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.stroke();
      }
    });

    particlesRef.current.forEach(p => {
        ctx.globalAlpha = p.life; ctx.fillStyle = p.color;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2); ctx.fill();
    });
    ctx.globalAlpha = 1.0;

    // Finish Line
    ctx.fillStyle = '#10b981'; ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 15);

    marblesRef.current.forEach(m => {
      ctx.save(); ctx.translate(m.x, m.y); ctx.rotate(m.angle); // Rotação real no sentido do movimento
      ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2); ctx.fillStyle = '#fff'; ctx.fill();
      ctx.save(); ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2); ctx.clip();
      const img = imagesRef.current[m.id]; if (img && img.complete) ctx.drawImage(img, -m.radius, -m.radius, m.radius * 2, m.radius * 2);
      ctx.restore(); ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2); ctx.strokeStyle = m.color; ctx.lineWidth = 3; ctx.stroke();
      ctx.restore(); 
    });
    ctx.restore(); 
    drawLeaderboard(ctx, canvas.width, canvas.height);
  };

  useEffect(() => {
    const loop = () => { update(); draw(); requestRef.current = requestAnimationFrame(loop); };
    requestRef.current = requestAnimationFrame(loop); return () => cancelAnimationFrame(requestRef.current!);
  });

  useEffect(() => {
    generateLevel(); raceFinished.current = false; gateOpenRef.current = false;
    startTime.current = Date.now(); cameraY.current = 0; timeRef.current = 0; teleportCooldowns.current = {};
    activeMarbles.forEach(m => { const img = new Image(); img.src = m.logoUrl; imagesRef.current[m.id] = img; });
    const spacing = (COURSE_WIDTH * 0.9) / Math.max(1, activeMarbles.length);
    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m, x: (COURSE_WIDTH * 0.05) + (spacing * index) + (spacing/2), y: GATE_Y - 50, vx: 0, vy: 0, angle: 0, omega: 0, finished: false, rank: 0
    }));
    audio.resume();
  }, [activeMarbles]);

  return <canvas ref={canvasRef} className="w-full h-full block" />;
};

export default RaceEngine;

{
  "name": "Neon Sensor Pong",
  "description": "Um jogo de Pong controlado pela inclinação do seu celular.",
  "requestFramePermissions": []
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface PongEntity {
  pos: Vector2;
  size: Vector2;
  vel?: Vector2;
}

export interface GameState {
  player: PongEntity;
  ai: PongEntity;
  ball: PongEntity & { radius: number };
  score: { player: number; ai: number };
  status: 'idle' | 'playing' | 'scored';
  lastWinner: 'player' | 'ai' | null;
}

import React, { useState, useEffect, useRef } from 'react';
import { Vector2, GameState, PongEntity } from './types';
import { Smartphone, Play, RotateCcw, Trophy } from 'lucide-react';

const CANVAS_WIDTH = 600;
const CANVAS_HEIGHT = 800;
const PADDLE_WIDTH = 120;
const PADDLE_HEIGHT = 20;
const BALL_SPEED_START = 5;
const BALL_MAX_SPEED = 12;

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [sensorActive, setSensorActive] = useState(false);
  const [gamma, setGamma] = useState(0); // Inclinação lateral
  const [gameState, setGameState] = useState<GameState>({
    player: { pos: { x: CANVAS_WIDTH / 2 - PADDLE_WIDTH / 2, y: CANVAS_HEIGHT - 50 }, size: { x: PADDLE_WIDTH, y: PADDLE_HEIGHT } },
    ai: { pos: { x: CANVAS_WIDTH / 2 - PADDLE_WIDTH / 2, y: 30 }, size: { x: PADDLE_WIDTH, y: PADDLE_HEIGHT } },
    ball: { pos: { x: CANVAS_WIDTH / 2, y: CANVAS_HEIGHT / 2 }, vel: { x: 4, y: 4 }, size: { x: 10, y: 10 }, radius: 10 },
    score: { player: 0, ai: 0 },
    status: 'idle',
    lastWinner: null
  });

  const stateRef = useRef(gameState);

  // Atualiza a referência mutável para o loop de animação
  useEffect(() => {
    stateRef.current = gameState;
  }, [gameState]);

  // Listener de Sensores
  useEffect(() => {
    const handleOrientation = (event: DeviceOrientationEvent) => {
      if (event.gamma !== null) {
        // Gamma vai de -90 a 90. Mapeamos para a largura do canvas.
        // Sensibilidade aumentada
        const sensitivity = 2.5;
        let targetX = (CANVAS_WIDTH / 2) + (event.gamma * sensitivity);

        // Limites
        targetX = Math.max(0, Math.min(CANVAS_WIDTH - PADDLE_WIDTH, targetX));
        setGamma(targetX);
      }
    };

    if (sensorActive) {
      window.addEventListener('deviceorientation', handleOrientation);
    }

    return () => window.removeEventListener('deviceorientation', handleOrientation);
  }, [sensorActive]);

  const startGame = () => {
    // Solicitar permissão para iOS 13+ (necessário para DeviceOrientation)
    if (typeof (DeviceOrientationEvent as any).requestPermission === 'function') {
      (DeviceOrientationEvent as any).requestPermission()
        .then((permissionState: string) => {
          if (permissionState === 'granted') {
            setSensorActive(true);
            resetBall('player');
            setGameState(prev => ({ ...prev, status: 'playing', score: { player: 0, ai: 0 } }));
          }
        })
        .catch(console.error);
    } else {
      setSensorActive(true);
      resetBall('player');
      setGameState(prev => ({ ...prev, status: 'playing', score: { player: 0, ai: 0 } }));
    }
  };

  const resetBall = (winner: 'player' | 'ai') => {
    const dir = winner === 'player' ? -1 : 1;
    setGameState(prev => ({
      ...prev,
      ball: {
        ...prev.ball,
        pos: { x: CANVAS_WIDTH / 2, y: CANVAS_HEIGHT / 2 },
        vel: { x: (Math.random() - 0.5) * 6, y: dir * BALL_SPEED_START }
      }
    }));
  };

  // Loop de Jogo
  useEffect(() => {
    if (gameState.status !== 'playing') return;

    let animationFrameId: number;

    const update = () => {
      const state = stateRef.current;
      const newBall = { ...state.ball };
      const newAi = { ...state.ai };
      const newPlayer = { ...state.player };
      let newScore = { ...state.score };
      let newStatus = state.status;

      // Movimento do Jogador (segue o sensor gamma)
      newPlayer.pos.x = gamma;

      // IA - Movimento suave seguindo a bola
      const aiSpeed = 5.5;
      const aiCenter = newAi.pos.x + PADDLE_WIDTH / 2;
      if (newBall.pos.x < aiCenter - 10) newAi.pos.x -= aiSpeed;
      if (newBall.pos.x > aiCenter + 10) newAi.pos.x += aiSpeed;
      newAi.pos.x = Math.max(0, Math.min(CANVAS_WIDTH - PADDLE_WIDTH, newAi.pos.x));

      // Bola
      newBall.pos.x += newBall.vel!.x;
      newBall.pos.y += newBall.vel!.y;

      // Colisão Paredes Laterais
      if (newBall.pos.x <= 0 || newBall.pos.x >= CANVAS_WIDTH) {
        newBall.vel!.x *= -1;
      }

      // Colisão Raquete Jogador
      if (
        newBall.pos.y >= newPlayer.pos.y - newBall.radius &&
        newBall.pos.x >= newPlayer.pos.x &&
        newBall.pos.x <= newPlayer.pos.x + PADDLE_WIDTH &&
        newBall.vel!.y > 0
      ) {
        const hitPoint = (newBall.pos.x - (newPlayer.pos.x + PADDLE_WIDTH / 2)) / (PADDLE_WIDTH / 2);
        newBall.vel!.y *= -1.05; // Aumenta velocidade
        newBall.vel!.x = hitPoint * 7;
        // Limite de velocidade
        if (Math.abs(newBall.vel!.y) > BALL_MAX_SPEED) newBall.vel!.y = Math.sign(newBall.vel!.y) * BALL_MAX_SPEED;
      }

      // Colisão Raquete IA
      if (
        newBall.pos.y <= newAi.pos.y + PADDLE_HEIGHT + newBall.radius &&
        newBall.pos.x >= newAi.pos.x &&
        newBall.pos.x <= newAi.pos.x + PADDLE_WIDTH &&
        newBall.vel!.y < 0
      ) {
        newBall.vel!.y *= -1.05;
        const hitPoint = (newBall.pos.x - (newAi.pos.x + PADDLE_WIDTH / 2)) / (PADDLE_WIDTH / 2);
        newBall.vel!.x = hitPoint * 7;
      }

      // Pontuação
      if (newBall.pos.y < 0) {
        newScore.player += 1;
        resetBall('player');
      } else if (newBall.pos.y > CANVAS_HEIGHT) {
        newScore.ai += 1;
        resetBall('ai');
      }

      setGameState(prev => ({
        ...prev,
        ball: newBall,
        ai: newAi,
        player: newPlayer,
        score: newScore
      }));

      animationFrameId = requestAnimationFrame(update);
    };

    animationFrameId = requestAnimationFrame(update);
    return () => cancelAnimationFrame(animationFrameId);
  }, [gameState.status, gamma]);

  // Renderização
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Desenha Campo
    ctx.strokeStyle = 'rgba(0, 255, 255, 0.1)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, CANVAS_HEIGHT / 2);
    ctx.lineTo(CANVAS_WIDTH, CANVAS_HEIGHT / 2);
    ctx.stroke();

    // Desenha Raquetes
    ctx.shadowBlur = 15;

    // IA
    ctx.fillStyle = '#ff00ff';
    ctx.shadowColor = '#ff00ff';
    ctx.fillRect(gameState.ai.pos.x, gameState.ai.pos.y, PADDLE_WIDTH, PADDLE_HEIGHT);

    // Jogador
    ctx.fillStyle = '#00ffff';
    ctx.shadowColor = '#00ffff';
    ctx.fillRect(gameState.player.pos.x, gameState.player.pos.y, PADDLE_WIDTH, PADDLE_HEIGHT);

    // Bola
    ctx.fillStyle = '#ffffff';
    ctx.shadowColor = '#ffffff';
    ctx.beginPath();
    ctx.arc(gameState.ball.pos.x, gameState.ball.pos.y, gameState.ball.radius, 0, Math.PI * 2);
    ctx.fill();

    ctx.shadowBlur = 0;
  }, [gameState]);

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-slate-950 p-4 font-sans text-white overflow-hidden">
      {/* Header Placar */}
      <div className="flex justify-between w-full max-w-[600px] mb-4 px-8 py-4 bg-slate-900/50 rounded-2xl border border-slate-800 backdrop-blur-md">
        <div className="flex flex-col items-center">
          <span className="text-xs uppercase tracking-widest text-slate-400">CPU</span>
          <span className="text-4xl font-bold text-magenta-500">{gameState.score.ai}</span>
        </div>
        <div className="flex flex-col items-center justify-center">
          <span className="text-slate-500 font-mono">VS</span>
        </div>
        <div className="flex flex-col items-center">
          <span className="text-xs uppercase tracking-widest text-slate-400">VOCÊ</span>
          <span className="text-4xl font-bold text-cyan-400">{gameState.score.player}</span>
        </div>
      </div>

      {/* Área de Jogo */}
      <div className="relative border-4 border-slate-800 rounded-xl overflow-hidden shadow-2xl bg-black">
        <canvas
          ref={canvasRef}
          width={CANVAS_WIDTH}
          height={CANVAS_HEIGHT}
          className="max-h-[70vh] w-full h-auto cursor-none touch-none"
        />

        {/* Overlay Inicial */}
        {gameState.status === 'idle' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/80 backdrop-blur-sm transition-all">
            <div className="p-8 text-center">
              <div className="mb-6 flex justify-center">
                <div className="p-4 bg-cyan-500/20 rounded-full animate-pulse">
                  <Smartphone size={64} className="text-cyan-400" />
                </div>
              </div>
              <h1 className="text-4xl font-black mb-2 tracking-tighter brand-font">NEON PONG</h1>
              <p className="text-slate-400 mb-8 max-w-[250px]">Incline seu celular para os lados para controlar a raquete.</p>
              <button
                onClick={startGame}
                className="flex items-center gap-2 px-8 py-4 bg-cyan-500 hover:bg-cyan-400 text-black font-bold rounded-full transition-transform active:scale-95 shadow-[0_0_20px_rgba(6,182,212,0.5)]"
              >
                <Play fill="currentColor" size={20} /> COMEÇAR JOGO
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Footer / Info */}
      <div className="mt-8 flex flex-col items-center gap-2">
        <p className="text-slate-500 text-xs flex items-center gap-2">
          Controle via Giroscópio Ativo <div className={`w-2 h-2 rounded-full ${sensorActive ? 'bg-green-500 shadow-[0_0_5px_green]' : 'bg-red-500'}`} />
        </p>
        {gameState.status === 'playing' && (
          <button 
            onClick={() => setGameState(prev => ({...prev, status: 'idle'}))}
            className="text-slate-400 hover:text-white transition-colors text-sm flex items-center gap-1"
          >
            <RotateCcw size={14} /> Reiniciar
          </button>
        )}
      </div>

      {/* Decoração Estética */}
      <div className="fixed top-0 left-0 w-full h-full pointer-events-none opacity-20 bg-[radial-gradient(circle_at_50%_50%,_rgba(6,182,212,0.1),_transparent_70%)]" />
    </div>
  );
}

// Pong Audio Service
class PongAudio {
  private ctx: AudioContext | null = null;

  private init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
  }

  playBeep(freq: number, duration: number) {
    this.init();
    if (!this.ctx) return;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, this.ctx.currentTime);

    gain.gain.setValueAtTime(0.1, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + duration);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start();
    osc.stop(this.ctx.currentTime + duration);
  }
}

