// Audio Service supporting both Pong and Marble Race
class AudioService {
  private ctx: AudioContext | null = null;

  private init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
  }

  // Basic beep for feedback
  playBeep(freq: number, duration: number) {
    this.init();
    if (!this.ctx) return;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, this.ctx.currentTime);

    gain.gain.setValueAtTime(0.1, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + duration);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start();
    osc.stop(this.ctx.currentTime + duration);
  }

  // Marble collision sound
  playBump(intensity: number) {
    this.playBeep(100 + Math.min(intensity * 50, 400), 0.1);
  }

  // Continuous sound for rolling (placeholder)
  updateRolling(totalSpeed: number) {
    // Logic for rolling sound modulation
  }

  // Pin hit sound
  playPinHit(volume: number) {
    this.playBeep(400, 0.05);
  }

  // Race completion sound
  playFinish() {
    this.playBeep(600, 0.5);
  }

  // Resumes audio context if suspended
  resume() {
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume();
    } else {
      this.init();
    }
  }
}

