const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<any>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: TEAMS.length - 1, 
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig] = useState<PhysicsConfig>({ gravity: 0.25, restitution: 0.6 });
  const [obstacleSettings] = useState<ObstacleSettings>({
    spinner: true, slider: true, repulsor: true, conveyor: true,
    teleporter: true, hollow_circle: true, laser: true, fan: true, funnel: true
  });

  const [isPaused, setIsPaused] = useState(false);
  const [cameraMode, setCameraMode] = useState<'leader' | 'bet' | 'last'>('leader');

  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter((m: Marble) => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;
    setGameState((prev: any) => ({ ...prev, phase: 'racing' }));
    audio.resume();
    setCameraMode('leader');
  };

  const cycleCameraMode = () => {
    const isBetActive = gameState.activeMarbleIds.includes(gameState.betMarbleId);
    setCameraMode(prev => {
      if (prev === 'leader') return isBetActive ? 'bet' : 'last';
      if (prev === 'bet') return 'last';
      return 'leader';
    });
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination' || gameState.gameMode === 'inverted_elimination') {
      const loser = gameState.gameMode === 'elimination' ? results[results.length - 1] : results.find(m => m.finished);
      setGameState((prev: any) => ({ ...prev, phase: 'round_result', lastEliminatedId: loser?.id }));
    }
  };

  const handleNextRound = () => {
    const nextActiveIds = gameState.activeMarbleIds.filter((id: number) => id !== gameState.lastEliminatedId);
    if (nextActiveIds.length === 1) {
      setGameState((prev: any) => ({ ...prev, activeMarbleIds: nextActiveIds, phase: 'champion' }));
    } else {
      setGameState((prev: any) => ({ ...prev, activeMarbleIds: nextActiveIds, phase: 'racing', round: prev.round + 1, lastEliminatedId: null }));
      setCameraMode('leader');
    }
  };

  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">MARBLE ROYALE</h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-8 font-bold tracking-widest uppercase italic">BRASILEIRÃO EDITION</h2>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400 uppercase"><Trophy className="mr-2" /> Escolha seu Time</h2>
          <div className="grid grid-cols-4 md:grid-cols-5 gap-2 mb-8">
            {gameState.marbles.map((m: Marble) => (
              <button key={m.id} onClick={() => setGameState((prev: any) => ({ ...prev, betMarbleId: m.id }))} 
                className={`p-2 rounded-lg flex flex-col items-center transition-all ${gameState.betMarbleId === m.id ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' : 'bg-gray-700 border border-transparent hover:bg-gray-600'}`}>
                <div className="w-10 h-10 rounded-full mb-1 bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden"><img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" /></div>
                <span className="text-[10px] font-bold text-center truncate w-full uppercase">{m.name}</span>
              </button>
            ))}
          </div>
          <button disabled={gameState.betMarbleId === null} onClick={handleStartTournament} 
            className={`w-full py-4 rounded-lg font-black text-xl tracking-widest transition-all ${gameState.betMarbleId !== null ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:scale-105 text-white shadow-lg' : 'bg-gray-700 text-gray-500'}`}>
            INICIAR CORRIDA
          </button>
        </div>
      </div>
    );
  }

  if (gameState.phase === 'champion') {
    const champion = gameState.marbles.find((m: Marble) => m.id === gameState.activeMarbleIds[0]);
    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center">
        <Trophy className="w-32 h-32 text-yellow-400 mb-4 animate-bounce" />
        <img src={champion.logoUrl} className="w-40 h-40 object-contain mb-4" />
        <h1 className="text-6xl font-black text-white mb-2 brand-font uppercase">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-bold mb-8 uppercase">CAMPEÃO DO BRASILEIRÃO!</p>
        <button onClick={() => window.location.reload()} className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-110 transition-transform uppercase">NOVO TORNEIO</button>
      </div>
    );
  }

  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">
      <div className="absolute inset-0 z-0">
        <RaceEngine key={gameState.round} activeMarbles={activeMarblesList} config={physicsConfig} obstacleSettings={obstacleSettings} 
          onRaceFinish={handleRaceFinish} betMarbleId={gameState.betMarbleId} isPaused={isPaused} cameraMode={cameraMode} gameMode={gameState.gameMode} />
      </div>

      <div className="absolute top-4 left-4 z-10 p-3 bg-black/60 rounded-lg border border-gray-700 text-white">
        <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
        <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
      </div>

      {gameState.phase === 'racing' && (
        <button onClick={cycleCameraMode} className="absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-3 rounded-full border-2 bg-black/80 flex items-center space-x-3 transition-all hover:scale-105 active:scale-95 z-40 border-yellow-500/50">
          <Camera className={`w-5 h-5 ${cameraMode !== 'leader' ? 'text-yellow-400 animate-pulse' : 'text-gray-400'}`} />
          {cameraMode === 'leader' ? (
            <span className="text-white font-bold uppercase text-sm tracking-widest">CÂMERA: LÍDER</span>
          ) : cameraMode === 'bet' ? (
            <div className="flex items-center space-x-2">
              <img src={gameState.marbles.find((m: any) => m.id === gameState.betMarbleId)?.logoUrl} className="w-6 h-6 object-contain" />
              <span className="font-bold text-yellow-400 uppercase text-sm tracking-widest">CÂMERA: MEU TIME</span>
            </div>
          ) : (
            <span className="text-yellow-400 font-bold uppercase text-sm tracking-widest">CÂMERA: LANTERNA</span>
          )}
        </button>
      )}

      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in zoom-in">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font uppercase">FIM DA RODADA</h2>
            <div className="bg-red-900/30 border border-red-500 p-6 rounded-xl mb-6">
              <Skull className="w-12 h-12 text-red-500 mx-auto mb-4" />
              <div className="text-red-400 font-bold text-sm uppercase mb-2">Eliminado</div>
              <div className="flex items-center justify-center space-x-3">
                <img src={gameState.marbles.find((m: any) => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-12 h-12 object-contain" />
                <span className="text-xl text-white font-bold uppercase">{gameState.marbles.find((m: any) => m.id === gameState.lastEliminatedId)?.name}</span>
              </div>
            </div>
            <button onClick={handleNextRound} className="w-full py-4 bg-blue-600 text-white font-bold rounded-xl hover:bg-blue-500 uppercase">PRÓXIMA RODADA</button>
          </div>
        </div>
      )}
    </div>
  );
}

