      {isCupMatchWithoutPlayer && !isPaused && (<div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-50 animate-in fade-in zoom-in"><button onClick={handleSimulateMatch} className="flex items-center space-x-2 bg-blue-600 hover:bg-blue-500 text-white font-bold py-3 px-6 rounded-full shadow-lg border-2 border-blue-400 animate-pulse uppercase"><FastForward className="fill-current" /><span>SIMULAR PARTIDA</span></button><div className="text-center mt-2 text-xs text-gray-400 bg-black/50 p-1 rounded uppercase">Ou continue assistindo</div></div>)}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none"><div className="flex items-center"><div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto"><div className="text-xs text-gray-400 font-bold uppercase">{gameState.gameMode === 'cup' ? gameState.cupMatches[gameState.currentMatchIndex]?.name : 'Rodada'}</div><div className="text-2xl font-mono text-yellow-400">{gameState.gameMode === 'cup' ? '' : `${gameState.round} `}<span className="text-sm text-gray-500">{gameState.gameMode === 'cup' ? '' : `/ ${gameState.totalRounds}`}</span></div></div></div>
