}));

function shuffle<T>(array: T[]): T[] {
  const newArr = [...array];
  for (let i = newArr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
  }
  return newArr;
}

interface MatchStats {
    completed: number;
    interrupted: number;
}

interface TeamStats {
    titles: { total: number; elimination: number; inverted_elimination: number; points: number; cup: number };
    points: { total: number; elimination: number; inverted_elimination: number; points: number; cup: number };
    raceWins: { total: number; elimination: number; inverted_elimination: number; points: number; cup: number };
}

interface Statistics {
    matches: {
        total: MatchStats;
        elimination: MatchStats;
        inverted_elimination: MatchStats;
        points: MatchStats;
        cup: MatchStats;
    };
    teams: Record<number, TeamStats>;
}

const INITIAL_STATS: Statistics = {
