             <button onClick={() => setShowStatisticsModal(true)} className="flex items-center text-sm bg-purple-700 hover:bg-purple-600 text-white px-4 py-2 rounded-lg transition-colors font-bold uppercase"><BarChart2 className="w-4 h-4 mr-2" />Estatísticas</button>
          </div>

          <div className="flex w-full">
            <button disabled={gameState.betMarbleId === null} onClick={handleStartTournament} className={`w-full py-4 rounded-lg font-black text-xl tracking-widest transition-all flex items-center justify-center ${gameState.betMarbleId !== null ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1' : 'bg-gray-700 text-gray-500 cursor-not-allowed'}`}>
                {gameState.gameMode === 'cup' ? 'VER CHAVEAMENTO' : 'INICIAR CORRIDA'}
            </button>
          </div>
        </div>

        {/* Settings Modal */}
        {showSettingsModal && (
           <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-gray-800 border border-gray-600 rounded-xl p-6 max-w-md w-full shadow-2xl animate-in zoom-in-95 flex flex-col">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-2xl font-bold flex items-center text-blue-400 uppercase"><Settings className="mr-2 w-6 h-6"/> Configurações de Física</h3>
                    <button onClick={() => setShowSettingsModal(false)}><X className="text-gray-400 hover:text-white" /></button>
                 </div>
                 <div className="space-y-6">
                    <div>
                        <label className="text-sm text-gray-300 font-bold block mb-2 uppercase">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                        <input type="range" min="0.1" max="0.8" step="0.05" value={physicsConfig.gravity} onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))} className="w-full accent-blue-500" />
                        <div className="flex justify-between text-[10px] text-gray-500 mt-1 uppercase"><span>Lenta</span><span>Normal</span><span>Pesada</span></div>
                    </div>
                    <div>
                        <label className="text-sm text-gray-300 font-bold block mb-2 uppercase">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                        <input type="range" min="0.1" max="0.9" step="0.1" value={physicsConfig.restitution} onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))} className="w-full accent-blue-500" />
                        <div className="flex justify-between text-[10px] text-gray-500 mt-1 uppercase"><span>Dura</span><span>Quicante</span><span>Extrema</span></div>
                    </div>
                 </div>
                 <button onClick={() => setShowSettingsModal(false)} className="mt-8 w-full py-3 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded-lg uppercase">Aplicar e Fechar</button>
              </div>
           </div>
        )}

        {showStatisticsModal && (
           <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-gray-800 border border-gray-600 rounded-xl p-6 max-w-4xl w-full shadow-2xl animate-in zoom-in-95 flex flex-col max-h-[90vh]">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-2xl font-bold flex items-center text-purple-400 uppercase"><BarChart2 className="mr-2 w-6 h-6"/> Histórico e Estatísticas</h3>
                    <button onClick={() => setShowStatisticsModal(false)}><X className="text-gray-400 hover:text-white" /></button>
                 </div>
                 <div className="overflow-y-auto pr-2 custom-scrollbar">
                     <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-3 mb-8">
                         <div className="bg-gray-700 p-2 rounded-lg text-center"><div className="text-gray-400 text-[10px] uppercase mb-1">Total</div><div className="text-xl font-bold">{statistics.matches.total.completed}</div></div>
                         <div className="bg-gray-700 p-2 rounded-lg text-center"><div className="text-gray-400 text-[10px] uppercase mb-1">Eliminação</div><div className="text-xl font-bold text-red-400">{statistics.matches.elimination.completed}</div></div>
                         <div className="bg-gray-700 p-2 rounded-lg text-center"><div className="text-gray-400 text-[10px] uppercase mb-1">Inv. Eliminação</div><div className="text-xl font-bold text-red-300">{statistics.matches.inverted_elimination?.completed || 0}</div></div>
                         <div className="bg-gray-700 p-2 rounded-lg text-center"><div className="text-gray-400 text-[10px] uppercase mb-1">Pontos</div><div className="text-xl font-bold text-blue-400">{statistics.matches.points.completed}</div></div>
                         <div className="bg-gray-700 p-2 rounded-lg text-center"><div className="text-gray-400 text-[10px] uppercase mb-1">Copas</div><div className="text-xl font-bold text-yellow-400">{statistics.matches.cup.completed}</div></div>
                     </div>
                     <h4 className="text-lg font-bold mb-3 text-white border-b border-gray-700 pb-2">Desempenho por Time</h4>
                     <div className="overflow-x-auto">
                         <table className="w-full text-left text-sm">
                             <thead className="text-gray-400 uppercase font-mono text-xs"><tr><th className="p-2">Time</th><th className="p-2 text-center text-yellow-500">Títulos</th><th className="p-2 text-center text-green-400">Vitórias</th><th className="p-2 text-center text-blue-400">Pontos</th></tr></thead>
                             <tbody className="divide-y divide-gray-700">
                                 {Object.entries(statistics.teams).sort(([, a]: [string, TeamStats], [, b]: [string, TeamStats]) => { if (b.titles.total !== a.titles.total) return b.titles.total - a.titles.total; if (b.raceWins.total !== a.raceWins.total) return b.raceWins.total - a.raceWins.total; return b.points.total - a.points.total; }).map(([idStr, stats]: [string, TeamStats]) => {
                                         const team = TEAMS[parseInt(idStr)];
                                         return (
                                             <tr key={idStr} className="hover:bg-gray-700/50"><td className="p-2 flex items-center space-x-2"><img src={team.logo} className="w-6 h-6 object-contain" /><span className="font-bold">{team.name}</span></td><td className="p-2 text-center font-mono font-bold text-yellow-500">{stats.titles.total > 0 ? stats.titles.total : '-'}</td><td className="p-2 text-center font-mono">{stats.raceWins.total}</td><td className="p-2 text-center font-mono text-gray-400">{stats.points.total}</td></tr>
                                         )
                                     })}
                             </tbody>
                         </table>
                     </div>
                 </div>
                 <div className="mt-6 flex justify-between items-center border-t border-gray-700 pt-4">
                    <button onClick={resetStatistics} className="flex items-center text-red-500 hover:text-red-400 text-xs font-bold px-3 py-2 rounded hover:bg-red-900/20 transition-colors"><Trash2 className="w-4 h-4 mr-2" />RESETAR DADOS</button>
                    <button onClick={() => setShowStatisticsModal(false)} className="px-6 py-2 bg-gray-600 hover:bg-gray-500 text-white font-bold rounded-lg">FECHAR</button>
                 </div>
              </div>
           </div>
        )}
      </div>
    );
  }

  if (gameState.phase === 'cup_tree') {
      const getSortedGroup = (groupIdx: number) => {
         const groupIds = gameState.cupGroups[groupIdx] || [];
         return [...groupIds].sort((a, b) => (gameState.cupScores[b] || 0) - (gameState.cupScores[a] || 0));
      };
      const getTeam = (id: number | undefined) => id !== undefined ? gameState.marbles.find(m => m.id === id) : undefined;
      const isGroupFinished = (gIdx: number) => gameState.currentMatchIndex > (16 + gIdx);
      const getWinnerFromMatch = (phaseName: string, bracketMatchIndex: number) => {
          const targetId = `${phaseName}_${bracketMatchIndex * 2}`;
          const m = gameState.cupMatches.find(match => match.id === targetId);
          return m?.winnerId;
      };
      const leadersA = getSortedGroup(0); const leadersB = getSortedGroup(1); const leadersC = getSortedGroup(2); const leadersD = getSortedGroup(3);
      const projections = (gameState.cupPhase === 'groups') ? [
          { t1: leadersA[0], t2: leadersB[3] }, { t1: leadersA[1], t2: leadersB[2] }, { t1: leadersA[2], t2: leadersB[1] }, { t1: leadersA[3], t2: leadersB[0] },
          { t1: leadersC[0], t2: leadersD[3] }, { t1: leadersC[1], t2: leadersD[2] }, { t1: leadersC[2], t2: leadersD[1] }, { t1: leadersC[3], t2: leadersD[0] },
      ] : [];
      const octavasLabels = [
          { t: "1º GRUPO A", b: "4º GRUPO B" }, { t: "2º GRUPO A", b: "3º GRUPO B" }, { t: "3º GRUPO A", b: "2º GRUPO B" }, { t: "4º GRUPO A", b: "1º GRUPO B" },
          { t: "1º GRUPO C", b: "4º GRUPO D" }, { t: "2º GRUPO C", b: "3º GRUPO D" }, { t: "3º GRUPO C", b: "2º GRUPO D" }, { t: "4º GRUPO C", b: "1º GRUPO D" },
      ];
      const renderBracketMatch = (phaseName: string, index: number, projection?: {t1: number | undefined, t2: number | undefined}, t1Ready: boolean = true, t2Ready: boolean = true, labelTop: string = "", labelBottom: string = "") => {
         const targetId = `${phaseName}_${index * 2}`;
         const match = gameState.cupMatches.find(m => m.id === targetId);
         let team1Id = match ? match.marbleIds[0] : (t1Ready && projection ? projection.t1 : undefined);
         let team2Id = match ? match.marbleIds[1] : (t2Ready && projection ? projection.t2 : undefined);
         const team1 = getTeam(team1Id); const team2 = getTeam(team2Id); const winnerId = match?.winnerId;
         return (
             <div className={`p-2 rounded-lg border flex flex-col justify-center text-xs mb-4 min-w-[160px] ${match ? 'bg-gray-800 border-gray-600' : 'bg-gray-800/50 border-gray-700 border-dashed opacity-70'}`}>
                 <div className="flex justify-between items-center mb-1"><span className="text-[10px] text-gray-500 font-mono uppercase">JOGO {index + 1}</span></div>
                 <div className="mb-1">
                     <div className={`flex items-center space-x-2 p-1 rounded ${winnerId === team1Id && team1Id !== undefined ? 'bg-green-900/30' : ''}`}>
                          <div className={`w-4 h-4 rounded-full flex items-center justify-center p-[1px] ${winnerId === team1Id && team1Id !== undefined ? 'bg-yellow-400' : 'bg-gray-400'}`}>{team1 ? <img src={team1.logoUrl} className="w-full h-full object-contain rounded-full" /> : <div className="w-full h-full bg-gray-600 rounded-full" />}</div>
                          <div className="flex flex-col overflow-hidden"><span className={`truncate font-mono ${winnerId === team1Id && team1Id !== undefined ? 'text-green-400 font-bold' : 'text-gray-300'}`}>{team1 ? team1.name : (gameState.cupPhase==='groups' ? '???' : '')}</span>{!team1 && labelTop && <span className="text-[9px] text-gray-500 uppercase">{labelTop}</span>}</div>
                          {winnerId === team1Id && team1Id !== undefined && <Medal className="w-3 h-3 text-yellow-500 ml-auto" />}
                     </div>
                 </div>
                 <div>
                     <div className={`flex items-center space-x-2 p-1 rounded ${winnerId === team2Id && team2Id !== undefined ? 'bg-green-900/30' : ''}`}>
                          <div className={`w-4 h-4 rounded-full flex items-center justify-center p-[1px] ${winnerId === team2Id && team2Id !== undefined ? 'bg-yellow-400' : 'bg-gray-400'}`}>{team2 ? <img src={team2.logoUrl} className="w-full h-full object-contain rounded-full" /> : <div className="w-full h-full bg-gray-600 rounded-full" />}</div>
                          <div className="flex flex-col overflow-hidden"><span className={`truncate font-mono ${winnerId === team2Id && team2Id !== undefined ? 'text-green-400 font-bold' : 'text-gray-300'}`}>{team2 ? team2.name : (gameState.cupPhase==='groups' ? '???' : '')}</span>{!team2 && labelBottom && <span className="text-[9px] text-gray-500 uppercase">{labelBottom}</span>}</div>
                          {winnerId === team2Id && team2Id !== undefined && <Medal className="w-3 h-3 text-yellow-500 ml-auto" />}
                     </div>
                 </div>
             </div>
         );
      };
      return (
          <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-start p-4 text-white overflow-y-auto">
             <div className="w-full max-w-7xl mt-4">
                 <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                     <div><h1 className="text-3xl font-bold brand-font text-yellow-400 uppercase">ORGANIZAÇÃO DA COPA</h1><p className="text-gray-400 text-sm">Próximo: {gameState.cupMatches[gameState.currentMatchIndex]?.name}</p></div>
                     <button onClick={handleStartCupRacing} className="bg-green-600 hover:bg-green-500 text-white px-8 py-3 rounded-lg font-bold flex items-center shadow-lg animate-pulse"><PlayCircle className="mr-2 w-6 h-6" /> IR PARA PARTIDA</button>
                 </div>
                 <div className="overflow-x-auto pb-4 custom-scrollbar"><div className="flex gap-4 min-w-[800px] justify-between">
                        <div className="flex flex-col w-1/4 min-w-[180px]"><h3 className="text-center font-bold text-blue-400 mb-4 bg-gray-800 p-2 rounded uppercase">OITAVAS</h3><div className="flex flex-col gap-2">{[0,1,2,3,4,5,6,7].map(i => { let t1Ready = true; let t2Ready = true; if (gameState.cupPhase === 'groups') { if (i < 4) { t1Ready = isGroupFinished(0); t2Ready = isGroupFinished(1); } else { t1Ready = isGroupFinished(2); t2Ready = isGroupFinished(3); } } return renderBracketMatch("Oitavas", i, projections[i], t1Ready, t2Ready, octavasLabels[i].t, octavasLabels[i].b); })}</div></div>
                        <div className="flex flex-col w-1/4 min-w-[180px]"><h3 className="text-center font-bold text-purple-400 mb-4 bg-gray-800 p-2 rounded uppercase">QUARTAS</h3><div className="flex flex-col justify-around h-full gap-4 py-8">{[0,1,2,3].map(i => renderBracketMatch("Quartas", i, { t1: getWinnerFromMatch('Oitavas', i*2), t2: getWinnerFromMatch('Oitavas', i*2+1) }, true, true, `VENC. OIT ${i*2+1}`, `VENC. OIT ${i*2+2}`))}</div></div>
                        <div className="flex flex-col w-1/4 min-w-[180px]"><h3 className="text-center font-bold text-orange-400 mb-4 bg-gray-800 p-2 rounded uppercase">SEMI</h3><div className="flex flex-col justify-around h-full gap-8 py-16">{[0,1].map(i => renderBracketMatch("Semi", i, { t1: getWinnerFromMatch('Quartas', i*2), t2: getWinnerFromMatch('Quartas', i*2+1) }, true, true, `VENC. QRT ${i*2+1}`, `VENC. QRT ${i*2+2}`))}</div></div>
                        <div className="flex flex-col w-1/4 min-w-[180px]"><h3 className="text-center font-bold text-yellow-400 mb-4 bg-gray-800 p-2 rounded uppercase">FINAL</h3><div className="flex flex-col justify-center h-full py-20">{(() => renderBracketMatch("Final", 0, { t1: getWinnerFromMatch('Semi', 0), t2: getWinnerFromMatch('Semi', 1) }, true, true, "VENC. SEMI 1", "VENC. SEMI 2"))()}{gameState.cupPhase === 'final' && gameState.cupMatches.find(m => m.name.includes("Final"))?.winnerId && (<div className="mt-4 text-center"><Trophy className="w-16 h-16 text-yellow-400 mx-auto animate-bounce" /><p className="text-yellow-400 font-bold mt-2 uppercase">CAMPEÃO!</p></div>)}</div></div>
                    </div></div>
                 {gameState.cupPhase === 'groups' && (<div className="mt-8 border-t border-gray-700 pt-6"><h2 className="text-xl font-bold mb-4 flex items-center text-gray-400 uppercase"><LayoutGrid className="mr-2"/> GRUPOS (Simulação p/ Oitavas)</h2><div className="grid grid-cols-1 md:grid-cols-4 gap-4">{gameState.cupGroups.map((group, idx) => { const sortedIds = getSortedGroup(idx); return (<div key={idx} className="bg-gray-800 rounded p-2 text-xs"><h3 className="font-bold text-center mb-2 uppercase">GRUPO {['A','B','C','D'][idx]}</h3>{sortedIds.map((id, rank) => (<div key={id} className={`flex justify-between p-1 ${rank < 4 ? 'text-white' : 'text-gray-500'}`}><span>{rank+1}. {gameState.marbles.find(m=>m.id===id)?.name}</span><span>{gameState.cupScores[id]||0}</span></div>))}</div>)})}</div></div>)}
             </div>
          </div>
      )
  }

  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0]; const champion = gameState.marbles.find(m => m.id === championId)!; const playerWon = gameState.betMarbleId === championId;
    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8"><div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div><Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" /><div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2"><img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" /></div></div>
        <h1 className="text-6xl font-black text-white mb-2 brand-font uppercase">{champion.name}</h1><p className="text-2xl text-yellow-500 font-mono mb-4 uppercase">CAMPEÃO DO TORNEIO</p>
        {gameState.gameMode === 'points' && (<div className="text-xl text-blue-400 mb-8 font-mono font-bold uppercase">Pontuação Final: {champion.score} pts</div>)}
        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}><h3 className="text-xl font-bold mb-2 uppercase">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3><p className="text-gray-300">{playerWon ? `Sua aposta no ${champion.name} deu certo!` : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}</p></div>
        {gameState.gameMode === 'points' && (<div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60"><h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>{[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (<div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0"><div className="flex items-center space-x-3"><span className="text-gray-500 font-mono w-4">{idx + 1}</span><div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5"><img src={m.logoUrl} className="w-full h-full object-contain"/></div><span>{m.name}</span></div><span className="font-mono font-bold text-yellow-500">{m.score}</span></div>))}</div>)}
        <button onClick={resetGame} className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform uppercase">NOVO TORNEIO</button>
      </div>
    );
  }

  const isCupMatchWithoutPlayer = gameState.gameMode === 'cup' && !gameState.activeMarbleIds.includes(gameState.betMarbleId!);

  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">
      <div className="absolute inset-0 z-0"><RaceEngine key={gameState.round} activeMarbles={activeMarblesList} config={physicsConfig} obstacleSettings={obstacleSettings} onRaceFinish={handleRaceFinish} betMarbleId={gameState.betMarbleId} isPaused={isPaused} cameraMode={cameraMode} gameMode={gameState.gameMode} /></div>
      {isCupMatchWithoutPlayer && !isPaused && (<div className="absolute top-20 left-1/2 transform -translate-x-1/2 z-50 animate-in fade-in zoom-in"><button onClick={handleSimulateMatch} className="flex items-center space-x-2 bg-blue-600 hover:bg-blue-500 text-white font-bold py-3 px-6 rounded-full shadow-lg border-2 border-blue-400 animate-pulse uppercase"><FastForward className="fill-current" /><span>SIMULAR PARTIDA</span></button><div className="text-center mt-2 text-xs text-gray-400 bg-black/50 p-1 rounded uppercase">Ou continue assistindo</div></div>)}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none"><div className="flex items-center"><div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto"><div className="text-xs text-gray-400 font-bold uppercase">{gameState.gameMode === 'cup' ? gameState.cupMatches[gameState.currentMatchIndex]?.name : 'Rodada'}</div><div className="text-2xl font-mono text-yellow-400">{gameState.gameMode === 'cup' ? '' : `${gameState.round} `}<span className="text-sm text-gray-500">{gameState.gameMode === 'cup' ? '' : `/ ${gameState.totalRounds}`}</span></div></div></div>
         <div className="flex flex-col items-end pointer-events-auto"><button onClick={() => setIsPaused(true)} className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50" title="Pausar"><Pause className="w-6 h-6" /></button>
             {gameState.gameMode === 'points' && (<div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]"><div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>{gameState.marbles.sort((a,b) => b.score - a.score).slice(0, 3).map((m, i) => (<div key={m.id} className="flex justify-between text-xs mb-1"><span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span><span className="font-mono">{m.score}</span></div>))}</div>)}
             {(gameState.gameMode === 'elimination' || gameState.gameMode === 'inverted_elimination') && (<div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right"><div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div><div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div></div>)}
             {gameState.gameMode === 'cup' && (<div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right max-h-40 overflow-y-auto"><div className="text-xs text-gray-400 font-bold uppercase mb-1">{gameState.cupPhase === 'groups' ? `Grupo ${['A','B','C','D'][gameState.cupMatches[gameState.currentMatchIndex]?.groupIndex || 0]}` : 'Placar'}</div>{gameState.activeMarbleIds.map(id => { const m = gameState.marbles.find(mar => mar.id === id); return (<div key={id} className="flex justify-between text-xs space-x-2"><span>{m?.name}</span>{gameState.cupPhase === 'groups' && <span className="text-yellow-500 font-bold">{gameState.cupScores[id] || 0}</span>}</div>)})}</div>)}
         </div>
      </div>
      {isPaused && !showExitConfirm && (<div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4"><div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200"><h2 className="text-3xl font-bold text-white mb-8 brand-font uppercase">JOGO PAUSADO</h2><div className="flex flex-col space-y-4"><button onClick={() => setIsPaused(false)} className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center uppercase"><Play className="mr-2 fill-current" /> RETOMAR</button><button onClick={() => setShowExitConfirm(true)} className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center uppercase"><X className="mr-2" /> SAIR DO JOGO</button></div></div></div>)}
      {showExitConfirm && (<div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4"><div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200"><Skull className="w-16 h-16 text-red-500 mx-auto mb-4" /><h2 className="text-2xl font-bold text-white mb-2 uppercase">ABANDONAR TORNEIO?</h2><p className="text-gray-400 mb-8 uppercase">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p><div className="flex space-x-4"><button onClick={() => setShowExitConfirm(false)} className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg uppercase">CANCELAR</button><button onClick={() => { setShowExitConfirm(false); setIsPaused(false); handleExitTournament(); }} className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all uppercase">SAIR</button></div></div></div>)}
      {gameState.phase === 'round_result' && (<div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4"><div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden"><h2 className="text-3xl font-bold text-white mb-6 brand-font uppercase">FIM DA RODADA {gameState.gameMode === 'cup' ? '' : gameState.round}</h2>{(gameState.gameMode === 'elimination' || gameState.gameMode === 'inverted_elimination') ? (<div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6"><Skull className="w-8 h-8 text-red-500 mx-auto mb-2" /><div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>{gameState.lastEliminatedId !== null && (<div className="flex items-center justify-center space-x-2 mt-2"><div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden"><img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" /></div><span className="text-xl text-white font-mono uppercase">{gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}</span></div>)}</div>) : (<div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto"><div className="flex items-center justify-center mb-4 text-yellow-400 uppercase"><Medal className="mr-2" /> Resultado da Rodada</div>{activeMarblesList.sort((a,b) => a.rank - b.rank).map((m, idx) => (<div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm"><div className="flex items-center space-x-2"><span className="w-4 text-gray-500">{idx + 1}</span><div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden"><img src={m.logoUrl} className="w-full h-full object-contain"/></div><span>{m.name}</span></div><div className="flex flex-col text-right">{gameState.gameMode === 'cup' && gameState.cupMatches[gameState.currentMatchIndex]?.type !== 'group' ? (<span className={idx===0 ? "text-green-400 font-bold uppercase" : "text-red-500 uppercase"}>{idx===0 ? "VENCEU" : "ELIMINADO"}</span>) : (<><span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span><span className="text-[10px] text-gray-500 uppercase">Total: {gameState.gameMode === 'cup' ? gameState.cupScores[m.id] : m.score}</span></>)}</div></div>))}</div>)}
            {(gameState.gameMode === 'elimination' || gameState.gameMode === 'inverted_elimination') && gameState.lastEliminatedId === gameState.betMarbleId && (<div className="text-red-400 text-sm font-bold mb-6 uppercase">SEU TIME FOI ELIMINADO! 😱</div>)}
            <div className="mt-4"><p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p><div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden"><div className="h-full bg-blue-500 animate-[width_3s_linear] w-full origin-left" style={{ animationDuration: '3s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div><style>{`@keyframes shrink { from { width: 100%; } to { width: 0%; } }`}</style></div></div></div></div>)}
      {gameState.phase === 'racing' && (
        <button onClick={cycleCameraMode} className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-3 rounded-full border-2 flex items-center space-x-3 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${cameraMode === 'leader' ? 'bg-black/60 border-yellow-500/30' : cameraMode === 'bet' ? 'bg-yellow-900/80 border-yellow-400' : 'bg-red-900/80 border-red-500'}`}>
          <Camera className={`w-5 h-5 ${cameraMode !== 'leader' ? 'text-yellow-400 animate-pulse' : 'text-gray-400'}`} />
          {cameraMode === 'leader' ? (
            <span className="text-gray-300 font-bold uppercase text-sm tracking-widest">CÂMERA: LÍDER</span>
          ) : cameraMode === 'bet' ? (
            <div className="flex items-center space-x-2">
              <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden"><img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" alt="Bet" /></div>
              <span className="font-bold text-yellow-400 uppercase text-sm tracking-widest">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
            </div>
          ) : (
            <span className="text-red-400 font-bold uppercase text-sm tracking-widest">CÂMERA: LANTERNA</span>
          )}
        </button>
      )}
    </div>
  );
}

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings, GameMode } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  cameraMode: 'leader' | 'bet' | 'last';
  gameMode: GameMode;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, cameraMode, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Cache for loaded images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);
  const gateOpenRef = useRef(false);

  // Constants
  const COURSE_WIDTH = 600;
  const GATE_Y = 180; // Position of the starting gate
  const GATE_DELAY = 3000; // Time before gate opens (ms)

  // --- Particle Helper ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03, // Random fade speed
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 12 + Math.floor(Math.random() * 4); 
    const segmentHeight = 450;
    let currentY = 0;

    // --- OBSTÁCULO INICIAL: PLINKO DE PINOS MÓVEIS ---
    const plinkoStartY = GATE_Y + 100;
    const plinkoRows = 10; 
    const plinkoRowHeight = 55; 
    const plinkoEndY = plinkoStartY + (plinkoRows * plinkoRowHeight);

    // Paredes
    lines.push({ x1: 0, y1: 0, x2: 0, y2: plinkoEndY, type: 'wall' }); 
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH, y2: plinkoEndY, type: 'wall' }); 

    // Gerar Pinos Móveis com Espaçamento Igual
    for (let r = 0; r < plinkoRows; r++) {
        const py = plinkoStartY + (r * plinkoRowHeight);
        const isEven = r % 2 === 0;

        // Espaçamento e distribuição
        const pinRadius = 9;
        const spacing = 70; // Espaçamento fixo

        // Configuração de Movimento da Linha
        const rowSpeed = 0.05 * (isEven ? 1 : -1); 
        const rowRange = 70; 

        const startX = 35;

        for (let x = startX; x < COURSE_WIDTH; x += spacing) {
             pins.push({
                 x: x, 
                 y: py,
                 radius: pinRadius, 
                 type: 'pin',
                 initialX: x,
                 speed: rowSpeed,
                 range: rowRange
             });
        }
    }

    // --- FUNIL PÓS-PLINKO ---
    const funnelHeight = 180;
    const funnelExitGap = 70;

    // Parede Funil Esquerda
    lines.push({
        x1: 0, y1: plinkoEndY,
        x2: COURSE_WIDTH / 2 - funnelExitGap / 2, y2: plinkoEndY + funnelHeight,
        type: 'wall'
    });

    // Parede Funil Direita
    lines.push({
        x1: COURSE_WIDTH, y1: plinkoEndY,
        x2: COURSE_WIDTH / 2 + funnelExitGap / 2, y2: plinkoEndY + funnelHeight,
        type: 'wall'
    });

    currentY = plinkoEndY + funnelHeight + 50;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 10 });
            options.push({ type: 'slider_v', weight: 10 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 15 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 10 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 4 });

        if (options.length === 0) return 'none';

        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;

        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    for (let i = 0; i < segments; i++) {
      const type = pickObstacleType();

      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type === 'spinner') {
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 150,
          angle: 0,
          speed: 0.12,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 150,
          angle: Math.PI / 2,
          speed: -0.15,
        });

        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 300, radius: 25, type: 'bumper' });

      } else if (type === 'slider_h') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        dynamics.push({
            id: `slide_h_top_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 200,
            width: 200,
            angle: 0,
            speed: 2.5,
            range: 180,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 200
        });

        dynamics.push({
            id: `slide_h_bot_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 350,
            width: 200,
            angle: 0,
            speed: -3.0, 
            range: 180,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 350
        });

      } else if (type === 'slider_v') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
            id: `slide_v_L_${i}`,
            type: 'slider_v',
            x: COURSE_WIDTH * 0.25,
            y: currentY + 250,
            width: 120,
            angle: 0,
            speed: 1.5,
            range: 80,
            initialX: COURSE_WIDTH * 0.25,
            initialY: currentY + 250
        });

        dynamics.push({
            id: `slide_v_R_${i}`,
            type: 'slider_v',
            x: COURSE_WIDTH * 0.75,
            y: currentY + 350, 
            width: 120,
            angle: 0,
            speed: 1.5,
            range: 80,
            initialX: COURSE_WIDTH * 0.75,
            initialY: currentY + 350
        });

        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 300, radius: 28, type: 'bumper' });

      } else if (type === 'repulsor') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `repulse_${i}`,
          type: 'repulsor',
          x: COURSE_WIDTH / 2,
          y: currentY + 300,
          width: 50, 
          range: 140, 
          angle: 0,
          speed: 0.1, 
          force: 3.0
        });

      } else if (type === 'conveyor') {
        const dirType = Math.floor(Math.random() * 5);
        let angle = Math.PI / 2;
        let cx = COURSE_WIDTH * 0.5;
        let width = 200; 
        let height = 100; 

        if (dirType === 1) { angle = Math.PI / 4; cx = COURSE_WIDTH * 0.4; } 
        else if (dirType === 2) { angle = 3 * Math.PI / 4; cx = COURSE_WIDTH * 0.6; } 
        else if (dirType === 3) { angle = 0; cx = COURSE_WIDTH * 0.3; width = 150; height = 150; } 
        else if (dirType === 4) { angle = Math.PI; cx = COURSE_WIDTH * 0.7; width = 150; height = 150; }

        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'wall' });

        dynamics.push({
          id: `conveyor_${i}`,
          type: 'conveyor',
          x: cx,
          y: currentY + 250,
          width: width, 
          height: height, 
          angle: angle, 
          speed: 0.1, 
          force: 18 
        });

        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 250, radius: 20, type: 'bumper' });

      } else if (type === 'teleporter') {
        const isTrap = Math.random() > 0.5; 
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);

        let targetY;
        if (isTrap) {
            targetY = Math.max(100, currentY - (300 + Math.random() * 400));
        } else {
            targetY = currentY + (500 + Math.random() * 300);
        }

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `teleport_${i}`,
          type: 'teleporter',
          x: entranceX,
          y: currentY + 200,
          width: 70, 
          destX: exitX,
          destY: targetY,
          angle: 0,
          speed: 0,
          blinkPhase: Math.random() * Math.PI * 2,
          blinkSpeed: 0.02 + Math.random() * 0.02, 
          active: true
        });

        pins.push({ x: entranceX + (Math.random() > 0.5 ? 80 : -80), y: currentY + 200, radius: 20, type: 'bumper' });

      } else if (type === 'hollow_circle') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });

        dynamics.push({
           id: `hollow_${i}`,
           type: 'hollow_circle',
           x: COURSE_WIDTH / 2 + (Math.random() - 0.5) * 60,
           y: currentY + 250,
           width: 250, // Diameter
           angle: 0,
           speed: (Math.random() > 0.5 ? 1 : -1) * (0.02 + Math.random() * 0.02),
           range: Math.PI / 2.5 // Gap size
        });

      } else if (type === 'laser') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
          id: `laser_${i}`,
          type: 'laser',
          x: COURSE_WIDTH * 0.1, 
          y: currentY + 300,
          width: 0, 
          height: COURSE_WIDTH * 0.8, 
          angle: 0, 
          speed: 0,
          force: 25, 
          active: true,
          timer: 0
        });
        lines.push({ x1: 0, y1: currentY + 280, x2: COURSE_WIDTH * 0.15, y2: currentY + 320, type: 'wall' });

        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 300, radius: 22, type: 'bumper' });

      } else if (type === 'funnel') {
        const funnelTopY = currentY + 50;
        const funnelHeight = 250;
        const exitGap = 55; 

        lines.push({
            x1: 0, y1: funnelTopY,
            x2: COURSE_WIDTH/2 - exitGap/2, y2: funnelTopY + funnelHeight,
            type: 'wall'
        });

        lines.push({
            x1: COURSE_WIDTH, y1: funnelTopY,
            x2: COURSE_WIDTH/2 + exitGap/2, y2: funnelTopY + funnelHeight,
            type: 'wall'
        });

        pins.push({ x: COURSE_WIDTH/2, y: funnelTopY + funnelHeight + 80, radius: 20, type: 'bumper' });

      } else if (type === 'fan') {
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `fan_${i}_1`,
          type: 'fan',
          x: 20, 
          y: currentY + 250,
          width: 40,
          height: 300, 
          angle: 0, 
          speed: 0,
          force: 0.7
        });

        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 25, type: 'bumper' });

        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 200, radius: 15, type: 'bumper' });
        pins.push({ x: COURSE_WIDTH / 2, y: currentY + 350, radius: 15, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  const update = () => {
    if (isPaused) {
        audio.updateRolling(0);
        return;
    }

    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    const timeSinceStart = Date.now() - startTime.current;

    if (!gateOpenRef.current) {
        if (timeSinceStart > GATE_DELAY) {
            gateOpenRef.current = true;
            audio.playPinHit(15); 
            spawnParticles(COURSE_WIDTH/2, GATE_Y, '#10b981', 30, 8); 
        }
    }

    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life -= p.decay;
        if (p.life <= 0) {
            particlesRef.current.splice(i, 1);
        }
    }

    let totalSpeed = 0;

    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    const totalMarbles = marbles.length;

    if (totalMarbles > 1 && activeMarblesCount === 1 && gameMode !== 'inverted_elimination') {
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = totalMarbles; 
            loser.finishTime = now - startTime.current + 99999; 
        }

        if (!raceFinished.current) {
            raceFinished.current = true;
            const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
            audio.playFinish(); 
            setTimeout(() => onRaceFinish(sorted), 1000);
            return;
        }
    }

    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner' || obj.type === 'hollow_circle') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      }

      if (obj.type === 'laser') {
         obj.timer = (obj.timer || 0) + 1;
         if (obj.timer > 180) {
             obj.active = !obj.active;
             obj.timer = 0;
         }
      }

      if (obj.type === 'teleporter' && obj.blinkPhase !== undefined && obj.blinkSpeed !== undefined) {
          const val = Math.sin(timeRef.current * obj.blinkSpeed + obj.blinkPhase);
          const opacity = (val + 1) / 2; 
          obj.active = opacity > 0.3; 
          obj.timer = opacity; 
      }
    });

    pinsRef.current.forEach(pin => {
         if (pin.initialX !== undefined && pin.speed !== undefined && pin.range !== undefined) {
             pin.x = pin.initialX + Math.sin(timeRef.current * pin.speed) * pin.range;
         }
    });

    const dynamicLines: LineSegment[] = [];
    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner' || obj.type === 'slider_h' || obj.type === 'slider_v') {
        const halfW = obj.width / 2;
        const dx = Math.cos(obj.angle) * halfW;
        const dy = Math.sin(obj.angle) * halfW;
        dynamicLines.push({
          x1: obj.x - dx, y1: obj.y - dy,
          x2: obj.x + dx, y2: obj.y + dy,
          type: obj.type === 'spinner' ? 'bouncer' : 'floor'
        });
      }
    });

    const gateLine: LineSegment = { x1: 0, y1: GATE_Y, x2: COURSE_WIDTH, y2: GATE_Y, type: 'wall' };

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        if (m.x < m.radius) {
            m.x = m.radius;
            m.vx = Math.abs(m.vx) * 0.5; 
        } else if (m.x > COURSE_WIDTH - m.radius) {
            m.x = COURSE_WIDTH - m.radius;
            m.vx = -Math.abs(m.vx) * 0.5; 
        }

        // Obstacles interaction
        for (const obj of dynamicObjs) {
          if (obj.type === 'fan') {
            const dx = m.x - obj.x;
            const dy = m.y - obj.y;
            const localX = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle);
            const localY = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle);
            const halfWidth = obj.width / 2; 
            const range = obj.height || 200;
            if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
               m.vx += Math.cos(obj.angle) * (obj.force || 0.5) * dt;
               m.vy += Math.sin(obj.angle) * (obj.force || 0.5) * dt;
               if (Math.random() < 0.1) spawnParticles(m.x, m.y, '#e2e8f0', 1, 1);
            }
          } else if (obj.type === 'repulsor') {
            const dx = m.x - obj.x;
            const dy = m.y - obj.y;
            const distSq = dx*dx + dy*dy;
            const range = obj.range || 100;
            if (distSq < range * range) {
               const dist = Math.sqrt(distSq);
               const force = (obj.force || 1) * (1 - dist/range) * (0.5 + (Math.sin(timeRef.current * obj.speed) + 1) * 0.5);
               m.vx += (dx / dist) * force * dt * 50;
               m.vy += (dy / dist) * force * dt * 50;
            }
          } else if (obj.type === 'conveyor') {
             const dx = m.x - obj.x;
             const dy = m.y - obj.y;
             const localParallel = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle); 
             const localPerp = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle); 
             if (Math.abs(localParallel) < obj.width / 2 && Math.abs(localPerp) < (obj.height || 50) / 2) {
                m.vx += Math.cos(obj.angle) * (obj.force || 10) * dt;
                m.vy += Math.sin(obj.angle) * (obj.force || 10) * dt;
             }
          } else if (obj.type === 'teleporter' && obj.active) {
            const dx = m.x - obj.x;
            const dy = m.y - obj.y;
            if (Math.sqrt(dx*dx + dy*dy) < (obj.width/2) && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {
                 const isBackwards = (obj.destY || 0) < obj.y;
                 spawnParticles(m.x, m.y, isBackwards ? '#ef4444' : '#d946ef', 15, 4); 
                 m.x = obj.destX || m.x;
                 m.y = obj.destY || m.y;
                 m.vx *= 0.2; 
                 m.vy = isBackwards ? 0 : Math.abs(m.vy) + 2; 
                 teleportCooldowns.current[m.id] = now + 1500; 
                 audio.playPinHit(8); 
                 spawnParticles(m.x, m.y, '#06b6d4', 15, 4); 
            }
          } else if (obj.type === 'laser' && obj.active) {
            const lx2 = obj.x + Math.cos(obj.angle) * (obj.height || 300);
            const ly2 = obj.y + Math.sin(obj.angle) * (obj.height || 300);
            const A = m.x - obj.x; const B = m.y - obj.y; const C = lx2 - obj.x; const D = ly2 - obj.y;
            const dot = A * C + B * D; const lenSq = C * C + D * D;
            let param = lenSq !== 0 ? dot / lenSq : -1;
            let xx = param < 0 ? obj.x : param > 1 ? lx2 : obj.x + param * C;
            let yy = param < 0 ? obj.y : param > 1 ? ly2 : obj.y + param * D;
            const dx = m.x - xx; const dy = m.y - yy;
            if (Math.sqrt(dx * dx + dy * dy) < m.radius + 5) { 
                m.vx += (dx/Math.sqrt(dx*dx+dy*dy)) * (obj.force || 20) * dt * 10;
                m.vy += (dy/Math.sqrt(dx*dx+dy*dy)) * (obj.force || 20) * dt * 10;
                spawnParticles(m.x, m.y, '#ef4444', 3, 4);
            }
          }
        }

        m.angle += m.omega * dt;
        m.omega *= 0.999; 
        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        if (m.vx*m.vx + m.vy*m.vy < 0.2) { m.vx += (Math.random() - 0.5); m.vy += 0.5; }

        if (!gateOpenRef.current) checkLineCollision(m, gateLine);
        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);
        for (let j = i + 1; j < marbles.length; j++) if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);

        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          m.rank = marbles.filter(b => b.finished).length;
          audio.playPinHit(10);
          spawnParticles(m.x, m.y, '#10b981', 10, 4);
          if (gameMode === 'inverted_elimination' && !raceFinished.current) {
              raceFinished.current = true;
              onRaceFinish(marblesRef.current);
              return;
          }
        }
        if (!m.finished) totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
      }
    }

    audio.updateRolling(totalSpeed);

    // --- CAMERA LOGIC UPDATED ---
    let targetY = cameraY.current;
    const allActive = marbles.filter(m => !m.finished);

    if (allActive.length > 0) {
        allActive.sort((a, b) => b.y - a.y); // Index 0 is Leader, Last index is Lanterna

        if (cameraMode === 'bet' && betMarbleId !== null) {
            const betMarble = marbles.find(m => m.id === betMarbleId && !m.finished);
            if (betMarble) {
                targetY = betMarble.y - 300;
            } else {
                targetY = allActive[0].y - 300; // Fallback para líder
            }
        } else if (cameraMode === 'last') {
            targetY = allActive[allActive.length - 1].y - 300;
        } else {
            // Default: Leader
            targetY = allActive[0].y - 300;
        }
    }

    cameraY.current += (targetY - cameraY.current) * 0.08;

    if (marbles.filter(m => !m.finished).length === 0 && !raceFinished.current) {
        raceFinished.current = true;
        onRaceFinish([...marbles].sort((a, b) => a.rank - b.rank));
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean, cx: number, cy: number) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
        if (intensity > 3.0) spawnParticles(cx, cy, isBouncy ? '#ef4444' : '#94a3b8', Math.floor(intensity), intensity * 0.5);
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny; const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;
    const jT_ideal = -vSurf / (3.5);
    const maxJt = 0.5 * Math.abs(jN);
    let jT = Math.abs(jT_ideal) > maxJt ? Math.sign(jT_ideal) * maxJt : jT_ideal;

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1; const dy = line.y2 - line.y1; const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx; const closeY = line.y1 + t * dy;
    const distX = ball.x - closeX; const distY = ball.y - closeY; const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist; const ny = distY / dist;
      ball.x += nx * (ball.radius - dist);
      ball.y += ny * (ball.radius - dist);
      resolveCollisionPhysics(ball, nx, ny, isDynamic && line.type === 'bouncer', closeX, closeY);
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x; const dy = ball.y - pin.y; const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;
    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq); const nx = dx / dist; const ny = dy / dist;
      ball.x += nx * (minDist - dist); ball.y += ny * (minDist - dist);
      const intensity = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
      if (intensity > 1) audio.playPinHit(intensity);
      resolveCollisionPhysics(ball, nx, ny, pin.type === 'bumper', pin.x + nx * pin.radius, pin.y + ny * pin.radius);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x; const dy = m2.y - m1.y; const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;
    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq); const nx = dx / dist; const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;
      m1.x -= nx * overlap; m1.y -= ny * overlap; m2.x += nx * overlap; m2.y += ny * overlap;
      const dot = (m1.vx - m2.vx) * nx + (m1.vy - m2.vy) * ny;
      if (dot > 0) {
         if (dot > 2) audio.playPinHit(dot * 0.5);
         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx; m1.vy -= impulse * ny;
         m2.vx += impulse * nx; m2.vy += impulse * ny;
      }
    }
  };

  useEffect(() => {
    generateLevel();
    raceFinished.current = false; gateOpenRef.current = false;
    startTime.current = Date.now(); cameraY.current = 0; timeRef.current = 0;
    teleportCooldowns.current = {}; particlesRef.current = [];

    activeMarbles.forEach(m => {
        const img = new Image(); img.src = m.logoUrl;
        imagesRef.current[m.id] = img;
    });

    const totalWidth = COURSE_WIDTH * 0.9;
    const startX = COURSE_WIDTH * 0.05;
    const spacing = totalWidth / Math.max(1, activeMarbles.length);

    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: startX + (spacing * index) + (spacing/2),
      y: GATE_Y - 50,
      vx: 0, vy: 0, angle: 0, omega: 0, finished: false, rank: 0
    }));
    audio.resume();
  }, [activeMarbles]); 

  const drawLeaderboard = (ctx: CanvasRenderingContext2D) => {
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1; if (b.finished) return 1;
      return b.y - a.y;
    });
    const boxWidth = 110; const itemHeight = 18; const startX = 10; const startY = 90; 
    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 6);
    ctx.fill();
    ctx.font = 'bold 10px "Roboto Mono"'; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    sorted.forEach((m, index) => {
       const y = startY + 10 + index * itemHeight; 
       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#6b7280';
       ctx.fillText(`${index + 1}.`, startX + 5, y);
       ctx.fillStyle = m.color; ctx.beginPath(); ctx.arc(startX + 25, y, 3, 0, Math.PI*2); ctx.fill();
       ctx.fillStyle = m.finished ? '#10b981' : '#e5e7eb'; ctx.fillText(m.name, startX + 35, y);
       if (m.id === betMarbleId) { ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 1; ctx.strokeRect(startX + 2, y - 8, boxWidth - 4, 16); }
    });
  };

  const draw = () => {
    const canvas = canvasRef.current; if (!canvas) return;
    const ctx = canvas.getContext('2d'); if (!ctx) return;
    if (canvas.width !== canvas.offsetWidth || canvas.height !== canvas.offsetHeight) {
      canvas.width = canvas.offsetWidth; canvas.height = canvas.offsetHeight;
    }
    ctx.fillStyle = '#1f2937'; ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.save();
    const scale = canvas.width / COURSE_WIDTH; ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa'; ctx.lineWidth = l.type === 'wall' ? 6 : 4;
      ctx.beginPath(); ctx.moveTo(l.x1, l.y1); ctx.lineTo(l.x2, l.y2); ctx.stroke();
    });

    dynamicRef.current.forEach(obj => {
       ctx.save(); ctx.translate(obj.x, obj.y); ctx.rotate(obj.angle);
       if (obj.type === 'fan') {
          ctx.fillStyle = '#64748b'; ctx.fillRect(-10, -obj.width/2, 20, obj.width);
          const gradient = ctx.createLinearGradient(0, 0, obj.height || 200, 0);
          gradient.addColorStop(0, 'rgba(255, 255, 255, 0.4)'); gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');
          ctx.fillStyle = gradient; ctx.fillRect(0, -obj.width/2, obj.height || 200, obj.width);
       } else if (obj.type === 'hollow_circle') {
             ctx.beginPath(); ctx.arc(0, 0, obj.width / 2, (obj.range || 1.0)/2, Math.PI * 2 - (obj.range || 1.0)/2);
             ctx.strokeStyle = '#d946ef'; ctx.lineWidth = 12; ctx.stroke();
       } else if (obj.type !== 'repulsor' && obj.type !== 'conveyor' && obj.type !== 'teleporter' && obj.type !== 'laser') {
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b'; ctx.lineWidth = 8;
         ctx.beginPath(); ctx.moveTo(-obj.width/2, 0); ctx.lineTo(obj.width/2, 0); ctx.stroke();
       }
       ctx.restore();
    });

    if (!gateOpenRef.current) {
        ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 10;
        ctx.beginPath(); ctx.moveTo(0, GATE_Y); ctx.lineTo(COURSE_WIDTH, GATE_Y); ctx.stroke();
    }

    particlesRef.current.forEach(p => {
        ctx.globalAlpha = p.life; ctx.fillStyle = p.color;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2); ctx.fill();
    });
    ctx.globalAlpha = 1.0;

    pinsRef.current.forEach(p => {
      ctx.beginPath(); ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af'; ctx.fill();
    });

    marblesRef.current.forEach(m => {
      ctx.save(); ctx.translate(m.x, m.y); ctx.rotate(-m.angle); 
      ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.fillStyle = '#ffffff'; ctx.fill();
      ctx.save(); ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2); ctx.clip();
      const img = imagesRef.current[m.id];
      if (img && img.complete) ctx.drawImage(img, -m.radius, -m.radius, m.radius * 2, m.radius * 2);
      else { ctx.fillStyle = m.color; ctx.fill(); }
      ctx.restore();
      ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2); ctx.strokeStyle = m.color; ctx.lineWidth = 2; ctx.stroke();
      ctx.restore(); 
      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(m.x, m.y, m.radius + 6, 0, Math.PI * 2); ctx.stroke();
      }
    });

    ctx.restore(); 
    drawLeaderboard(ctx);
  };

  useEffect(() => {
    const loop = () => { update(); draw(); requestRef.current = requestAnimationFrame(loop); };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return <canvas ref={canvasRef} className="w-full h-full block" />;
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings, GameMode } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  cameraMode: 'leader' | 'bet' | 'last';
  gameMode: GameMode;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, cameraMode, gameMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);
  const gateOpenRef = useRef(false);

  const COURSE_WIDTH = 600;
  const GATE_Y = 180;
  const GATE_DELAY = 3000;

  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x, y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03,
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    const segments = 12 + Math.floor(Math.random() * 4); 
    const segmentHeight = 450;

    const plinkoStartY = GATE_Y + 100;
    const plinkoRows = 10; 
    const plinkoRowHeight = 55; 
    const plinkoEndY = plinkoStartY + (plinkoRows * plinkoRowHeight);

    lines.push({ x1: 0, y1: 0, x2: 0, y2: plinkoEndY, type: 'wall' }); 
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH, y2: plinkoEndY, type: 'wall' }); 

    for (let r = 0; r < plinkoRows; r++) {
        const py = plinkoStartY + (r * plinkoRowHeight);
        const isEven = r % 2 === 0;
        const pinRadius = 9;
        const spacing = 70;
        const rowSpeed = 0.05 * (isEven ? 1 : -1); 
        const rowRange = 70; 
        const startX = 35;
        for (let x = startX; x < COURSE_WIDTH; x += spacing) {
             pins.push({ x, y: py, radius: pinRadius, type: 'pin', initialX: x, speed: rowSpeed, range: rowRange });
        }
    }

    const funnelHeight = 180;
    const funnelExitGap = 70;
    lines.push({ x1: 0, y1: plinkoEndY, x2: COURSE_WIDTH / 2 - funnelExitGap / 2, y2: plinkoEndY + funnelHeight, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: plinkoEndY, x2: COURSE_WIDTH / 2 + funnelExitGap / 2, y2: plinkoEndY + funnelHeight, type: 'wall' });

    let currentY = plinkoEndY + funnelHeight + 50;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) { options.push({ type: 'slider_h', weight: 10 }); options.push({ type: 'slider_v', weight: 10 }); }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 15 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 10 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 4 });
        if (options.length === 0) return 'none';
        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;
        for (const opt of options) { if (random < opt.weight) return opt.type; random -= opt.weight; }
        return options[0].type;
    };

    for (let i = 0; i < segments; i++) {
      const type = pickObstacleType();
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type === 'spinner') {
        dynamics.push({ id: `s1_${i}`, type: 'spinner', x: COURSE_WIDTH * 0.35, y: currentY + 250, width: 150, angle: 0, speed: 0.12 });
        dynamics.push({ id: `s2_${i}`, type: 'spinner', x: COURSE_WIDTH * 0.65, y: currentY + 350, width: 150, angle: Math.PI / 2, speed: -0.15 });
      } else if (type === 'slider_h') {
        dynamics.push({ id: `sh_${i}`, type: 'slider_h', x: COURSE_WIDTH/2, y: currentY + 200, width: 200, angle: 0, speed: 2.5, range: 180, initialX: COURSE_WIDTH/2 });
      } else if (type === 'slider_v') {
        dynamics.push({ id: `sv_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.25, y: currentY + 250, width: 120, angle: 0, speed: 1.5, range: 80, initialY: currentY + 250 });
      } else if (type === 'repulsor') {
        dynamics.push({ id: `r_${i}`, type: 'repulsor', x: COURSE_WIDTH/2, y: currentY + 300, width: 50, range: 140, angle: 0, speed: 0.1, force: 3.0 });
      } else if (type === 'conveyor') {
        dynamics.push({ id: `c_${i}`, type: 'conveyor', x: COURSE_WIDTH/2, y: currentY + 250, width: 200, height: 100, angle: Math.PI/2, speed: 0.1, force: 18 });
      } else if (type === 'teleporter') {
        const exitY = Math.random() > 0.5 ? Math.max(100, currentY - 400) : currentY + 600;
        dynamics.push({ id: `t_${i}`, type: 'teleporter', x: COURSE_WIDTH/2, y: currentY + 200, width: 70, destX: COURSE_WIDTH/2, destY: exitY, angle: 0, speed: 0, blinkPhase: Math.random()*Math.PI, blinkSpeed: 0.03, active: true });
      } else if (type === 'hollow_circle') {
        dynamics.push({ id: `h_${i}`, type: 'hollow_circle', x: COURSE_WIDTH/2, y: currentY + 250, width: 250, angle: 0, speed: 0.03, range: Math.PI/2.5 });
      } else if (type === 'laser') {
        dynamics.push({ id: `l_${i}`, type: 'laser', x: 20, y: currentY + 300, width: 0, height: COURSE_WIDTH*0.8, angle: 0, speed: 0, force: 25, active: true, timer: 0 });
      } else if (type === 'fan') {
        dynamics.push({ id: `f_${i}`, type: 'fan', x: 20, y: currentY + 250, width: 40, height: 300, angle: 0, speed: 0, force: 0.7 });
      }
      currentY += segmentHeight;
    }
    finishLineY.current = currentY + 250;
    linesRef.current = lines; pinsRef.current = pins; dynamicRef.current = dynamics;
  };

  const update = () => {
    if (isPaused || raceFinished.current) { audio.updateRolling(0); return; }
    if (!gateOpenRef.current && (Date.now() - startTime.current > GATE_DELAY)) {
      gateOpenRef.current = true; audio.playPinHit(15); spawnParticles(COURSE_WIDTH/2, GATE_Y, '#10b981', 30, 8);
    }
    const STEPS = 8; const dt = 1 / STEPS; timeRef.current += 1; const now = Date.now();
    const marbles = marblesRef.current;

    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i]; p.x += p.vx; p.y += p.vy; p.life -= p.decay;
        if (p.life <= 0) particlesRef.current.splice(i, 1);
    }

    dynamicRef.current.forEach(obj => {
      if (obj.type === 'spinner' || obj.type === 'hollow_circle') obj.angle += obj.speed;
      else if (obj.type === 'slider_h') obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      else if (obj.type === 'slider_v') obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      if (obj.type === 'laser') { obj.timer = (obj.timer || 0) + 1; if (obj.timer > 180) { obj.active = !obj.active; obj.timer = 0; } }
      if (obj.type === 'teleporter' && obj.blinkPhase !== undefined) {
          const opacity = (Math.sin(timeRef.current * (obj.blinkSpeed || 0.03) + obj.blinkPhase) + 1) / 2;
          obj.active = opacity > 0.3; obj.timer = opacity;
      }
    });

    pinsRef.current.forEach(pin => {
      if (pin.initialX !== undefined) pin.x = pin.initialX + Math.sin(timeRef.current * (pin.speed || 0.05)) * (pin.range || 70);
    });

    let totalSpeed = 0;
    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i]; if (m.finished) continue;
        m.vy += config.gravity * dt; m.x += m.vx * dt; m.y += m.vy * dt;
        if (m.x < m.radius) { m.x = m.radius; m.vx = Math.abs(m.vx) * 0.5; }
        else if (m.x > COURSE_WIDTH - m.radius) { m.x = COURSE_WIDTH - m.radius; m.vx = -Math.abs(m.vx) * 0.5; }

        for (const obj of dynamicRef.current) {
          if (obj.type === 'fan') {
            const dx = m.x - obj.x; const dy = m.y - obj.y;
            const lx = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle);
            const ly = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle);
            if (lx > 0 && lx < (obj.height || 200) && Math.abs(ly) < obj.width/2) {
               m.vx += Math.cos(obj.angle) * (obj.force || 0.5) * dt; m.vy += Math.sin(obj.angle) * (obj.force || 0.5) * dt;
            }
          } else if (obj.type === 'repulsor') {
            const dx = m.x - obj.x; const dy = m.y - obj.y; const dSq = dx*dx + dy*dy;
            if (dSq < (obj.range || 100)**2) {
               const dist = Math.sqrt(dSq); const force = (obj.force || 1) * (1 - dist/(obj.range || 100)) * (0.5 + (Math.sin(timeRef.current * obj.speed) + 1) * 0.5);
               m.vx += (dx/dist) * force * dt * 50; m.vy += (dy/dist) * force * dt * 50;
            }
          } else if (obj.type === 'conveyor') {
             const dx = m.x - obj.x; const dy = m.y - obj.y;
             const lp = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle);
             const lr = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle);
             if (Math.abs(lp) < obj.width/2 && Math.abs(lr) < (obj.height || 50)/2) {
                m.vx += Math.cos(obj.angle) * (obj.force || 10) * dt; m.vy += Math.sin(obj.angle) * (obj.force || 10) * dt;
             }
          } else if (obj.type === 'teleporter' && obj.active) {
            const dx = m.x - obj.x; const dy = m.y - obj.y;
            if (Math.sqrt(dx*dx + dy*dy) < obj.width/2 && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {
                 m.x = obj.destX || m.x; m.y = obj.destY || m.y; m.vx *= 0.2; m.vy = (obj.destY||0) < obj.y ? 0 : Math.abs(m.vy) + 2;
                 teleportCooldowns.current[m.id] = now + 1500; audio.playPinHit(8); spawnParticles(m.x, m.y, '#06b6d4', 15, 4);
            }
          }
        }

        m.angle += m.omega * dt; m.omega *= 0.999; m.vx *= Math.pow(config.friction, dt); m.vy *= Math.pow(config.friction, dt);
        if (!gateOpenRef.current) checkLineCollision(m, { x1: 0, y1: GATE_Y, x2: COURSE_WIDTH, y2: GATE_Y, type: 'wall' });
        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);
        for (let j = i + 1; j < marbles.length; j++) if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);

        if (m.y > finishLineY.current) {
          m.finished = true; m.finishTime = Date.now() - startTime.current; m.rank = marbles.filter(b => b.finished).length;
          audio.playPinHit(10);
          if (gameMode === 'inverted_elimination' && !raceFinished.current) { raceFinished.current = true; onRaceFinish(marblesRef.current); return; }
        }
        if (!m.finished) totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy);
      }
    }
    audio.updateRolling(totalSpeed);

    let targetY = cameraY.current;
    const active = marbles.filter(m => !m.finished);
    if (active.length > 0) {
        active.sort((a, b) => b.y - a.y);
        if (cameraMode === 'bet' && betMarbleId !== null) {
            const b = marbles.find(m => m.id === betMarbleId && !m.finished);
            targetY = b ? b.y - 300 : active[0].y - 300;
        } else if (cameraMode === 'last') targetY = active[active.length - 1].y - 300;
        else targetY = active[0].y - 300;
    }
    cameraY.current += (targetY - cameraY.current) * 0.08;
    if (marbles.filter(m => !m.finished).length === 0 && !raceFinished.current) {
        raceFinished.current = true; onRaceFinish([...marbles].sort((a,b) => a.rank - b.rank));
    }
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1; const dy = line.y2 - line.y1; const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx; const closeY = line.y1 + t * dy;
    const distX = ball.x - closeX; const distY = ball.y - closeY; const distSq = distX*distX + distY*distY;
    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq); const nx = distX / dist; const ny = distY / dist;
      ball.x += nx * (ball.radius - dist); ball.y += ny * (ball.radius - dist);
      const vDotN = ball.vx * nx + ball.vy * ny;
      if (vDotN <= 0) {
          const rest = isDynamic && line.type === 'bouncer' ? 1.5 : config.restitution;
          const jN = -(1 + rest) * vDotN; ball.vx += jN * nx; ball.vy += jN * ny;
          if (Math.abs(vDotN) > 1) audio.playBump(Math.abs(vDotN));
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x; const dy = ball.y - pin.y; const dSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;
    if (dSq < minDist * minDist) {
      const dist = Math.sqrt(dSq); const nx = dx / dist; const ny = dy / dist;
      ball.x += nx * (minDist - dist); ball.y += ny * (minDist - dist);
      const vDotN = ball.vx * nx + ball.vy * ny;
      if (vDotN <= 0) {
          const jN = -(1 + config.restitution) * vDotN; ball.vx += jN * nx; ball.vy += jN * ny;
          audio.playPinHit(Math.abs(vDotN));
      }
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x; const dy = m2.y - m1.y; const dSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;
    if (dSq < minDist * minDist) {
      const dist = Math.sqrt(dSq); const nx = dx / dist; const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;
      m1.x -= nx * overlap; m1.y -= ny * overlap; m2.x += nx * overlap; m2.y += ny * overlap;
      const dot = (m1.vx - m2.vx) * nx + (m1.vy - m2.vy) * ny;
      if (dot > 0) {
         const imp = dot * 0.9; m1.vx -= imp * nx; m1.vy -= imp * ny; m2.vx += imp * nx; m2.vy += imp * ny;
         if (dot > 2) audio.playPinHit(dot * 0.5);
      }
    }
  };

  useEffect(() => {
    generateLevel(); startTime.current = Date.now(); cameraY.current = 0; timeRef.current = 0;
    activeMarbles.forEach(m => { const img = new Image(); img.src = m.logoUrl; imagesRef.current[m.id] = img; });
    const sX = COURSE_WIDTH * 0.05; const sp = (COURSE_WIDTH * 0.9) / Math.max(1, activeMarbles.length);
    marblesRef.current = activeMarbles.map((m, i) => ({ ...m, x: sX + sp*i + sp/2, y: GATE_Y-50, vx: 0, vy: 0, finished: false }));
    audio.resume();
  }, [activeMarbles]); 

  const drawTeleporter = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle, isExit: boolean) => {
    const opacity = obj.timer || 1.0; if (opacity < 0.1 && !isExit) return;
    ctx.save(); ctx.globalAlpha = isExit ? 1.0 : opacity;
    const r = obj.width / 2; const isTrap = (obj.destY || 0) < obj.y;
    const color = isExit ? '#06b6d4' : (isTrap ? '#ef4444' : '#d946ef');
    ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.strokeStyle = color; ctx.lineWidth = 3; ctx.stroke();
    ctx.fillStyle = '#fff'; ctx.font = '10px Arial'; ctx.textAlign = 'center'; ctx.fillText(isExit ? 'SAÍDA' : (isTrap ? 'ARMADILHA' : 'PORTAL'), 0, 4);
    ctx.restore();
  };

  const drawConveyor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    ctx.fillStyle = '#334155'; ctx.fillRect(-obj.width/2, -obj.height!/2, obj.width, obj.height!);
    const off = (timeRef.current * (obj.speed || 0.1) * 50) % 40;
    ctx.fillStyle = 'rgba(255,255,255,0.3)';
    for(let x = -obj.width/2; x < obj.width/2; x += 40) {
        ctx.beginPath(); ctx.moveTo(x + off - 5, -8); ctx.lineTo(x + off + 5, 0); ctx.lineTo(x + off - 5, 8); ctx.fill();
    }
  };

  const draw = () => {
    const canvas = canvasRef.current; if (!canvas) return;
    const ctx = canvas.getContext('2d'); if (!ctx) return;
    canvas.width = canvas.offsetWidth; canvas.height = canvas.offsetHeight;
    ctx.fillStyle = '#1f2937'; ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.save(); const scale = canvas.width / COURSE_WIDTH; ctx.scale(scale, scale);
    ctx.translate(0, -Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100)));

    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa'; ctx.lineWidth = l.type === 'wall' ? 6 : 4;
      ctx.beginPath(); ctx.moveTo(l.x1, l.y1); ctx.lineTo(l.x2, l.y2); ctx.stroke();
    });

    dynamicRef.current.forEach(obj => {
       ctx.save(); ctx.translate(obj.x, obj.y); ctx.rotate(obj.angle);
       if (obj.type === 'fan') {
          ctx.fillStyle = '#64748b'; ctx.fillRect(-10, -obj.width/2, 20, obj.width);
          const g = ctx.createLinearGradient(0, 0, obj.height || 200, 0);
          g.addColorStop(0, 'rgba(255,255,255,0.4)'); g.addColorStop(1, 'rgba(255,255,255,0)');
          ctx.fillStyle = g; ctx.fillRect(0, -obj.width/2, obj.height || 200, obj.width);
       } else if (obj.type === 'hollow_circle') {
          ctx.beginPath(); ctx.arc(0, 0, obj.width/2, (obj.range||1)/2, Math.PI*2 - (obj.range||1)/2); ctx.strokeStyle = '#d946ef'; ctx.lineWidth = 12; ctx.stroke();
       } else if (obj.type === 'repulsor') {
          const p = (Math.sin(timeRef.current * (obj.speed||0.1)) + 1) / 2;
          ctx.beginPath(); ctx.arc(0, 0, obj.width/2, 0, Math.PI*2); ctx.fillStyle = '#8b5cf6'; ctx.fill();
          ctx.beginPath(); ctx.arc(0, 0, obj.width/2 + p*(obj.range!-obj.width/2), 0, Math.PI*2); ctx.strokeStyle = `rgba(139,92,246,${1-p})`; ctx.stroke();
       } else if (obj.type === 'conveyor') {
          drawConveyor(ctx, obj);
       } else if (obj.type === 'laser') {
          ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
          if (obj.active) {
              ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(obj.height!, 0); ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 4; ctx.stroke();
          }
       } else if (obj.type === 'teleporter') {
          drawTeleporter(ctx, obj, false);
       } else {
          ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b'; ctx.lineWidth = 8;
          ctx.beginPath(); ctx.moveTo(-obj.width/2, 0); ctx.lineTo(obj.width/2, 0); ctx.stroke();
       }
       ctx.restore();
       if (obj.type === 'teleporter' && obj.destX !== undefined) {
           ctx.save(); ctx.translate(obj.destX, obj.destY!); drawTeleporter(ctx, obj, true); ctx.restore();
       }
    });

    if (!gateOpenRef.current) { ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 10; ctx.beginPath(); ctx.moveTo(0, GATE_Y); ctx.lineTo(COURSE_WIDTH, GATE_Y); ctx.stroke(); }
    particlesRef.current.forEach(p => { ctx.globalAlpha = p.life; ctx.fillStyle = p.color; ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI*2); ctx.fill(); }); ctx.globalAlpha = 1.0;
    pinsRef.current.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, p.radius, 0, Math.PI*2); ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af'; ctx.fill(); });
    marblesRef.current.forEach(m => {
      ctx.save(); ctx.translate(m.x, m.y); ctx.rotate(-m.angle); 
      ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI*2); ctx.fillStyle = '#fff'; ctx.fill();
      ctx.save(); ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI*2); ctx.clip();
      if (imagesRef.current[m.id]?.complete) ctx.drawImage(imagesRef.current[m.id], -m.radius, -m.radius, m.radius*2, m.radius*2);
      else { ctx.fillStyle = m.color; ctx.fill(); }
      ctx.restore();
      ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI*2); ctx.strokeStyle = m.color; ctx.lineWidth = 2; ctx.stroke();
      ctx.restore(); 
      if (m.id === betMarbleId) { ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 3; ctx.beginPath(); ctx.arc(m.x, m.y, m.radius+6, 0, Math.PI*2); ctx.stroke(); }
    });
    ctx.restore(); 
  };

  useEffect(() => {
    const l = () => { update(); draw(); requestRef.current = requestAnimationFrame(l); };
    requestRef.current = requestAnimationFrame(l);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return <canvas ref={canvasRef} className="w-full h-full block" />;
};

export default RaceEngine;

{
  "name": "Marble Royale & Pong Royale",
  "description": "Um portal de mini-games incluindo Marble Royale e um Pong controlado por bússola.",
  "requestFramePermissions": [
    "camera"
  ]
}

export interface Marble {
  id: number;
  color: string;
  name: string;
  logoUrl: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  angle: number;
  omega: number;
  score: number;
  finished: boolean;
  finishTime: number;
  rank: number;
}

export interface LineSegment {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  type: 'wall' | 'floor' | 'bouncer';
}

export interface CircleObstacle {
  x: number;
  y: number;
  radius: number;
  type: 'pin' | 'bumper';
  initialX?: number;
  speed?: number;
  range?: number;
}

export interface DynamicObstacle {
  id: string;
  type: 'spinner' | 'slider_h' | 'slider_v' | 'fan' | 'repulsor' | 'conveyor' | 'laser' | 'teleporter' | 'hollow_circle';
  x: number;
  y: number;
  width: number;
  height?: number;
  angle: number;
  speed: number;
  range?: number;
  initialX?: number;
  initialY?: number;
  force?: number;
  destX?: number;
  destY?: number;
  active?: boolean;
  timer?: number;
  blinkPhase?: number;
  blinkSpeed?: number;
}

export interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  decay: number;
  color: string;
  size: number;
}

export interface PhysicsConfig {
  gravity: number;
  restitution: number;
  friction: number;
}

export interface ObstacleSettings {
  spinner: boolean;
  slider: boolean;
  repulsor: boolean;
  conveyor: boolean;
  teleporter: boolean;
  hollow_circle: boolean;
  laser: boolean;
  fan: boolean;
  funnel: boolean;
}

export type GameMode = 'elimination' | 'inverted_elimination' | 'points' | 'cup' | 'pong';

export interface Match {
  id: string;
  name: string;
  marbleIds: number[];
  type: 'group' | 'knockout';
  nextPhase?: boolean;
  groupIndex?: number;
}

export interface GameState {
  gameMode: GameMode;
  phase: 'betting' | 'cup_tree' | 'racing' | 'round_result' | 'champion' | 'pong_active';
  round: number;
  totalRounds: number;
  marbles: Marble[];
  activeMarbleIds: number[];
  betMarbleId: number | null;
  lastEliminatedId: number | null;
  roundPoints: Record<number, number>;
  cupMatches: Match[];
  currentMatchIndex: number;
  cupGroups: number[][];
  cupScores: Record<number, number>;
  cupPhase: 'groups' | 'octavas' | 'quartas' | 'semi' | 'final';
}

import React, { useRef, useEffect, useState } from 'react';
import { X, Trophy, Activity, ArrowLeftRight } from 'lucide-react';

interface PongGameProps {
  onExit: () => void;
}

const PongGame: React.FC<PongGameProps> = ({ onExit }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [score, setScore] = useState({ player: 0, ai: 0 });
  const [permissionGranted, setPermissionGranted] = useState<boolean | null>(null);
  const orientationRef = useRef<number>(0);
  const gameRef = useRef({
    ballX: 300,
    ballY: 400,
    ballVX: 4,
    ballVY: -4,
    playerX: 250,
    aiX: 250,
    paddleWidth: 100,
    paddleHeight: 15,
    ballRadius: 10,
    canvasWidth: 600,
    canvasHeight: 800,
  });

  const requestPermission = async () => {
    if (typeof (DeviceOrientationEvent as any).requestPermission === 'function') {
      try {
        const response = await (DeviceOrientationEvent as any).requestPermission();
        if (response === 'granted') {
          setPermissionGranted(true);
        } else {
          setPermissionGranted(false);
        }
      } catch (e) {
        setPermissionGranted(false);
      }
    } else {
      // Browsers que não exigem permissão explícita
      setPermissionGranted(true);
    }
  };

  useEffect(() => {
    const handleOrientation = (e: DeviceOrientationEvent) => {
      // Usando alpha (bússola) ou gamma (inclinação lateral)
      // O usuário pediu "bússola", mas para controle de Pong, inclinação (gamma) costuma ser mais intuitivo.
      // Vou priorizar alpha conforme pedido, mapeando 360 graus para a largura da tela.
      if (e.alpha !== null) {
        // Mapear alpha (0-360) para a posição da paleta
        // Normalizamos o alpha para um range que faça sentido
        orientationRef.current = e.alpha;
      }
    };

    window.addEventListener('deviceorientation', handleOrientation);
    return () => window.removeEventListener('deviceorientation', handleOrientation);
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationId: number;

    const update = () => {
      const g = gameRef.current;

      // Movimentação da paleta do jogador baseada na bússola (alpha)
      // Ajustamos a sensibilidade para que o movimento seja fluido
      const targetX = (orientationRef.current / 360) * g.canvasWidth - g.paddleWidth / 2;
      g.playerX += (targetX - g.playerX) * 0.15; // Suavização

      // Limites da paleta do jogador
      if (g.playerX < 0) g.playerX = 0;
      if (g.playerX > g.canvasWidth - g.paddleWidth) g.playerX = g.canvasWidth - g.paddleWidth;

      // Movimentação da IA (Simples acompanhamento da bola)
      const aiTarget = g.ballX - g.paddleWidth / 2;
      g.aiX += (aiTarget - g.aiX) * 0.08;

      // Limites da paleta da IA
      if (g.aiX < 0) g.aiX = 0;
      if (g.aiX > g.canvasWidth - g.paddleWidth) g.aiX = g.canvasWidth - g.paddleWidth;

      // Movimentação da bola
      g.ballX += g.ballVX;
      g.ballY += g.ballVY;

      // Colisão com paredes laterais
      if (g.ballX - g.ballRadius < 0 || g.ballX + g.ballRadius > g.canvasWidth) {
        g.ballVX *= -1;
      }

      // Colisão com paleta da IA (Topo)
      if (g.ballY - g.ballRadius < g.paddleHeight) {
        if (g.ballX > g.aiX && g.ballX < g.aiX + g.paddleWidth) {
          g.ballVY = Math.abs(g.ballVY); // Rebate para baixo
          g.ballVX += (g.ballX - (g.aiX + g.paddleWidth / 2)) * 0.2; // Adiciona ângulo
        } else {
          // Ponto do Jogador
          setScore(s => ({ ...s, player: s.player + 1 }));
          resetBall();
        }
      }

      // Colisão com paleta do Jogador (Base)
      if (g.ballY + g.ballRadius > g.canvasHeight - g.paddleHeight) {
        if (g.ballX > g.playerX && g.ballX < g.playerX + g.paddleWidth) {
          g.ballVY = -Math.abs(g.ballVY); // Rebate para cima
          g.ballVX += (g.ballX - (g.playerX + g.paddleWidth / 2)) * 0.2; // Adiciona ângulo
        } else {
          // Ponto da IA
          setScore(s => ({ ...s, ai: s.ai + 1 }));
          resetBall();
        }
      }
    };

    const resetBall = () => {
      const g = gameRef.current;
      g.ballX = g.canvasWidth / 2;
      g.ballY = g.canvasHeight / 2;
      g.ballVX = (Math.random() > 0.5 ? 4 : -4);
      g.ballVY = -4;
    };

    const draw = () => {
      const g = gameRef.current;
      ctx.clearRect(0, 0, g.canvasWidth, g.canvasHeight);

      // Fundo Neon
      ctx.fillStyle = '#111827';
      ctx.fillRect(0, 0, g.canvasWidth, g.canvasHeight);

      // Linha central
      ctx.setLineDash([10, 10]);
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)';
      ctx.beginPath();
      ctx.moveTo(0, g.canvasHeight / 2);
      ctx.lineTo(g.canvasWidth, g.canvasHeight / 2);
      ctx.stroke();
      ctx.setLineDash([]);

      // Paleta IA
      ctx.fillStyle = '#ef4444';
      ctx.shadowBlur = 15;
      ctx.shadowColor = '#ef4444';
      ctx.fillRect(g.aiX, 0, g.paddleWidth, g.paddleHeight);

      // Paleta Jogador
      ctx.fillStyle = '#3b82f6';
      ctx.shadowBlur = 15;
      ctx.shadowColor = '#3b82f6';
      ctx.fillRect(g.playerX, g.canvasHeight - g.paddleHeight, g.paddleWidth, g.paddleHeight);

      // Bola
      ctx.fillStyle = '#fff';
      ctx.shadowBlur = 10;
      ctx.shadowColor = '#fff';
      ctx.beginPath();
      ctx.arc(g.ballX, g.ballY, g.ballRadius, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;
    };

    const loop = () => {
      update();
      draw();
      animationId = requestAnimationFrame(loop);
    };

    if (permissionGranted) {
      animationId = requestAnimationFrame(loop);
    }

    return () => cancelAnimationFrame(animationId);
  }, [permissionGranted]);

  return (
    <div className="fixed inset-0 bg-black z-50 flex flex-col items-center justify-center p-4">
      {permissionGranted === null && (
        <div className="text-center p-8 bg-gray-800 rounded-2xl border border-blue-500 max-w-sm">
          <ArrowLeftRight className="w-16 h-16 text-blue-400 mx-auto mb-4 animate-bounce" />
          <h2 className="text-2xl font-bold text-white mb-4">Controle por Sensor</h2>
          <p className="text-gray-400 mb-8 uppercase text-sm">
            Este jogo usa a bússola/giroscópio do seu celular para mover a paleta. Por favor, autorize o acesso.
          </p>
          <button onClick={requestPermission} className="w-full py-4 bg-blue-600 text-white font-bold rounded-xl uppercase shadow-lg shadow-blue-500/30">
            AUTORIZAR SENSORES
          </button>
        </div>
      )}

      {permissionGranted === false && (
        <div className="text-center">
          <p className="text-red-500 font-bold mb-4 uppercase">Acesso negado aos sensores.</p>
          <button onClick={onExit} className="px-8 py-3 bg-gray-700 text-white rounded-full uppercase">Voltar</button>
        </div>
      )}

      {permissionGranted === true && (
        <>
          <div className="absolute top-8 left-0 w-full flex justify-around items-center pointer-events-none z-10">
            <div className="text-center">
              <div className="text-xs text-red-400 font-bold uppercase mb-1">IA</div>
              <div className="text-5xl font-black text-white brand-font">{score.ai}</div>
            </div>
            <div className="text-center">
              <div className="text-xs text-blue-400 font-bold uppercase mb-1">VOCÊ</div>
              <div className="text-5xl font-black text-white brand-font">{score.player}</div>
            </div>
          </div>

          <div className="relative w-full max-w-[500px] aspect-[3/4] border-4 border-gray-700 rounded-xl overflow-hidden shadow-2xl shadow-blue-500/10 bg-gray-900">
            <canvas ref={canvasRef} className="w-full h-full block" width={600} height={800} />

            <div className="absolute bottom-10 left-0 w-full text-center pointer-events-none">
              <p className="text-blue-400/30 font-mono text-xs uppercase animate-pulse">Gire o celular como um volante</p>
            </div>
          </div>

          <button onClick={onExit} className="mt-8 p-4 bg-gray-800 rounded-full border border-gray-600 text-white hover:bg-gray-700 transition-colors shadow-xl">
            <X className="w-8 h-8" />
          </button>
        </>
      )}
    </div>
  );
};

export default PongGame;

